// Cyrus Model Studio (Layer 1): the SCENE MODEL the viewport draws and the brush picks on. Pure + client-safe.
// One flat triangle soup per model (positions, UVs, part + face per triangle) built from what a project really holds:
//   creature  a RigSpec (lib/cyrus/creature/spec.ts) + its box-UV skin layout (lib/cyrus/creature/compile.ts layoutSkin,
//             computed on the server: compile.ts is server-only). Rest pose. Face orientation = the creature preview
//             renderer's faceCorners (lib/cyrus/creature/preview.ts), so a painted texel lands where the compiler's
//             skin puts it. Units: Blockbench (16 = one block), times spec.scale.
//   item3d    a flat item texture extruded like vanilla item/generated (front + back + open edges per opaque texel),
//             model units 0..16 (x right, y up), z 7.5..8.5: exactly the geometry the item model display transforms
//             (lib/cyrus/textures/display.ts applyDisplay) are written for.
//   mesh      a glTF 2.0 mesh (./gltf.ts), node transforms applied, TEXCOORD_0. Units as authored (glTF: metres).
// ItemCuboidSpec (3D cuboid items, plan F3) does not exist yet; when it lands it becomes one more builder here.
import type { RigSpec, Face } from "../creature/spec";
import type { SkinLayout } from "../creature/compile";
import { apply4, mul4, Rx4, Ry4, Rz4, S4, T4, I4, type M4, type V2, type V3 } from "./math";
import type { GltfParsed } from "./gltf";

export const SCENE_FACES = ["north", "east", "south", "west", "up", "down", "front", "back", "edge", "mesh"] as const;
export type SceneFace = (typeof SCENE_FACES)[number];
export type ScenePart = { name: string; kind: "cube" | "item" | "mesh"; bone?: string; index?: number };
/** A UV region in texels as row spans [y, x0, x1) (a cube face is one rectangle; an item side is its silhouette). */
export type Spans = [number, number, number][];
export type ModelKind = "creature" | "item3d" | "mesh";

export type ModelScene = {
  kind: ModelKind;
  name: string;
  /** the painted texture's size in texels; wrap = glTF REPEAT */
  tex: { w: number; h: number; wrap: boolean };
  /** 9 floats per triangle */
  pos: Float32Array;
  /** 6 floats per triangle, (0,0) = top-left of the texture */
  uv: Float32Array;
  /** part index per triangle */
  part: Uint16Array;
  /** SCENE_FACES index per triangle */
  face: Uint8Array;
  parts: ScenePart[];
  /** `${part}:${face}` -> the face's UV region (cubes and items; meshes compute islands on demand, ./pick.ts) */
  regions: Record<string, Spans>;
  bounds: { min: V3; max: V3 };
  triCount: number;
  /** the model-space plane x = mirrorX the Mirror (X) tool reflects across */
  mirrorX: number;
  /** item3d only: model point the hand holds (lib/cyrus/textures/display.ts gripPoint), model units */
  grip?: V2;
};

const faceIdx = (f: SceneFace) => SCENE_FACES.indexOf(f);

class Builder {
  pos: number[] = []; uv: number[] = []; part: number[] = []; face: number[] = [];
  /** quad TL, TR, BR, BL with uv corners in the same order; two triangles TL-TR-BR, TL-BR-BL */
  quad(p: [V3, V3, V3, V3], u: [V2, V2, V2, V2], part: number, f: SceneFace) {
    for (const [a, b, c] of [[0, 1, 2], [0, 2, 3]]) {
      this.pos.push(...p[a], ...p[b], ...p[c]);
      this.uv.push(...u[a], ...u[b], ...u[c]);
      this.part.push(part); this.face.push(faceIdx(f));
    }
  }
  done(kind: ModelKind, name: string, tex: ModelScene["tex"], parts: ScenePart[], regions: Record<string, Spans>, mirrorX: number | null, extra: Partial<ModelScene> = {}): ModelScene {
    const pos = Float32Array.from(this.pos);
    let min: V3 = [Infinity, Infinity, Infinity], max: V3 = [-Infinity, -Infinity, -Infinity];
    for (let i = 0; i < pos.length; i += 3) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], pos[i + k]); max[k] = Math.max(max[k], pos[i + k]); }
    if (!pos.length) { min = [0, 0, 0]; max = [0, 0, 0]; }
    return { kind, name, tex, pos, uv: Float32Array.from(this.uv), part: Uint16Array.from(this.part), face: Uint8Array.from(this.face), parts, regions, bounds: { min, max }, triCount: pos.length / 9, mirrorX: mirrorX ?? (min[0] + max[0]) / 2, ...extra };
  }
}

const rect = (x: number, y: number, w: number, h: number): Spans => Array.from({ length: h }, (_, j) => [y + j, x, x + w] as [number, number, number]);

/** Rest-pose bone world matrices, the same composition as lib/cyrus/creature/preview.ts poseMatrices (Euler ZYX about the pivot). */
export function restMatrices(spec: Pick<RigSpec, "bones">): Map<string, M4> {
  const out = new Map<string, M4>();
  const world = (name: string, depth = 0): M4 => {
    const hit = out.get(name);
    if (hit) return hit;
    const b = spec.bones.find((x) => x.name === name);
    if (!b || depth > 64) return I4();
    const r = b.rotation ?? [0, 0, 0];
    const [px, py, pz] = b.pivot;
    const local = mul4(T4(px, py, pz), mul4(Rz4(r[2]), mul4(Ry4(r[1]), mul4(Rx4(r[0]), T4(-px, -py, -pz)))));
    const m = b.parent ? mul4(world(b.parent, depth + 1), local) : local;
    out.set(name, m);
    return m;
  };
  for (const b of spec.bones) world(b.name);
  return out;
}

/** Face corners TL, TR, BL as seen from outside (= lib/cyrus/creature/preview.ts faceCorners). */
export function cubeFaceCorners(f: Face, a: V3, b: V3): { tl: V3; tr: V3; bl: V3 } {
  const [x0, y0, z0] = a, [x1, y1, z1] = b;
  switch (f) {
    case "north": return { tl: [x1, y1, z0], tr: [x0, y1, z0], bl: [x1, y0, z0] };
    case "south": return { tl: [x0, y1, z1], tr: [x1, y1, z1], bl: [x0, y0, z1] };
    case "east": return { tl: [x1, y1, z1], tr: [x1, y1, z0], bl: [x1, y0, z1] };
    case "west": return { tl: [x0, y1, z0], tr: [x0, y1, z1], bl: [x0, y0, z0] };
    case "up": return { tl: [x0, y1, z0], tr: [x1, y1, z0], bl: [x0, y1, z1] };
    case "down": return { tl: [x0, y0, z1], tr: [x1, y0, z1], bl: [x0, y0, z0] };
  }
}
const CUBE_FACES: readonly Face[] = ["north", "east", "south", "west", "up", "down"];

/** A creature (expanded RigSpec + its skin layout) as a scene in its rest pose. */
export function sceneFromRig(spec: Pick<RigSpec, "name" | "bones" | "scale">, layout: SkinLayout): ModelScene {
  const B = new Builder();
  const mats = restMatrices(spec);
  const parts: ScenePart[] = [];
  const regions: Record<string, Spans> = {};
  const n = layout.size;
  const s = spec.scale;
  for (const cl of layout.cubes) {
    const bone = spec.bones.find((b) => b.name === cl.bone);
    const c = bone?.cubes[cl.index];
    if (!bone || !c) continue;
    const pi = parts.length;
    parts.push({ name: `${cl.bone}#${cl.index}`, kind: "cube", bone: cl.bone, index: cl.index });
    const M = mul4(S4(s, s, s), mats.get(bone.name)!);
    const inf = c.inflate;
    const a: V3 = [c.from[0] - inf, c.from[1] - inf, c.from[2] - inf], b: V3 = [c.to[0] + inf, c.to[1] + inf, c.to[2] + inf];
    for (const f of CUBE_FACES) {
      const fc = cubeFaceCorners(f, a, b);
      const br: V3 = [fc.tr[0] + fc.bl[0] - fc.tl[0], fc.tr[1] + fc.bl[1] - fc.tl[1], fc.tr[2] + fc.bl[2] - fc.tl[2]];
      const r = cl.faces[f];
      B.quad([apply4(M, fc.tl), apply4(M, fc.tr), apply4(M, br), apply4(M, fc.bl)],
        [[r.x / n, r.y / n], [(r.x + r.w) / n, r.y / n], [(r.x + r.w) / n, (r.y + r.h) / n], [r.x / n, (r.y + r.h) / n]], pi, f);
      regions[`${pi}:${faceIdx(f)}`] = rect(r.x, r.y, r.w, r.h);
    }
  }
  return B.done("creature", spec.name, { w: n, h: n, wrap: false }, parts, regions, 0);
}

export type Img = { w: number; h: number; px: Uint8ClampedArray };

/**
 * A flat item extruded like vanilla item/generated, from its (composite) albedo. Front (z 8.5) and back (z 7.5) are
 * full 16x16 quads (alpha-tested when drawn; ./pick.ts skips transparent texels for items); each opaque texel with a
 * transparent or missing neighbour gets an edge quad whose UV is the texel centre (the game colours edges that way).
 */
export function sceneFromItem(name: string, albedo: Img, grip?: V2): ModelScene {
  const n = albedo.w, k = 16 / n, B = new Builder();
  const op = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && albedo.px[(y * n + x) * 4 + 3] > 0;
  const parts: ScenePart[] = [{ name, kind: "item" }];
  B.quad([[0, 16, 8.5], [16, 16, 8.5], [16, 0, 8.5], [0, 0, 8.5]], [[0, 0], [1, 0], [1, 1], [0, 1]], 0, "front");
  // the back as seen from behind: TL is model (16, 16); the texel at model x is the same texel as on the front
  B.quad([[16, 16, 7.5], [0, 16, 7.5], [0, 0, 7.5], [16, 0, 7.5]], [[1, 0], [0, 0], [0, 1], [1, 1]], 0, "back");
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (!op(x, y)) continue;
    const c: V2 = [(x + 0.5) / n, (y + 0.5) / n];
    const u: [V2, V2, V2, V2] = [c, c, c, c];
    const x0 = x * k, x1 = (x + 1) * k, y0 = 16 - (y + 1) * k, y1 = 16 - y * k;
    if (!op(x, y - 1)) B.quad([[x0, y1, 7.5], [x1, y1, 7.5], [x1, y1, 8.5], [x0, y1, 8.5]], u, 0, "edge");
    if (!op(x, y + 1)) B.quad([[x0, y0, 8.5], [x1, y0, 8.5], [x1, y0, 7.5], [x0, y0, 7.5]], u, 0, "edge");
    if (!op(x - 1, y)) B.quad([[x0, y1, 7.5], [x0, y1, 8.5], [x0, y0, 8.5], [x0, y0, 7.5]], u, 0, "edge");
    if (!op(x + 1, y)) B.quad([[x1, y1, 8.5], [x1, y1, 7.5], [x1, y0, 7.5], [x1, y0, 8.5]], u, 0, "edge");
  }
  // the item's sides: the silhouette (opaque texels) as spans
  const sil: Spans = [];
  for (let y = 0; y < n; y++) { let x = 0; while (x < n) { if (!op(x, y)) { x++; continue; } const s0 = x; while (x < n && op(x, y)) x++; sil.push([y, s0, x]); } }
  return B.done("item3d", name, { w: n, h: n, wrap: false }, parts, { [`0:${faceIdx("front")}`]: sil, [`0:${faceIdx("back")}`]: sil }, 8, grip ? { grip } : {});
}

/** A parsed glTF as a scene (world-space triangles of the default scene). Meshes without UVs are skipped. */
export function sceneFromGltf(name: string, g: GltfParsed, texSize?: { w: number; h: number }): ModelScene {
  const B = new Builder();
  const parts: ScenePart[] = [];
  for (const m of g.meshes) {
    if (!m.uv) continue;
    const pi = parts.length;
    parts.push({ name: m.name, kind: "mesh" });
    for (let t = 0; t < m.idx.length; t += 3) {
      const ps: V3[] = [], us: V2[] = [];
      for (let k = 0; k < 3; k++) {
        const i = m.idx[t + k];
        ps.push(apply4(m.matrix, [m.pos[i * 3], m.pos[i * 3 + 1], m.pos[i * 3 + 2]]));
        us.push([m.uv[i * 2], m.uv[i * 2 + 1]]);
      }
      B.pos.push(...ps[0], ...ps[1], ...ps[2]);
      B.uv.push(...us[0], ...us[1], ...us[2]);
      B.part.push(pi); B.face.push(faceIdx("mesh"));
    }
  }
  const img = g.baseColorImage !== null ? g.images[g.baseColorImage] : null;
  const w = texSize?.w ?? img?.w ?? 1024, h = texSize?.h ?? img?.h ?? 1024;
  return B.done("mesh", name, { w, h, wrap: g.wrap }, parts, {}, null);
}

export const sceneFaceName = (s: ModelScene, tri: number): SceneFace => SCENE_FACES[s.face[tri]];
export const triPos = (s: ModelScene, t: number): [V3, V3, V3] => [0, 1, 2].map((k) => [s.pos[t * 9 + k * 3], s.pos[t * 9 + k * 3 + 1], s.pos[t * 9 + k * 3 + 2]] as V3) as [V3, V3, V3];
export const triUv = (s: ModelScene, t: number): [V2, V2, V2] => [0, 1, 2].map((k) => [s.uv[t * 6 + k * 2], s.uv[t * 6 + k * 2 + 1]] as V2) as [V2, V2, V2];
// Model Studio L2: the GPU-free scene + camera maths the editor UI draws and picks with. Pure + client-safe.
// buildScene(doc, pose) -> posed cube faces (world space) + bone pivots; project() / pickCube() / axisDrag() are the
// camera half. The layer-1 three.js viewport (feature/cyrus-r16-viewport, not merged when this was written) can
// consume the same EditorScene through components/cyrus/modelstudio/editor/viewport-adapter.ts.
import type { Face } from "../../creature/spec";
import { FACES } from "../../creature/spec";
import type { ModelDoc, Vec3 } from "./doc";
import { apply, boneMatrices, cubeMatrix, mul, Rx, Ry, samplePose, type M4 } from "./pose";

export type SceneFace = { cube: string; bone: string; face: Face; pts: [Vec3, Vec3, Vec3, Vec3]; normal: Vec3; color: string; glow: boolean };
export type SceneBone = { id: string; name: string; at: Vec3; parentAt: Vec3 | null; tag: string };
export type EditorScene = { faces: SceneFace[]; bones: SceneBone[]; min: Vec3; max: Vec3; matrices: Map<string, M4> };

const hex = (c: string) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const toHex = (rgb: number[]) => `#${rgb.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")).join("")}`;
export const mixHex = (a: string, b: string, t: number) => toHex(hex(a).map((v, i) => v + (hex(b)[i] - v) * t));

/** Face corners in the compiler's order (top-left, top-right, bottom-right, bottom-left seen from outside). */
function corners(f: Face, a: Vec3, b: Vec3): { pts: [Vec3, Vec3, Vec3, Vec3]; n: Vec3 } {
  const [x0, y0, z0] = a, [x1, y1, z1] = b;
  switch (f) {
    case "north": return { pts: [[x1, y1, z0], [x0, y1, z0], [x0, y0, z0], [x1, y0, z0]], n: [0, 0, -1] };
    case "south": return { pts: [[x0, y1, z1], [x1, y1, z1], [x1, y0, z1], [x0, y0, z1]], n: [0, 0, 1] };
    case "east": return { pts: [[x1, y1, z1], [x1, y1, z0], [x1, y0, z0], [x1, y0, z1]], n: [1, 0, 0] };
    case "west": return { pts: [[x0, y1, z0], [x0, y1, z1], [x0, y0, z1], [x0, y0, z0]], n: [-1, 0, 0] };
    case "up": return { pts: [[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], n: [0, 1, 0] };
    case "down": return { pts: [[x0, y0, z1], [x1, y0, z1], [x1, y0, z0], [x0, y0, z0]], n: [0, -1, 0] };
  }
}

export function buildScene(doc: ModelDoc, opts: { clip?: string | null; time?: number; showHidden?: boolean } = {}): EditorScene {
  const pose = samplePose(doc, opts.clip ?? null, opts.time ?? 0);
  const mats = boneMatrices(doc, pose);
  const hiddenBones = new Set<string>();
  for (const b of doc.bones) if (b.hidden) { const stack = [b.id]; while (stack.length) { const id = stack.pop()!; if (hiddenBones.has(id)) continue; hiddenBones.add(id); for (const c of doc.bones) if (c.parent === id) stack.push(c.id); } }
  const faces: SceneFace[] = [];
  const min: Vec3 = [Infinity, Infinity, Infinity], max: Vec3 = [-Infinity, -Infinity, -Infinity];
  const glowOf = new Map(doc.bones.map((b) => [b.id, b.tag === "glow"]));
  for (const c of doc.cubes) {
    if (!mats.has(c.bone)) continue;
    if (!opts.showHidden && (c.hidden || hiddenBones.has(c.bone))) continue;
    const M = cubeMatrix(doc, mats, c.id);
    const inf = c.inflate;
    const a: Vec3 = [c.from[0] - inf, c.from[1] - inf, c.from[2] - inf], b: Vec3 = [c.to[0] + inf, c.to[1] + inf, c.to[2] + inf];
    const base = doc.palette[c.material] ?? "#888888";
    const fade = c.shade === "fade" && c.fadeTo ? doc.palette[c.fadeTo] ?? base : null;
    const o = apply(M, [0, 0, 0]);
    for (const f of FACES) {
      const k = corners(f, a, b);
      const pts = k.pts.map((p) => apply(M, p)) as [Vec3, Vec3, Vec3, Vec3];
      const nn = apply(M, k.n).map((v, i) => v - o[i]);
      const l = Math.hypot(nn[0], nn[1], nn[2]) || 1;
      const color = f === "up" ? mixHex(base, "#ffffff", 0.16) : f === "down" ? mixHex(fade ?? base, "#0b0a14", 0.24) : fade ? mixHex(base, fade, 0.5) : base;
      faces.push({ cube: c.id, bone: c.bone, face: f, pts, normal: [nn[0] / l, nn[1] / l, nn[2] / l], color, glow: glowOf.get(c.bone) ?? false });
      for (const p of pts) for (let i = 0; i < 3; i++) { min[i] = Math.min(min[i], p[i]); max[i] = Math.max(max[i], p[i]); }
    }
  }
  if (!faces.length) { min.splice(0, 3, -8, 0, -8); max.splice(0, 3, 8, 16, 8); }
  const at = new Map(doc.bones.map((b) => [b.id, mats.has(b.id) ? apply(mats.get(b.id)!, b.pivot) : ([...b.pivot] as Vec3)]));
  const bones: SceneBone[] = doc.bones.map((b) => ({ id: b.id, name: b.name, at: at.get(b.id)!, parentAt: b.parent ? at.get(b.parent) ?? null : null, tag: b.tag }));
  return { faces, bones, min, max, matrices: mats };
}

// ------------------------------------------------------------------------------------------------------ camera ----
export type Camera = { yaw: number; pitch: number; zoom: number; target: Vec3; ortho: boolean; width: number; height: number; /** screen-space nudge of the centre (room for overlays) */ offsetY?: number };
export type Projected = { x: number; y: number; z: number };

/** A camera that frames the scene: yaw 0 = looking at the creature's face (from -z), slightly from above. */
export function fitCamera(s: Pick<EditorScene, "min" | "max">, width: number, height: number, view: "persp" | "front" | "side" = "persp"): Camera {
  const target: Vec3 = [(s.min[0] + s.max[0]) / 2, (s.min[1] + s.max[1]) / 2, (s.min[2] + s.max[2]) / 2];
  const ext = Math.max(s.max[0] - s.min[0], s.max[1] - s.min[1], s.max[2] - s.min[2], 8);
  const zoom = (Math.min(width, height) * 0.66) / ext;
  if (view === "front") return { yaw: 0, pitch: 0, zoom, target, ortho: true, width, height };
  if (view === "side") return { yaw: 90, pitch: 0, zoom, target, ortho: true, width, height };
  return { yaw: 32, pitch: -18, zoom, target, ortho: false, width, height };
}

const DIST = 90; // perspective eye distance in model units (fixed: zoom scales the picture, not the eye)
export function viewMatrix(c: Camera): M4 { return mul(Rx(c.pitch), Ry(c.yaw)); }
/** World point -> screen pixels (+ camera depth; larger = farther). Camera sits on -z looking toward +z. */
export function project(c: Camera, p: readonly number[], V: M4 = viewMatrix(c)): Projected {
  const q = apply(V, [p[0] - c.target[0], p[1] - c.target[1], p[2] - c.target[2]]);
  const k = c.ortho ? c.zoom : (c.zoom * DIST) / Math.max(1, DIST + q[2]);
  return { x: c.width / 2 - q[0] * k, y: c.height / 2 + (c.offsetY ?? 0) - q[1] * k, z: q[2] };
}
/** Camera-space normal z < 0 = the face points at the camera. */
export const facing = (c: Camera, n: Vec3, V: M4 = viewMatrix(c)) => apply(V, n)[2] < -1e-6;

function inside(pts: Projected[], x: number, y: number): boolean {
  let hit = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const a = pts[i], b = pts[j];
    if ((a.y > y) !== (b.y > y) && x < ((b.x - a.x) * (y - a.y)) / (b.y - a.y) + a.x) hit = !hit;
  }
  return hit;
}

/** Visible faces back to front (painter's order) with their projected corners. */
export function drawList(s: EditorScene, c: Camera): { f: SceneFace; pts: Projected[]; depth: number }[] {
  const V = viewMatrix(c);
  return s.faces.filter((f) => facing(c, f.normal, V)).map((f) => {
    const pts = f.pts.map((p) => project(c, p, V));
    return { f, pts, depth: pts.reduce((a, p) => a + p.z, 0) / 4 };
  }).sort((a, b) => b.depth - a.depth);
}

/** The cube under a screen point (nearest visible face wins), or null. */
export function pickCube(s: EditorScene, c: Camera, x: number, y: number): string | null {
  const list = drawList(s, c);
  for (let i = list.length - 1; i >= 0; i--) if (inside(list[i].pts, x, y)) return list[i].f.cube;
  return null;
}

/** A drag of (dx, dy) screen pixels along world axis 0/1/2 through `origin` -> model units along that axis. */
export function axisDrag(c: Camera, origin: Vec3, axis: 0 | 1 | 2, dx: number, dy: number): number {
  const a = project(c, origin), tip: Vec3 = [...origin] as Vec3;
  tip[axis] += 1;
  const b = project(c, tip);
  const sx = b.x - a.x, sy = b.y - a.y;
  const l2 = sx * sx + sy * sy;
  if (l2 < 1e-6) return 0; // the axis points at the camera
  return (dx * sx + dy * sy) / l2;
}
// Cyrus Model Studio: the PLAYBACK CLOCK and scene-time API (game-agnostic hook points for animation and effects:
// creature walk cycles, a gun's cock / fire / reload, vehicle doors, explosions, fire, water...). Pure + client-safe,
// deterministic: time only moves when tick() / seek() say so (the viewport ticks it from requestAnimationFrame while
// playing; tests and the server preview set it directly), so "the scene at time t" is reproducible everywhere.
// Nothing here animates anything: providers (a rig's clips, an effect) plug in through ./pose.ts.
export type ClockState = { time: number; playing: boolean; speed: number; loop: boolean; start: number; end: number };
export type ClockListener = (s: Readonly<ClockState>) => void;

