// Cyrus timeline: the PLAYBACK CLOCK (play, pause, scrub, loop, speed) a viewport or a live simulation drives.
// Pure state machine: the host (requestAnimationFrame, a server-side bake, a test) feeds it elapsed seconds; it
// returns the new state, the time span it covered and every instant (event, cue, burst, state change) crossed, so
// sound cues and effects fire in sync and deterministically. No timers in here.
import { firedBetween, type Fired } from "./sampler";
import type { Clip } from "./types";

export const MIN_SPEED = 0.1;
export const MAX_SPEED = 4;

export type Clock = { time: number; length: number; loop: boolean; speed: number; playing: boolean; /** total looped time, for wrap-aware event firing */ elapsed: number };
export type Tick = { clock: Clock; fired: Fired[]; wrapped: number; ended: boolean };

export const clockInit = (clip: Pick<Clip, "length" | "loop"> | null, speed = 1): Clock => ({ time: 0, length: clip?.length ?? 1, loop: clip?.loop ?? false, speed, playing: false, elapsed: 0 });
/** Point the clock at another clip (keeps speed; rewinds). */
export const clockLoad = (c: Clock, clip: Pick<Clip, "length" | "loop">): Clock => ({ ...c, time: 0, elapsed: 0, length: clip.length, loop: clip.loop, playing: false });
/** Play from where it is (a finished one-shot restarts from 0). */
export const clockPlay = (c: Clock): Clock => ({ ...c, playing: true, ...(!c.loop && c.time >= c.length ? { time: 0, elapsed: 0 } : {}) });
export const clockPause = (c: Clock): Clock => ({ ...c, playing: false });
export const clockToggle = (c: Clock): Clock => (c.playing ? clockPause(c) : clockPlay(c));
/** Jump to a time (clamped to the clip); scrubbing never fires instants. */
export const clockScrub = (c: Clock, time: number): Clock => { const t = Math.max(0, Math.min(c.length, Number.isFinite(time) ? time : 0)); return { ...c, time: t, elapsed: t }; };
export const clockSpeed = (c: Clock, speed: number): Clock => ({ ...c, speed: Math.max(MIN_SPEED, Math.min(MAX_SPEED, Number.isFinite(speed) ? speed : 1)) });
export const clockLoop = (c: Clock, loop: boolean): Clock => ({ ...c, loop });

/** Advance a playing clock by `dt` real seconds (x speed). A one-shot clip stops at its end. */
export function clockTick(c: Clock, dt: number, clip?: Clip): Tick {
  if (!c.playing || !(dt > 0)) return { clock: c, fired: [], wrapped: 0, ended: false };
  const step = dt * c.speed;
  const from = c.elapsed, to = c.elapsed + step;
  if (!c.loop && c.time + step >= c.length) {
    const end = c.elapsed + (c.length - c.time);
    return { clock: { ...c, time: c.length, elapsed: end, playing: false }, fired: clip ? firedBetween(clip, from, end, { includeStart: from === 0 }) : [], wrapped: 0, ended: true };
  }
  const time = c.loop ? to % c.length : c.time + step;
  const wrapped = c.loop ? Math.floor(to / c.length) - Math.floor(from / c.length) : 0;
  return { clock: { ...c, time, elapsed: to }, fired: clip ? firedBetween(clip, from, to, { includeStart: from === 0 }) : [], wrapped, ended: false };
}

