156	    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
157	    t.magFilter = this.pixel ? THREE.NearestFilter : THREE.LinearFilter;
158	    t.minFilter = this.pixel ? THREE.NearestFilter : THREE.LinearMipmapLinearFilter;
159	    t.generateMipmaps = !this.pixel;
160	    t.flipY = false;
161	    t.wrapS = t.wrapT = THREE.RepeatWrapping;
162	    t.needsUpdate = true;
163	    return t;
164	  }
