166	  /** Upload channel composites (albedo always; the others only when painted). */
167	  setMaps(maps: ViewMaps) {
168	    const THREE = this.T;
169	    for (const [k, img] of Object.entries(maps) as [PaintChannel, Img | undefined][]) {
170	      if (!img) continue;
171	      const cur = this.tex[k];
172	      if (cur && cur.image.width === img.w && cur.image.height === img.h) { (cur.image.data as Uint8Array).set(img.px); cur.needsUpdate = true; continue; }
173	      cur?.dispose();
174	      this.tex[k] = this.dataTex(img, k === "albedo" || k === "emissive");
175	    }
176	    const m = this.lit;
177	    m.map = this.tex.albedo ?? null;
178	    if (!this.pixel) {
179	      // roughness reads G and metalness B in three.js: the composites are grey, so every channel holds the value
180	      m.normalMap = this.tex.normal ?? null;
181	      m.roughnessMap = this.tex.roughness ?? null; m.roughness = 1;
182	      m.metalnessMap = this.tex.metallic ?? null; m.metalness = this.tex.metallic ? 1 : 0;
183	      m.emissiveMap = this.tex.emissive ?? null; m.emissive = new THREE.Color(this.tex.emissive ? 0xffffff : 0x000000);
184	    }
185	    m.needsUpdate = true;
186	    this.requestRender();
187	  }
