192	    if (d.kind === "lit") { for (const m of this.parts) m.material = this.lit; this.requestRender(); return; }
193	    const cur = this.viewTex;
194	    if (cur && cur.image.width === d.img.w && cur.image.height === d.img.h) { (cur.image.data as Uint8Array).set(d.img.px); cur.needsUpdate = true; }
195	    else { cur?.dispose(); this.viewTex = this.dataTex(d.img, true); }
196	    this.flat.map = this.viewTex; this.flat.needsUpdate = true;
