214	  // ------------------------------------------------------------------ camera
215	  private bounds(): { c: V3; r: number } {
216	    if (!this.mesh) return { c: [0, 0, 0], r: 1 };
217	    this.mesh.updateMatrixWorld(true);
218	    const s = new this.T.Box3().setFromObject(this.mesh).getBoundingSphere(new this.T.Sphere());
219	    return { c: [s.center.x, s.center.y, s.center.z], r: Math.max(1e-3, s.radius) };
220	  }
221	  fit(_s?: ModelScene) {
222	    if (this.rig) { this.applyRigCamera(); return; }
223	    const { c, r } = this.bounds();
224	    const el = this.canvas.getBoundingClientRect(), asp = Math.min(1, (el.width || 1) / (el.height || 1));
225	    this.cam = { ...this.cam, target: c, dist: (r / Math.sin(((this.cam.fov / 2) * Math.PI) / 180)) * (1.3 / asp) };
226	    this.syncCamera();
227	  }
228	  /** creatures face north (-z): their presets turn 180 so "front" shows the face */
229	  facing = 0;
230	  preset(p: CamPreset) { this.cam = { ...this.cam, ...PRESET[p], yaw: PRESET[p].yaw + this.facing }; this.syncCamera(); }
231	  zoom(k: number) { this.cam = { ...this.cam, dist: Math.max(0.05, Math.min(500, this.cam.dist * k)) }; this.syncCamera(); }
232	
233	  private syncCamera() {
234	    const THREE = this.T;
235	    if (!(this.camera instanceof THREE.PerspectiveCamera)) this.camera = new THREE.PerspectiveCamera(this.cam.fov, 1, 0.01, 1000);
236	    const cam = this.camera as THREE_NS.PerspectiveCamera;
237	    const e = camEye(this.cam);
238	    cam.fov = this.cam.fov;
239	    cam.near = Math.max(0.001, this.cam.dist / 200); cam.far = this.cam.dist * 50 + 10;
240	    cam.position.set(e[0], e[1], e[2]);
241	    cam.up.set(0, 1, 0);
242	    cam.lookAt(this.cam.target[0], this.cam.target[1], this.cam.target[2]);
243	    this.resize();
244	    this.events.onCamera?.(this.cam);
245	  }
