247	  /** The ray through a client point (same maths as the pure pick). */
248	  rayAt(clientX: number, clientY: number): Ray {
249	    const r = this.canvas.getBoundingClientRect();
250	    return rayFromOrbit(this.cam, clientX - r.left, clientY - r.top, r.width || 1, r.height || 1);
251	  }
