253	  // ------------------------------------------------------------------ in-game context (read-only panel)
254	  setRig(rig: ContextRig | null, light: boolean) {
255	    const THREE = this.T;
256	    this.rig = rig;
257	    this.props.clear();
258	    if (this.grid) this.grid.visible = !rig;
259	    if (!this.mesh) return;
260	    if (!rig) { this.mesh.matrixAutoUpdate = true; this.mesh.matrix.identity(); this.mesh.position.set(0, 0, 0); this.mesh.updateMatrix(); this.fit(); return; }
261	    const M = new THREE.Matrix4().fromArray(rig.model as M4);
262	    this.mesh.matrixAutoUpdate = false; this.mesh.matrix.copy(M); this.mesh.matrixWorldNeedsUpdate = true;
263	    for (const p of rig.props) this.props.add(this.propMesh(p, light));
264	    this.applyRigCamera();
265	  }
266	
267	  private propMesh(p: Prop, light: boolean): THREE_NS.Object3D {
268	    const THREE = this.T;
269	    const col: Record<Prop["kind"], number> = { glove: 0x6152b8, sleeve: 0x3a2f78, slot: light ? 0xb9b3cc : 0x3a3a48, frame: 0x8a5a32, shadow: 0x000000, head: 0x8676dc, body: 0x4a3e94, shelf: 0x7a5434 };
270	    const mat = new THREE.MeshStandardMaterial({ color: col[p.kind], roughness: 1, metalness: 0, transparent: p.kind === "shadow" || p.kind === "glove", opacity: p.kind === "shadow" ? 0.35 : p.kind === "glove" ? 0.92 : 1 });
271	    const g = p.kind === "shadow" ? new THREE.CylinderGeometry(p.size[0] / 2, p.size[0] / 2, 0.005, 24) : new THREE.BoxGeometry(...p.size);
272	    const m = new THREE.Mesh(g, mat);
273	    if (p.kind === "sleeve" && p.dir) {
274	      const d = new THREE.Vector3(...p.dir).normalize();
275	      m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
276	      m.position.set(p.center[0] + (d.x * p.size[1]) / 2, p.center[1] + (d.y * p.size[1]) / 2, p.center[2] + (d.z * p.size[1]) / 2);
277	    } else m.position.set(...p.center);
278	    return m;
279	  }
280	
281	  private applyRigCamera() {
282	    const THREE = this.T, rig = this.rig!;
283	    this.scene3.updateMatrixWorld(true); // the rig matrix was just set: world matrices must follow before measuring
284	    const box = new THREE.Box3().setFromObject(this.mesh!);
285	    for (const c of this.props.children) box.expandByObject(c);
286	    if (rig.proj === "persp") {
287	      // first person: the eye stays where the game puts it (rig.cam); the view turns toward the item + hand and the
288	      // field of view is fitted to them (the game shows the item in the lower right corner, mostly off a small panel)
289	      const eye = camEye(rig.cam);
290	      const sphere = box.getBoundingSphere(new THREE.Sphere());
291	      const to = sphere.center.clone().sub(new THREE.Vector3(...eye));
292	      const fov = Math.max(18, Math.min(70, ((2 * Math.atan(sphere.radius / Math.max(1e-3, to.length()))) * 180) / Math.PI * 1.35));
293	      const yaw = (Math.atan2(to.x, to.z) * 180) / Math.PI + 180, pitch = (Math.asin(-to.y / to.length()) * 180) / Math.PI;
294	      this.cam = { yaw, pitch, dist: to.length(), target: [sphere.center.x, sphere.center.y, sphere.center.z], fov };
295	      this.syncCamera();
296	      return;
297	    }
298	    const sphere = box.getBoundingSphere(new THREE.Sphere());
299	    const r = Math.max(1e-3, sphere.radius) * 1.08;
300	    const el = this.canvas.getBoundingClientRect();
301	    const asp = (el.width || 1) / (el.height || 1);
302	    const cam = new THREE.OrthographicCamera(-r * asp, r * asp, r, -r, 0.01, r * 20 + 10);
303	    const yaw = (rig.cam.yaw * Math.PI) / 180, pitch = (rig.cam.pitch * Math.PI) / 180;
304	    const dir = new THREE.Vector3(Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch), Math.cos(pitch) * Math.cos(yaw));
305	    cam.position.copy(sphere.center).addScaledVector(dir, r * 4 + 1);
306	    cam.lookAt(sphere.center);
307	    this.camera = cam;
308	    this.requestRender();
309	  }
