311	  // ------------------------------------------------------------------ input
312	  private bind() {
313	    const c = this.canvas;
314	    c.addEventListener("contextmenu", (e) => e.preventDefault());
315	    c.addEventListener("pointerdown", (e) => {
316	      if (this.rig) return;
317	      c.setPointerCapture(e.pointerId);
318	      const paint = e.button === 0 && !e.altKey && !this.readOnly && !!this.events.onPaintStart && this.events.onPaintStart(this.rayAt(e.clientX, e.clientY), e);
319	      this.drag = { mode: paint ? "paint" : e.button === 1 || e.shiftKey ? "pan" : "orbit", x: e.clientX, y: e.clientY, id: e.pointerId };
320	      this.fpsT0 = performance.now(); this.frames = 0;
321	    });
322	    c.addEventListener("pointermove", (e) => {
323	      const d = this.drag;
324	      if (!d) { this.events.onHover?.(this.rig ? null : this.rayAt(e.clientX, e.clientY), e); return; }
325	      if (d.id !== e.pointerId) return;
326	      if (d.mode === "paint") { this.events.onPaintMove?.(this.rayAt(e.clientX, e.clientY), e); this.events.onHover?.(this.rayAt(e.clientX, e.clientY), e); return; }
327	      const dx = e.clientX - d.x, dy = e.clientY - d.y;
328	      d.x = e.clientX; d.y = e.clientY;
329	      if (d.mode === "orbit") this.cam = { ...this.cam, yaw: this.cam.yaw - dx * 0.45, pitch: Math.max(-89, Math.min(89, this.cam.pitch + dy * 0.45)) };
330	      else {
331	        const k = this.cam.dist / 600, y = (this.cam.yaw * Math.PI) / 180;
332	        const right: V3 = [Math.cos(y), 0, -Math.sin(y)];
333	        this.cam = { ...this.cam, target: [this.cam.target[0] - right[0] * dx * k, this.cam.target[1] + dy * k, this.cam.target[2] - right[2] * dx * k] };
334	      }
335	      this.syncCamera();
336	    });
337	    const end = (e: PointerEvent) => {
338	      const d = this.drag;
339	      if (!d || d.id !== e.pointerId) return;
340	      if (d.mode === "paint") this.events.onPaintEnd?.();
341	      this.drag = null;
342	      const ms = performance.now() - this.fpsT0;
343	      if (ms > 250 && this.frames > 2) this.fps = Math.round((this.frames * 1000) / ms);
344	    };
345	    c.addEventListener("pointerup", end);
346	    c.addEventListener("pointercancel", end);
347	    c.addEventListener("pointerleave", () => { if (!this.drag) this.events.onHover?.(null, null); });
348	    c.addEventListener("wheel", (e) => { if (this.rig) return; e.preventDefault(); this.zoom(Math.exp(e.deltaY * 0.0012)); }, { passive: false });
349	  }
