351	  // ------------------------------------------------------------------ scene time: overrides + overlays (animation / effects hooks)
352	  /** Pose providers (a rig clip, a gun's reload slide...) evaluated at the clock's time; replaces the list. */
353	  setPoseProviders(p: PoseProvider[]) { this.providers = p; const d = Math.max(0, ...p.map((x) => x.duration)); this.clock.setRange(0, d || 1); this.applyTime(); }
354	  /** Fixed per-node transform overrides (model space, part index -> matrix); empty map = rest pose. */
355	  setPartOverrides(o: PartOverrides) {
356	    for (const m of this.parts) { const k = m.userData.part as number; const x = o.get(k); if (x) m.matrix.fromArray(x); else m.matrix.identity(); m.matrixWorldNeedsUpdate = true; }
357	    this.requestRender();
358	  }
359	  /** Attach an overlay layer (particles, helper gizmos, decal previews) driven by the clock. Same id = replaced. */
360	  addOverlay(o: Overlay) { this.removeOverlay(o.id); const g = new this.T.Group(); g.name = o.id; this.overlayRoot.add(g); o.attach(this.T, g); this.overlays.set(o.id, { ...o, group: g } as Overlay & { group: THREE_NS.Group }); this.applyTime(); }
361	  removeOverlay(id: string) { const o = this.overlays.get(id) as (Overlay & { group?: THREE_NS.Group }) | undefined; if (!o) return; o.dispose?.(); if (o.group) this.overlayRoot.remove(o.group); this.overlays.delete(id); this.requestRender(); }
362	  /** The posed scene at the clock's time (for the pure pick while posed / playing). */
363	  posed(): ModelScene | null { return this.shown && this.providers.length ? posedScene(this.shown, evalPose(this.providers, this.clock.time, this.shown)) : this.shown; }
364	  private applyTime() {
365	    const t = this.clock.time;
366	    if (this.shown && this.providers.length) this.setPartOverrides(evalPose(this.providers, t, this.shown));
367	    for (const o of this.overlays.values()) o.update?.(t);
368	    this.requestRender();
369	  }
370	  /** Render the scene exactly at time t (pauses the clock): thumbnails, frame grabs, comparisons with the server preview. */
371	  renderAt(t: number): string { this.clock.pause(); this.clock.seek(t); this.applyTime(); return this.snapshot(); }
372	
373	  // ------------------------------------------------------------------ render
374	  private resize() {
375	    const r = this.canvas.getBoundingClientRect();
376	    const w = Math.max(1, Math.floor(r.width)), h = Math.max(1, Math.floor(r.height));
377	    this.renderer.setSize(w, h, false);
378	    if (this.camera instanceof this.T.PerspectiveCamera) { this.camera.aspect = w / h; this.camera.updateProjectionMatrix(); }
379	    else if (this.rig) { this.applyRigCamera(); return; }
380	    this.requestRender();
381	  }
382	  requestRender() {
383	    if (this.raf) return;
384	    this.raf = requestAnimationFrame((now) => {
385	      this.raf = 0;
386	      this.frames++;
387	      if (this.clock.state.playing) { const dt = this.lastTick ? (now - this.lastTick) / 1000 : 0; this.lastTick = now; this.clock.tick(Math.min(0.1, dt)); this.requestRender(); }
388	      else this.lastTick = 0;
389	      this.renderer.render(this.scene3, this.camera);
390	    });
391	  }
392	  /** A PNG of the current view (thumbnails). */
393	  snapshot(): string { this.renderer.render(this.scene3, this.camera); return this.canvas.toDataURL("image/png"); }
394	  dispose() {
395	    cancelAnimationFrame(this.raf);
396	    this.ro.disconnect();
397	    for (const m of this.parts) m.geometry.dispose();
398	    for (const o of this.overlays.values()) o.dispose?.();
399	    for (const t of Object.values(this.tex)) t?.dispose();
400	    this.viewTex?.dispose();
401	    this.renderer.dispose();
402	  }
403	}
404	// Cyrus Model Studio: per-NODE transform overrides driven by scene time (the hook point animation and effects plug
405	// into; nothing here is game-specific). Pure + client-safe.
406	//   PoseProvider  anything that can say, at time t, how some scene parts (nodes) move: a creature clip, a gun's
407	//                 slide-back on reload, a vehicle door. Returns model-space matrices per part index.
408	//   evalPose      merges providers at time t (later providers compose on top of earlier ones)
409	//   posedScene    the scene with the overrides baked into its positions, so the PURE pick (./pick.ts) still hits
410	//                 the right texel while the model is posed or playing
411	// The viewport applies the same overrides to per-part meshes (components/cyrus/studios/model-viewport.ts
412	// setPartOverrides), and the server preview takes them in the request (preview/types.ts `overrides`, `time`), so the
413	// live view and the deterministic render agree at any time t.
414	import { apply4, mul4, type M4 } from "./math";
415	import type { ModelScene } from "./scene";
416	
417	export type PartOverrides = Map<number, M4>;
418	export interface PoseProvider {
419	  readonly id: string;
420	  /** seconds; 0 = a static pose */
421	  readonly duration: number;
422	  poseAt(t: number, scene: ModelScene): PartOverrides;
423	}
424	
425	/** Merge providers at time t: for a part several providers move, the matrices compose in provider order. */
426	export function evalPose(providers: readonly PoseProvider[], t: number, scene: ModelScene): PartOverrides {
427	  const out: PartOverrides = new Map();
428	  for (const p of providers) for (const [part, m] of p.poseAt(t, scene)) out.set(part, out.has(part) ? mul4(m, out.get(part)!) : m);
429	  return out;
430	}
431	
432	/** A copy of the scene with each overridden part's triangles transformed (bounds recomputed). */
433	export function posedScene(s: ModelScene, o: PartOverrides): ModelScene {
434	  if (!o.size) return s;
435	  const pos = new Float32Array(s.pos);
436	  for (let t = 0; t < s.triCount; t++) {
437	    const m = o.get(s.part[t]);
438	    if (!m) continue;
439	    for (let k = 0; k < 3; k++) {
440	      const i = t * 9 + k * 3;
441	      const p = apply4(m, [pos[i], pos[i + 1], pos[i + 2]]);
442	      pos[i] = p[0]; pos[i + 1] = p[1]; pos[i + 2] = p[2];
443	    }
444	  }
445	  const min: [number, number, number] = [Infinity, Infinity, Infinity], max: [number, number, number] = [-Infinity, -Infinity, -Infinity];
446	  for (let i = 0; i < pos.length; i += 3) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], pos[i + k]); max[k] = Math.max(max[k], pos[i + k]); }
447	  return { ...s, pos, bounds: { min, max } };
448	}
449	
450	/** Overrides as plain JSON (part index -> 16 numbers) for the server preview request. */
451	export const overridesJson = (o: PartOverrides): Record<string, number[]> => Object.fromEntries([...o].sort((a, b) => a[0] - b[0]).map(([k, m]) => [String(k), m.map((v) => Math.round(v * 1e6) / 1e6)]));
452	
453	/** A provider from a function (tests, simple effects). */
454	export const poseProvider = (id: string, duration: number, f: (t: number, s: ModelScene) => PartOverrides): PoseProvider => ({ id, duration, poseAt: f });
455	// Cyrus Model Studio (Layer 1): PBR channel VIEW MODES, profile-aware. Pure + client-safe.
456	// A game's asset profile (lib/cyrus/adapters/asset-profile.ts channelMap) says which channel roles it can ship.
457	// Channels it cannot ship are shown DISABLED with the reason (plan section 4: "Minecraft Java item: albedo only"),
458	// never silently hidden, and they cannot be painted on that model either. A model with no game profile (a glTF
459	// mesh before an adapter claims it) gets the full glTF metallic-roughness set.
460	import type { AssetProfile, ChannelRole } from "../adapters/asset-profile";
461	import { CHANNEL_DEFAULT, compositeChannel, PAINT_CHANNELS, solidImg, type LayerSet, type PaintChannel } from "./layers";
462	import type { Img } from "./scene";
463	
464	export const VIEW_MODES = ["lit", "albedo", "normal", "roughness", "metallic", "ao", "emissive", "mask"] as const;
465	export type ViewMode = (typeof VIEW_MODES)[number];
466	export const VIEW_LABEL: Record<ViewMode, string> = { lit: "Lit", albedo: "Albedo", normal: "Normal", roughness: "Rough", metallic: "Metal", ao: "AO", emissive: "Emissive", mask: "Mask" };
467	
468	export type ModeState = { id: ViewMode; label: string; enabled: boolean; reason: string | null };
469	export type ChannelState = { channel: PaintChannel; paintable: boolean; reason: string | null };
470	
471	const ROLE: Record<PaintChannel, ChannelRole> = { albedo: "albedo", normal: "normal", roughness: "roughness", metallic: "metallic", emissive: "emissive", mask: "mask" };
472	const engineName = (p: AssetProfile) => (p.engineFamily === "minecraft-java" ? "Minecraft Java" : p.game);
473	
474	/** Which channels may be painted for this profile (mask is an authoring aid: never shipped, always paintable). */
475	export function paintChannels(profile: AssetProfile | null): ChannelState[] {
476	  return PAINT_CHANNELS.map((c) => {
477	    if (!profile || c === "mask" || profile.channelMap[ROLE[c]]) return { channel: c, paintable: true, reason: null };
478	    return { channel: c, paintable: false, reason: `${engineName(profile)} models have no ${c} map, so it would never reach the game` };
479	  });
480	}
481	
482	export function viewModes(profile: AssetProfile | null): ModeState[] {
483	  const pc = new Map(paintChannels(profile).map((c) => [c.channel as string, c]));
484	  return VIEW_MODES.map((id) => {
485	    if (id === "lit") return { id, label: VIEW_LABEL[id], enabled: true, reason: null };
486	    if (id === "ao") return { id, label: VIEW_LABEL[id], enabled: false, reason: "Ambient occlusion is baked from the mesh at export, not painted (Layer 3/4)" };
487	    const c = pc.get(id)!;
488	    return { id, label: VIEW_LABEL[id], enabled: c.paintable, reason: c.reason };
489	  });
490	}
491	
492	/** The image a view mode shows: the channel's composite (grey channels read R), albedo as is. */
493	export function channelImage(set: LayerSet, mode: Exclude<ViewMode, "lit" | "ao">, albedoBase: Img | null): Img {
494	  const ch = mode as PaintChannel;
495	  const img = compositeChannel(set, ch, ch === "albedo" ? albedoBase : null);
496	  if (ch === "roughness" || ch === "metallic" || ch === "mask") for (let i = 0; i < img.w * img.h; i++) { const v = img.px[i * 4]; img.px[i * 4 + 1] = v; img.px[i * 4 + 2] = v; img.px[i * 4 + 3] = 255; }
497	  return img;
498	}
499	
500	/** Every channel's composite (what the Lit material and the server renderer use). */
501	export function allChannels(set: LayerSet, albedoBase: Img | null): Record<PaintChannel, Img> {
502	  return Object.fromEntries(PAINT_CHANNELS.map((c) => [c, compositeChannel(set, c, c === "albedo" ? albedoBase : null)])) as Record<PaintChannel, Img>;
503	}
