505	/** True when nothing is painted on a channel (the material can skip that map). */
506	export const channelUntouched = (set: LayerSet, c: PaintChannel) => !set.layers.some((l) => l.channel === c && l.visible && l.opacity > 0 && l.px.some((v, i) => i % 4 === 3 && v > 0));
507	
508	/** A deterministic UV checker: 8 x 8 cells, two tones, plus a 1-texel grid line per cell (shows stretching and seams). */
509	export function uvChecker(w: number, h: number): Img {
510	  const img = solidImg(w, h, CHANNEL_DEFAULT.normal);
511	  const cw = Math.max(1, Math.floor(w / 8)), chh = Math.max(1, Math.floor(h / 8));
512	  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
513	    const o = (y * w + x) * 4, cx = Math.floor(x / cw), cy = Math.floor(y / chh);
514	    const on = (cx + cy) % 2 === 0, line = x % cw === 0 || y % chh === 0;
515	    const v = line ? [255, 255, 255] : on ? [124, 77, 255] : [32, 26, 58];
516	    img.px[o] = v[0]; img.px[o + 1] = v[1]; img.px[o + 2] = v[2]; img.px[o + 3] = 255;
517	  }
518	  return img;
519	}
