344	function useTheme(): "dark" | "light" {
345	  const [t, setT] = useState<"dark" | "light">("dark");
346	  useEffect(() => {
347	    const read = () => setT(document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark");
348	    read();
349	    const mo = new MutationObserver(read);
350	    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
351	    return () => mo.disconnect();
352	  }, []);
353	  return t;
354	}
