366	  const [dims, setDims] = useState({ w: 600, h: 400 });
367	  const [orbit, setOrbit] = useState({ yaw: 0, pitch: 0, zoom: 1 });
368	  const [hot, setHot] = useState<0 | 1 | 2 | null>(null);
369	  const drag = useRef<{ kind: "orbit" | "axis"; x: number; y: number; axis?: 0 | 1 | 2; op?: Op | null } | null>(null);
370	  const theme = useTheme();
371	  const { doc } = p;
372	  const scene = useMemo(() => buildScene(doc, { clip: p.clip, time: p.time }), [doc, p.clip, p.time]);
373	  const rest = useMemo(() => buildScene(doc), [doc]);
374	  // frame the camera on the model once per model + view (not on every edit, so the view does not jump)
375	  const frameKey = `${doc.name}|${p.view}`;
376	  const [frameBox, setFrameBox] = useState<{ key: string; min: Vec3; max: Vec3 } | null>(null);
377	  useEffect(() => { if (frameBox?.key !== frameKey) setFrameBox({ key: frameKey, min: rest.min, max: rest.max }); }, [frameKey, rest, frameBox]);
378	  const cam: Camera = useMemo(() => {
379	    const c = fitCamera(frameBox ?? rest, dims.w, dims.h, p.view);
380	    return { ...c, yaw: c.yaw + orbit.yaw, pitch: Math.max(-89, Math.min(89, c.pitch + orbit.pitch)), zoom: c.zoom * orbit.zoom, ortho: c.ortho && orbit.yaw === 0 && orbit.pitch === 0, offsetY: 14 };
381	  }, [frameBox, rest, dims, p.view, orbit]);
382	  useEffect(() => { setOrbit({ yaw: 0, pitch: 0, zoom: 1 }); }, [p.view]);
383	
384	  const primary = p.sel[0] ?? null;
385	  const gizmo: Gizmo = useMemo(() => {
386	    if (!primary || p.tool === "select" || p.readOnly) return null;
387	    const b = boneById(doc, primary), c = cubeById(doc, primary);
388	    const world = (boneId: string, pt: Vec3): Vec3 => { const m = scene.matrices.get(boneId); return m ? applyM(m, pt) : pt; };
389	    if (b) return { kind: p.tool === "resize" ? "move" : p.tool, origin: world(b.id, b.pivot) };
390	    if (c) return { kind: p.tool, origin: world(c.bone, p.tool === "pivot" || p.tool === "rotate" ? c.pivot : p.tool === "resize" ? c.to : centre(c)) };
391	    return null;
392	  }, [primary, p.tool, p.readOnly, doc, scene]);
393	  const frame: ViewportFrame = { scene, camera: cam, selected: new Set(p.sel), selectedBone: primary && boneById(doc, primary) ? primary : cubeById(doc, primary ?? "")?.bone ?? null, showBones: p.showBones, wire: p.wire, gizmo, hot, theme };
394	
395	  useEffect(() => {
396	    const c = cv.current;
397	    if (!c) return;
398	    vp.current = p.factory(c, { maxDpr: window.innerWidth < 760 ? 1.5 : 2 });
399	    const ro = new ResizeObserver(() => setDims({ w: Math.max(50, c.clientWidth), h: Math.max(50, c.clientHeight) }));
400	    ro.observe(c);
401	    return () => { ro.disconnect(); vp.current?.dispose(); vp.current = null; };
402	  }, [p.factory]);
403	  useEffect(() => { vp.current?.draw(frame); });
404	
405	  const local = (e: React.PointerEvent | React.WheelEvent) => { const r = cv.current!.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
406	  const opFor = (axis: 0 | 1 | 2, dx: number, dy: number): Op | null => {
407	    if (!primary || !gizmo) return null;
408	    const u = axisDrag(cam, gizmo.origin, axis, dx, dy);
409	    const vec = (n: number): Vec3 => { const v: Vec3 = [0, 0, 0]; v[axis] = n; return v; };
410	    const c = cubeById(doc, primary), b = boneById(doc, primary);
411	    if (p.tool === "move" || (p.tool === "resize" && b)) return { op: "move", ids: p.sel, delta: vec(u), snap: p.snap };
412	    if (p.tool === "rotate") return { op: "rotate", ids: p.sel, rotation: vec(dx * 0.6), mode: "add", snap: p.angleSnap };
413	    if (p.tool === "pivot") { const base = b ? b.pivot : c!.pivot; return { op: "setPivot", id: primary, pivot: base.map((v, i) => (i === axis ? v + u : v)) as Vec3, snap: p.snap }; }
414	    if (p.tool === "resize" && c) { const s: Vec3 = [c.to[0] - c.from[0], c.to[1] - c.from[1], c.to[2] - c.from[2]]; s[axis] += u; return { op: "resize", id: c.id, size: s, snap: p.snap }; }
415	    return null;
416	  };
417	
418	  return (
419	    <div className="me-stage">
420	      <canvas ref={cv} className="me-cv" aria-label={`3D view of ${doc.name}`} role="img"
421	        onContextMenu={(e) => e.preventDefault()}
