424	          (e.target as HTMLElement).setPointerCapture(e.pointerId);
425	          const axis = e.button === 0 && vp.current ? vp.current.gizmoAxisAt(frame, x, y) : null;
426	          if (axis !== null) { drag.current = { kind: "axis", x, y, axis, op: null }; return; }
427	          if (e.button === 0) {
428	            const hit = pickCube(scene, cam, x, y);
429	            if (hit) { p.setSel(e.shiftKey ? (p.sel.includes(hit) ? p.sel.filter((s) => s !== hit) : [...p.sel, hit]) : [hit]); drag.current = null; return; }
430	          }
431	          drag.current = { kind: "orbit", x, y };
432	        }}
433	        onPointerMove={(e) => {
434	          const { x, y } = local(e);
435	          const d = drag.current;
436	          if (!d) { if (vp.current && gizmo) { const a = vp.current.gizmoAxisAt(frame, x, y); if (a !== hot) setHot(a); } return; }
437	          if (d.kind === "orbit") { setOrbit((o) => ({ ...o, yaw: o.yaw - (x - d.x) * 0.4, pitch: o.pitch - (y - d.y) * 0.3 })); drag.current = { ...d, x, y }; return; }
438	          const op = opFor(d.axis!, x - d.x, y - d.y);
439	          d.op = op;
440	          p.onPreview(op);
441	        }}
442	        onPointerUp={() => { const d = drag.current; drag.current = null; if (d?.kind === "axis") { if (d.op) p.onCommit(d.op); else p.onPreview(null); } }}
443	        onWheel={(e) => setOrbit((o) => ({ ...o, zoom: Math.max(0.3, Math.min(5, o.zoom * (e.deltaY > 0 ? 0.9 : 1.1))) }))} />
444	      <div className="me-tools cys-glass" role="toolbar" aria-label="Tools">
445	        {TOOLS.map((t) => <button key={t.id} type="button" disabled={p.readOnly && t.id !== "select"} className={`cys-ib ${p.tool === t.id ? "on" : ""}`} aria-label={`${t.label} (${t.key})`} aria-pressed={p.tool === t.id} data-tip={`${t.label}  ${t.key}`} onClick={() => p.setTool(t.id)}><MI n={t.icon} /></button>)}
446	        <span className="cys-sep" />
447	        <button type="button" className={`cys-ib tog ${p.showBones ? "on" : ""}`} aria-label="Show bones" aria-pressed={p.showBones} data-tip="Bones" onClick={() => p.setShowBones(!p.showBones)}><MI n="bone" /></button>
448	        <button type="button" className={`cys-ib tog ${p.wire ? "on" : ""}`} aria-label="Wireframe" aria-pressed={p.wire} data-tip="Wire" onClick={() => p.setWire(!p.wire)}><MI n="wire" /></button>
449	      </div>
450	      <div className="me-vtop">
451	        <span className="sp" />
452	        <label className="me-snap cys-soft"><span>Snap</span><select aria-label="Move snap" value={p.snap} onChange={(e) => p.setSnap(Number(e.target.value))}>{SNAP_STEPS.map((s) => <option key={s} value={s}>{s ? `${s} u` : "off"}</option>)}</select></label>
453	        <label className="me-snap cys-soft"><span>Angle</span><select aria-label="Angle snap" value={p.angleSnap} onChange={(e) => p.setAngleSnap(Number(e.target.value))}>{ANGLE_SNAPS.map((s) => <option key={s} value={s}>{s ? `${s}°` : "off"}</option>)}</select></label>
454	        <div className="cys-seg cys-soft sm" role="group" aria-label="View">{(["persp", "front", "side"] as const).map((v) => <button key={v} type="button" className={p.view === v ? "on" : ""} onClick={() => p.setView(v)}>{v === "persp" ? "Persp" : v === "front" ? "Front" : "Side"}</button>)}</div>
455	      </div>
456	      {primary && (
457	        <div className="me-hud cys-soft mono">
458	          {cubeById(doc, primary) ? (() => { const c = cubeById(doc, primary)!; const s = [0, 1, 2].map((i) => Math.round((c.to[i] - c.from[i]) * 100) / 100); return `${boneById(doc, c.bone)?.name} · ${cubeLabel(doc, c.id)} · ${s.join(" × ")}`; })() : `${boneById(doc, primary)?.name} · pivot ${boneById(doc, primary)?.pivot.join(", ")}`}
459	          {p.sel.length > 1 ? ` · +${p.sel.length - 1}` : ""}
