462	      <span className="cys-chip cys-soft me-pose"><MI n="bone" />{p.clip ? <>Pose <b>{p.clip}</b> at <b className="mono">{p.time.toFixed(2)} s</b></> : "Rest pose"}</span>
463	      <div className="me-axes" aria-hidden="true"><i className="x">X</i><i className="y">Y</i><i className="z">Z</i></div>
464	    </div>
465	  );
466	}
