/// Cyrus Model Studio (Layer 1): the AUTOSAVED working copy of one paint session, one per (project, owner, model key).
/// Never built, never shared, never a revision: "Save revision" turns it into a revision and deletes it. The doc is a
/// ModelDoc v1 (lib/cyrus/modelstudio/doc.ts). Opaque ids, no foreign keys into Nxeon (host seam).
model CyrusModelDraft {
  id          String   @id @default(cuid())
  projectId   String
  /// the owner (user id as an opaque reference)
  ownerRef    String
  assetKey    String
  /// the asset row the session started from (null = first paint)
  baseAssetId String?
  /// the project head the session saw when it started
  baseHeadId  String?
  doc         Json
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([projectId, ownerRef, assetKey])
  @@index([ownerRef])
}

/// The identifier registry: one row per identifier a project defines.
/// Unique per (namespace, kind, key); glyph codepoints are unique across ALL
/// projects, so Mod Packs can never collide on a glyph.
model CyrusIdentifier {
  id        String   @id @default(cuid())
  });
  if (!rows.length) return null;
  const root = rows.find((r) => r.id === rootBuildId) ? rootBuildId : rows[0].rootBuildId ?? rows[0].id;
  const ok = rows.filter((r) => r.status === "succeeded");
  const regular = ok.filter((r) => !candidateKeyOf(r.changeRequest) && !soundCandidateOf(r.changeRequest));
  const withAssets = ok.map((r) => readBuildAssets(r.result)).find(Boolean) ?? null;
  return {
    rootBuildId: root, latestBuildId: ok[0]?.id ?? null, baseBuildId: regular[0]?.id ?? ok[0]?.id ?? null, mcVersion: (regular[0] ?? ok[0] ?? rows[0]).mcVersion, pluginName: (regular[0] ?? rows[0]).pluginName,
    assets: withAssets,
    candidateBuilds: rows.flatMap((r) => { const key = candidateKeyOf(r.changeRequest); return key ? [{ id: r.id, key, status: r.status, error: r.error, createdAt: r.createdAt.toISOString(), summary: candidateSummaryOf(r.changeRequest) }] : []; }),
    soundCandidateBuilds: rows.flatMap((r) => { const c = soundCandidateOf(r.changeRequest); return c ? [{ id: r.id, set: c.set, event: c.event, status: r.status, error: r.error, createdAt: r.createdAt.toISOString(), summary: candidateSummaryOf(r.changeRequest) }] : []; }),
  };
}


/**
 * Cyrus Model Studio drafts (CyrusModelDraft): the autosaved working copy. Lives here because this file is the studios'
 * one Prisma bridge (host seam: no new Nxeon imports under lib/cyrus). Upsert on (project, owner, key).
 */
export const prismaModelDraftStore = {
  get: async (projectId: string, ownerRef: string, assetKey: string) => db.cyrusModelDraft.findUnique({ where: { projectId_ownerRef_assetKey: { projectId, ownerRef, assetKey } } }),
  put: async (r: { projectId: string; ownerRef: string; assetKey: string; baseAssetId: string | null; baseHeadId: string | null; doc: unknown }) => {
    const data = { baseAssetId: r.baseAssetId, baseHeadId: r.baseHeadId, doc: r.doc as never };
    const row = await db.cyrusModelDraft.upsert({ where: { projectId_ownerRef_assetKey: { projectId: r.projectId, ownerRef: r.ownerRef, assetKey: r.assetKey } }, update: data, create: { projectId: r.projectId, ownerRef: r.ownerRef, assetKey: r.assetKey, ...data } });
    return { updatedAt: row.updatedAt };
  },
  drop: async (projectId: string, ownerRef: string, assetKey: string) => { await db.cyrusModelDraft.deleteMany({ where: { projectId, ownerRef, assetKey } }); },
};

/**
 * Cyrus Config Studio: the newest regular succeeded build of the owner's chain, with config.yml / plugin.yml read out of
 * its stored jar and the settings schema the portal re-validated (ModBuild.result.cyrusConfig). Read only.
 */
export async function configSourceOf(userId: string, rootBuildId: string): Promise<ConfigSource | null> {
  const rows = await db.modBuild.findMany({
    where: { userId, status: "succeeded", OR: [{ id: rootBuildId }, { rootBuildId }] },
    orderBy: { createdAt: "desc" }, take: 50,
    select: { id: true, mcVersion: true, pluginName: true, changeRequest: true, result: true, jarPath: true },
  });
  const row = rows.find((r) => !candidateKeyOf(r.changeRequest) && !soundCandidateOf(r.changeRequest)) ?? rows[0];
  if (!row) return null;
  let configYml: string | null = null, pluginYml: string | null = null;
  if (row.jarPath) {
    try {
      const z = indexZip(await readFile(row.jarPath));
      if (z.ok) for (const e of z.zip.entries) {
        if (e.name !== "config.yml" && e.name !== "plugin.yml") continue;
        const r = readEntry(z.zip, e, 512 * 1024);
        if (r.ok) { if (e.name === "config.yml") configYml = r.data.toString("utf8"); else pluginYml = r.data.toString("utf8"); }
      }
    } catch { /* jar gone: no file values */ }
  }
  const cc = (row.result as { cyrusConfig?: { source?: unknown; spec?: unknown } } | null)?.cyrusConfig;
  const declared = cc && cc.spec && (cc.source === "declared" || cc.source === "inferred") ? { source: cc.source as "declared" | "inferred", spec: cc.spec } : null;
  return { buildId: row.id, pluginName: row.pluginName, mcVersion: row.mcVersion, configYml, pluginYml, declared };
}
// Model Studio L2: the REAL dependencies of the model editor API. SERVER ONLY. Reuses the studios' wiring (the
// viewer rule, the Prisma StudioStore, the plan lookup, the rate limiter) and reads the editor's own flag through the
// host seam. Drafts: no CyrusModelDraft table yet (plan task F1), so the server has no draft store (null -> the client
// keeps drafts in the browser); devhost can opt into an in-process memory store with CYRUS_MODEL_EDITOR_DRAFTS=memory.
import { getHost } from "../../host";
import { prismaStudioStore, studioPlanOf, studioViewer } from "../../studios/deps";
import { MODEL_EDITOR_FLAG, type ModelEditorApiDeps } from "./http";
import { memoryDraftStore, type DraftStore } from "./service";

/** Non-production only: CYRUS_MODEL_EDITOR_DEV=1 opens the editor without the setting (devhost screenshots). */
export async function modelEditorEnabled(env: Record<string, string | undefined> = process.env): Promise<boolean> {
  if (env.NODE_ENV !== "production" && env.CYRUS_MODEL_EDITOR_DEV === "1") return true;
  try { return await getHost().settings.getBool(MODEL_EDITOR_FLAG, false); } catch { return false; }
}

const G = globalThis as { __cyrusModelDrafts?: DraftStore };
export function modelEditorApiDeps(env: Record<string, string | undefined> = process.env): ModelEditorApiDeps {
  const dev = env.NODE_ENV !== "production";
  return {
    viewer: studioViewer,
    enabled: () => modelEditorEnabled(env),
    service: { store: prismaStudioStore, planOf: studioPlanOf(env), drafts: dev && env.CYRUS_MODEL_EDITOR_DRAFTS === "memory" ? (G.__cyrusModelDrafts ??= memoryDraftStore()) : null },
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:studio:${key}`, { max, windowMs }),
    allowPlanned: dev && env.CYRUS_MODEL_EDITOR_PLANNED_EXPORTERS === "1",
  };
}
// Model Studio L2: the server half of the cuboid + bone editor (load, save as a revision, drafts). SERVER ONLY.
// Every dependency is injected (host seam): the project/revision/asset rows through the studios' StudioStore, the plan
// through planOf, drafts through DraftStore. No Nxeon internals here.
//
// A project's model = the newest CyrusProjectAsset row of kind "model" for its key. A build writes RigSpec rows
// (mime RIG_SPEC_MIME, provenance.spec); the editor writes ModelDoc rows (mime MODEL_DOC_MIME, provenance.doc + the
// explicit RigSpec it compiled). Rows and revisions are append-only: a save is a NEW revision (kind "asset") plus a new
// asset row, with expectedHeadId -> 409 stale_head exactly like the Texture Studio. Before writing, the doc is parsed
// (untrusted), validated (errors block), re-checked with checkRigSpec, compiled with the real creature compiler and run
// through the skin quality bar (creature/portal.ts checkReturnedCreature), so a saved model always builds.
import { canonicalJson, sha256Hex } from "../../assets/textures";
import { RIG_SPEC_MIME, checkReturnedCreature } from "../../creature/portal";
import { COMPILER_VERSION } from "../../creature/compile";
import { checkRigSpec } from "../../creature/spec";
import type { ManifestEntry } from "../../engine-core/revisions";
import { StudioError, type AssetRow, type ProjectRow, type StudioStore } from "../../studios/service";
import { checkModelDoc, MODEL_DOC_MIME, type ModelDoc } from "./doc";
import { canModelEditor, modelEditorAccess, type ModelEditorAccess } from "./gate";
import { fromRigSpec, toRigSpec } from "./rigspec";
import { validateDoc, type Validation } from "./validate";

export const MODEL_EDITOR_TOOLCHAIN = `cyrus-model-editor ${COMPILER_VERSION}`;

export type ModelDraft = { ownerRef: string; projectId: string; key: string; baseAssetId: string | null; baseHeadId: string | null; doc: ModelDoc; updatedAt: string };
/** CyrusModelDraft (MODEL-STUDIO-PLAN F1) is not a table yet: drafts go through this interface; null = not wired. */
export interface DraftStore {
  get(ownerRef: string, projectId: string, key: string): Promise<ModelDraft | null>;
  put(d: ModelDraft): Promise<void>;
  remove(ownerRef: string, projectId: string, key: string): Promise<void>;
}
export function memoryDraftStore(): DraftStore & { rows: Map<string, ModelDraft> } {
  const rows = new Map<string, ModelDraft>();
  const k = (o: string, p: string, key: string) => `${o}|${p}|${key}`;
  return {
    rows,
    async get(o, p, key) { return rows.get(k(o, p, key)) ?? null; },
    async put(d) { rows.set(k(d.ownerRef, d.projectId, d.key), JSON.parse(JSON.stringify(d))); },
    async remove(o, p, key) { rows.delete(k(o, p, key)); },
  };
}

export type ModelEditorDeps = {
  store: Pick<StudioStore, "project" | "projectForRoot" | "assets" | "revisions" | "addRevision" | "recordAsset">;
  planOf: (userId: string) => Promise<unknown>;
  drafts: DraftStore | null;
};

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();
const gate = (d: ReturnType<typeof canModelEditor>) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };
export const docSha = (d: ModelDoc) => sha256Hex(canonicalJson(d));

export type ModelEntry = { key: string; assetId: string; origin: string; revisionId: string; createdAt: string; source: "rigspec" | "modeldoc"; doc: ModelDoc };

/** The ModelDoc an asset row holds (a build's RigSpec row is converted; a broken row is skipped). */
export function docOfModelRow(row: AssetRow): ModelDoc | null {
  if (row.kind !== "model") return null;
  const p = obj(row.provenance);
  if (row.mime === MODEL_DOC_MIME) { const d = checkModelDoc(p.doc); return d.ok ? d.doc : null; }
  if (row.mime === RIG_SPEC_MIME) { const c = checkRigSpec(p.spec); return c.ok ? fromRigSpec(c.spec) : null; }
  return null;
}

/** Pure: the current model per key (newest readable row), oldest key first. */
export function resolveModels(rows: readonly AssetRow[]): ModelEntry[] {
  const byKey = new Map<string, AssetRow[]>();
  for (const r of rows) if (r.kind === "model") byKey.set(r.assetKey, [...(byKey.get(r.assetKey) ?? []), r]);
  const out: (ModelEntry & { first: number })[] = [];
  for (const [key, list] of byKey) {
    list.sort((a, b) => ts(a.createdAt) - ts(b.createdAt) || (a.id < b.id ? -1 : 1));
    for (let i = list.length - 1; i >= 0; i--) {
      const doc = docOfModelRow(list[i]);
      if (!doc) continue;
      const r = list[i];
      out.push({ key, assetId: r.id, origin: r.origin, revisionId: r.revisionId, createdAt: new Date(r.createdAt).toISOString(), source: r.mime === MODEL_DOC_MIME ? "modeldoc" : "rigspec", doc, first: ts(list[0].createdAt) });
      break;
    }
  }
  return out.sort((a, b) => a.first - b.first || (a.key < b.key ? -1 : 1)).map(({ first: _f, ...m }) => { void _f; return m; });
}

async function owned(deps: ModelEditorDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}
const accessOf = async (deps: ModelEditorDeps, userId: string): Promise<ModelEditorAccess> => modelEditorAccess(await deps.planOf(userId).catch(() => null));

export type ModelListView = { project: { id: string; namespace: string; title: string | null } | null; headRevisionId: string | null; access: ModelEditorAccess; models: Omit<ModelEntry, "doc">[] };
/** The models of a mod (viewing is never gated). */
export async function listModels(deps: ModelEditorDeps, userId: string, rootBuildId: string): Promise<ModelListView> {
  const access = await accessOf(deps, userId);
  const p = await deps.store.projectForRoot(rootBuildId);
  if (!p || p.userId !== userId) return { project: null, headRevisionId: null, access, models: [] };
  const revs = await deps.store.revisions(p.id);
  return { project: { id: p.id, namespace: p.namespace, title: p.title }, headRevisionId: revs.at(-1)?.id ?? null, access, models: resolveModels(await deps.store.assets(p.id)).map(({ doc: _d, ...m }) => { void _d; return m; }) };
}

export type ModelView = { model: ModelEntry; headRevisionId: string | null; revisionSeq: number | null; access: ModelEditorAccess; validation: Validation; draft: ModelDraft | null; namespace: string };
export async function loadModel(deps: ModelEditorDeps, userId: string, projectId: string, key: string): Promise<ModelView> {
  const p = await owned(deps, userId, projectId);
  const model = resolveModels(await deps.store.assets(p.id)).find((m) => m.key === key);
  if (!model) throw new StudioError(404, "not_found", `No model called ${key} in this mod.`);
  const access = await accessOf(deps, userId);
  const revs = await deps.store.revisions(p.id);
  // a draft is only offered to someone who may edit (it is unsaved editing work)
  const draft = access.edit.ok && deps.drafts ? await deps.drafts.get(userId, p.id, key).catch(() => null) : null;
  return { model, headRevisionId: revs.at(-1)?.id ?? null, revisionSeq: revs.find((r) => r.id === model.revisionId)?.seq ?? null, access, validation: validateDoc(model.doc), draft, namespace: p.namespace };
}

export type SaveModelInput = { userId: string; projectId: string; key: string; doc: unknown; baseAssetId: string; expectedHeadId: string | null; message?: string | null; action?: "save" | "approve" };
export type SaveModelResult = { revisionId: string; seq: number; assetId: string; specSha256: string; bbmodelSha256: string; warnings: string[]; validation: Validation };

export async function saveModelRevision(deps: ModelEditorDeps, input: SaveModelInput): Promise<SaveModelResult> {
  gate(canModelEditor(await deps.planOf(input.userId).catch(() => null), input.action ?? "save"));
  const project = await owned(deps, input.userId, input.projectId);
  const parsed = checkModelDoc(input.doc);
  if (!parsed.ok) throw new StudioError(400, "bad_doc", parsed.error);
  const doc = parsed.doc;
  if (doc.name !== input.key) throw new StudioError(400, "bad_doc", "the model name must match its key (renaming a creature is not supported yet)");
  const rows = await deps.store.assets(project.id);
  const base = rows.find((r) => r.id === input.baseAssetId && r.kind === "model" && r.assetKey === input.key);
  if (!base) throw new StudioError(404, "not_found", "The model this edit started from is not in this project.");
  const validation = validateDoc(doc);
  if (!validation.ok) throw new StudioError(422, "invalid", validation.issues.find((i) => i.severity === "error")!.message, { issues: validation.issues.filter((i) => i.severity === "error").slice(0, 20) });
  const { spec } = toRigSpec(doc);
  const checked = checkReturnedCreature({ name: doc.name, spec }, project.namespace);
  if (!checked.ok) throw new StudioError(422, "compile_failed", `This model can't be built: ${checked.reason}`);

  const revs = await deps.store.revisions(project.id);
  const head = revs.at(-1) ?? null;
  if ((head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const docCanonical = canonicalJson(doc), docSha256 = sha256Hex(docCanonical);
  const creaturePath = `assets/creatures/${doc.name}.json`, docPath = `assets/models/${doc.name}.modeldoc.json`, bbPath = `bettermodel/${checked.key}.bbmodel`;
  const manifest: ManifestEntry[] = [
    ...(head?.manifest ?? []).filter((e) => e.path !== creaturePath && e.path !== docPath && e.path !== bbPath),
    { path: creaturePath, sha256: checked.specSha256, role: "asset" },
    { path: bbPath, sha256: checked.compiled.bbmodelSha256, role: "asset" },
    { path: docPath, sha256: docSha256, role: "asset" },
  ];
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, {
      kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: MODEL_EDITOR_TOOLCHAIN },
      message: (input.message ?? (input.action === "approve" ? `Approved ${doc.name} on a phone` : `Edited ${doc.name} in Model Studio`)).slice(0, 200),
    });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const asset = await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: doc.name, kind: "model", sha256: docSha256, size: Buffer.byteLength(docCanonical), origin: "edited", mime: MODEL_DOC_MIME, path: docPath,
    provenance: {
      generator: "cyrus-model-editor", compiler: COMPILER_VERSION, doc, spec: checked.input, specSha256: checked.specSha256, modelKey: checked.key,
      bbmodelSha256: checked.compiled.bbmodelSha256, pngSha256: checked.compiled.pngSha256, stats: checked.compiled.stats, quality: checked.quality,
      warnings: checked.warnings.slice(0, 10), basedOn: base.id,
    },
  });
  if (deps.drafts) await deps.drafts.remove(input.userId, project.id, doc.name).catch(() => undefined);
  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, specSha256: checked.specSha256, bbmodelSha256: checked.compiled.bbmodelSha256, warnings: checked.warnings, validation };
}

/** Autosave: store the working copy as a draft (never built, never shared). Gated like any edit. */
export async function saveDraft(deps: ModelEditorDeps, i: { userId: string; projectId: string; key: string; doc: unknown; baseAssetId: string | null; baseHeadId: string | null }): Promise<{ updatedAt: string; sha256: string }> {
  gate(canModelEditor(await deps.planOf(i.userId).catch(() => null), "autosave"));
  if (!deps.drafts) throw new StudioError(503, "drafts_unavailable", "Drafts are kept in this browser only for now.");
  await owned(deps, i.userId, i.projectId);
  const d = checkModelDoc(i.doc);
  if (!d.ok) throw new StudioError(400, "bad_doc", d.error);
  if (d.doc.name !== i.key) throw new StudioError(400, "bad_doc", "the model name must match its key");
  const updatedAt = new Date().toISOString();
  await deps.drafts.put({ ownerRef: i.userId, projectId: i.projectId, key: i.key, baseAssetId: i.baseAssetId, baseHeadId: i.baseHeadId, doc: d.doc, updatedAt });
  return { updatedAt, sha256: docSha(d.doc) };
}

