export type Overlap = { id: string; kind: NodeKind; node: string; field: string | null; label: string; ours: unknown; theirs: unknown; resolution: "ours" | "theirs" };
export type MergeOptions = { accept?: ReadonlySet<string> | null; resolve?: Readonly<Record<string, "ours" | "theirs">> };
