const fl = (f: string) => FIELD_LABEL[f] ?? f;

function nodesOf(d: ModelDoc): Map<string, Node> {
  const out = new Map<string, Node>();
  const boneName = new Map(d.bones.map((b) => [b.id, b.name]));
  let i = 0;
  const put = (kind: NodeKind, key: string, value: Rec, label: string) => out.set(`${kind}:${key}`, { kind, key, value, order: i++, label });
  put("meta", "meta", { ...d.meta } as Rec, "model settings");
  for (const [k, c] of Object.entries(d.palette)) put("palette", k, { color: c }, `colour ${k}`);
  for (const b of d.bones) { const { id, hidden: _h, locked: _l, ...v } = b; void _h; void _l; put("bone", id, v as Rec, b.name); }
  const cubeIdx = new Map<string, number>();
  for (const c of d.cubes) {
    const n = cubeIdx.get(c.bone) ?? 0; cubeIdx.set(c.bone, n + 1);
    const { id, hidden: _h, locked: _l, from, to, pivot, ...v } = c; void _h; void _l;
    // the box (from, to and the pivot that follows it) merges as ONE field: half a resize is never a valid edit
    put("cube", id, { ...v, box: { from, to, pivot } } as Rec, `${boneName.get(c.bone) ?? "?"} · ${c.label ?? `cube ${n}`}`);
  }
  for (const cl of d.clips) {
    put("clip", cl.name, { length: cl.length, loop: cl.loop }, `clip ${cl.name}`);
    for (const e of cl.events ?? []) put("event", e.id, { clip: cl.name, t: e.t, name: e.name, ...(e.data ? { data: e.data } : {}) }, `${cl.name} event ${e.name}`);
    for (const t of cl.tracks) {
      const tk = trackKey(cl.name, t.bone, t.channel);
      put("track", tk, t.wave ? { wave: t.wave } : { keyed: true }, `${cl.name} ${boneName.get(t.bone) ?? "?"} ${t.channel}`);
      for (const k of t.keys ?? []) put("key", k.id, { track: tk, t: k.t, v: k.v, ease: k.ease }, `${cl.name} ${boneName.get(t.bone) ?? "?"} ${t.channel} key`);
    }
  }
  return out;
}

