  }

  // 5. revision + asset rows (idempotent)
  const manifest: ManifestEntry[] = [
    ...(build.jarName && build.jarSha256 ? [{ path: `plugin/${build.jarName}`, sha256: build.jarSha256, role: "artifact" as const }] : []),
    ...ok.map((c) => ({ path: `assets/textures/${c.name}.json`, sha256: studio.get(c.name)?.sha256 ?? c.specSha256, role: "asset" as const })),
    ...budget.keep.map((c) => ({ path: `assets/sounds/${c.set}.json`, sha256: c.specSha256, role: "asset" as const })),
    ...cre.ok.flatMap((c) => [
      { path: `assets/creatures/${c.name}.json`, sha256: c.specSha256, role: "asset" as const },
      { path: `bettermodel/${c.key}.bbmodel`, sha256: c.compiled.bbmodelSha256, role: "asset" as const },
    ]),
    ...(pack && packSha256 ? [{ path: `resourcepack/${pack.sha1}.zip`, sha256: packSha256, role: "resourcePack" as const }] : []),
    ...dps.flatMap((d) => [{ path: `assets/datapack/${d.name}.json`, sha256: d.specSha256, role: "asset" as const }, { path: `datapack/${d.name}-${build.mcVersion}.zip`, sha256: d.pack.sha256, role: "dataPack" as const }]),
    ...dzs.map((d) => ({ path: `assets/designs/${d.name}.json`, sha256: d.specSha256, role: "asset" as const })),
    ...(pack ? ims.map((x) => ({ path: `assets/itemmodels/${x.name}.json`, sha256: x.specSha256, role: "asset" as const })) : []),
  ];
  const parts = [
    ...(ok.length ? [`${ok.length} custom texture${ok.length > 1 ? "s" : ""}`] : []),
    ...(pack && ims.length ? [`${ims.length} stateful item model${ims.length > 1 ? "s" : ""}`] : []),
    ...(dps.length ? [`${dps.length} data pack${dps.length > 1 ? "s" : ""} (${dps.reduce((n, d) => n + d.spec.resources.length, 0)} resources)`] : []),
    ...(cre.ok.length ? [`${cre.ok.length} animated creature${cre.ok.length > 1 ? "s" : ""}`] : []),
    ...((n) => (n ? [`${n} item design${n > 1 ? "s" : ""}`] : []))(dzs.filter((d) => d.kind === "item").length),
    ...((n) => (n ? [`${n} menu${n > 1 ? "s" : ""}`] : []))(dzs.filter((d) => d.kind === "menu").length),
    ...((n) => (n ? [`${n} quest${n > 1 ? "s" : ""}`] : []))(dzs.filter((d) => d.kind === "quest").length),
    ...((n) => (n ? [`${n} boss${n > 1 ? "es" : ""}`] : []))(dzs.filter((d) => d.kind === "boss").length),
    ...((n) => (n ? [`${n} encounter${n > 1 ? "s" : ""}`] : []))(dzs.filter((d) => d.kind === "encounter").length),
    ...((n) => (n ? [`${n} HUD${n > 1 ? "s" : ""}`] : []))(dzs.filter((d) => d.kind === "hud").length),
    ...(budget.keep.length ? [`${accepted.length} custom sound event${accepted.length === 1 ? "" : "s"}${base.soundRender !== "rendered" ? ` (${budget.keep.length} set${budget.keep.length > 1 ? "s" : ""} not rendered: ${base.soundRender})` : ""}`] : []),
  ];
  const toolchain = [
    ...(ok.length ? [`cyrus-textures ${QUALITY_VERSION} (service ${ar.qualityVersion})`] : []),
    ...(renderTool ? [`cyrus-sound ${renderTool.render}/${renderTool.quality} on ${renderHostId} (${renderTool.ffmpeg.replace(/ Copyright.*$/, "")})`] : []),
    ...(cre.ok.length ? [`cyrus-creature ${COMPILER_VERSION}/${SKIN_QUALITY_VERSION} (bbmodel 5.0 for BetterModel 3.5.0)`] : []),
    ...(pack && ims.length ? [`${ITEMMODEL_EMITTER_VERSION}`] : []),
    ...(pack ? [`pack format ${pack.packFormat}`] : []),
    ...(dps.length ? [`cyrus-datapack ${EMITTER_VERSION} data pack format ${dps[0].pack.format.major}.${dps[0].pack.format.minor} for ${build.mcVersion}`] : []),
    ...(dzc.compiled ? [`${dzc.compiled.compiler} ${dzc.compiled.library} ${dzc.compiled.libraryHash.slice(0, 12)} for ${build.mcVersion}`] : []),
  ].join("; ");
  let revisionId: string | null = null;
  for (let attempt = 0; attempt < 4 && !revisionId; attempt++) {
    const found = await deps.findRevisionForBuild(project.id, build.id);
    if (found) { revisionId = found.id; break; }
    const head = await deps.headRevisionId(project.id);
    try {
      const rev = await deps.addRevision(project.id, {
        kind: "generated", manifest, modBuildId: build.id, status: "passed", expectedHeadId: head,
        engine: { ...(ar.promptVersion ? { promptVersion: ar.promptVersion } : ar.datapackPromptVersion ? { promptVersion: ar.datapackPromptVersion } : ar.designPromptVersion ? { promptVersion: ar.designPromptVersion } : {}), toolchain, ...(build.engineRelease ? { release: build.engineRelease } : {}) },
        message: clip(`${parts.join(" + ")}${pack ? `; pack ${pack.sha1.slice(0, 12)}` : ""}${ar.kept ? " (kept unchanged)" : ""}`, 200),
      });
      revisionId = rev.id;
    } catch (e) {
      if ((e as { code?: string }).code === "stale_head") continue; // someone appended meanwhile: look again
      throw e;
    }
  }
  if (!revisionId) throw new Error("could not record the asset revision (the project kept moving)");
  for (const c of ok) {
    const d = studio.get(c.name);
    if (d) {
      await deps.recordAsset(project.id, {
        revisionId, assetKey: c.name, kind: "texture", sha256: d.sha256, size: Buffer.byteLength(d.canonical), origin: "edited",
        mime: TEXTURE_DOC_MIME, path: `assets/textures/${c.name}.json`,
        provenance: { generator: "cyrus-texture-studio", doc: d.doc, quality: d.quality, pngSha256: d.pngSha256, packSha1: pack?.sha1 ?? null, modBuildId: build.id, kept: true, keptStudioEdit: true, buildSpecSha256: c.specSha256 },
      });
      continue;
    }
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.name, kind: "texture", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: TEXTURE_SPEC_MIME, path: `assets/textures/${c.name}.json`,
      provenance: { generator: "cyrus-texture-dsl", spec: c.spec, quality: c.quality, pngSha256: c.pngSha256, packSha1: pack?.sha1 ?? null, modBuildId: build.id, kept: ar.kept === true },
    });
  }
  if (pack) for (const x of ims) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: x.name, kind: "itemmodel", sha256: x.specSha256, size: Buffer.byteLength(x.canonical), origin: "generated",
      mime: ITEMMODEL_SPEC_MIME, path: `assets/itemmodels/${x.name}.json`,
      provenance: { generator: "cyrus-itemmodel", emitter: ITEMMODEL_EMITTER_VERSION, spec: x.spec, needs: x.needs, version: build.mcVersion, packSha1: pack.sha1, modBuildId: build.id, kept: ar.kept === true || (ar.keptKinds ?? []).includes("itemmodel") },
    });
  }
  for (const c of budget.keep) {
    const evs = accepted.filter((e) => e.set === c.set);
    const st = studioSounds.get(c.set);
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.set, kind: "sound", sha256: st ? st.sha256 : c.specSha256, size: Buffer.byteLength(st ? st.canonical : c.canonical), origin: st ? "edited" : "generated",
      mime: st ? SOUND_DOC_MIME : SOUND_SPEC_MIME, path: `assets/sounds/${c.set}.json`,
      provenance: {
        ...(st ? { doc: st.doc, keptStudioEdit: true, buildSpecSha256: st.buildSpecSha256 } : {}),
        generator: st ? "cyrus-sound-studio" : "cyrus-soundspec", spec: c.spec, render: base.soundRender, renderHost: renderHostId, tool: renderTool,
        events: evs.map((e) => ({ event: e.event, key: `${project!.namespace}:${c.set}.${e.event}`, subtitle: e.subtitle, files: e.files.map((f) => ({ index: f.index, weight: f.weight, oggSha256: f.oggSha256, pcmSha256: f.pcmSha256, bytes: f.bytes, durationS: f.encoded.durationS, measure: f.measure, quality: f.quality, render: f.render })) })),
        ledger: ledgerOf(c), packSha1: pack?.sha1 ?? null, modBuildId: build.id, kept: ar.kept === true || (ar.keptKinds ?? []).includes("sound"),
      },
    });
  }
  for (const d of dps) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: d.name, kind: "datapack", sha256: d.specSha256, size: Buffer.byteLength(d.canonical), origin: "generated",
      mime: DATAPACK_SPEC_MIME, path: `assets/datapack/${d.name}.json`,
      provenance: {
        generator: "cyrus-datapack", emitter: d.pack.emitter, spec: d.spec, version: build.mcVersion, format: d.pack.format, packSha256: d.pack.sha256, packSha1: d.pack.sha1,
        bytes: d.pack.bytes, counts: d.pack.counts, apply: d.pack.apply, checks: d.pack.checks, warnings: d.pack.warnings.slice(0, 10), serviceAgreed: d.serviceAgreed,
        ...(d.pack.worldgen ? { worldgen: true, worldgenSummary: d.pack.worldgen } : {}),
        modBuildId: build.id, kept: (ar.keptKinds ?? []).includes("datapack"),
      },
    });
  }
  for (const c of cre.ok) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.name, kind: "model", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: RIG_SPEC_MIME, path: `assets/creatures/${c.name}.json`,
      provenance: {
        generator: "cyrus-rigspec", compiler: COMPILER_VERSION, engine: "bettermodel@3.5.0", spec: c.input, modelKey: c.key,
        bbmodelSha256: c.compiled.bbmodelSha256, pngSha256: c.compiled.pngSha256, skinSize: c.compiled.layout.size, stats: c.compiled.stats,
        quality: c.quality, warnings: c.warnings, modBuildId: build.id, kept: ar.kept === true || (ar.keptKinds ?? []).includes("creature"),
      },
    });
  }
  if (cre.ok.length) notices.push("Animated creatures are delivered by the Nxeon-managed BetterModel plugin, which builds their resource pack on the server; players accept a resource pack on join.");
  for (const d of dzs) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: d.name, kind: "design", sha256: d.specSha256, size: Buffer.byteLength(d.canonical), origin: "generated",
      mime: DESIGN_KIND_MIME[d.kind], path: `assets/designs/${d.name}.json`,
      provenance: {
        generator: "cyrus-designer", ...(d.kind !== "item" ? { designKind: d.kind } : {}), compiler: dzc.compiled?.compiler ?? null, library: dzc.compiled?.library ?? null, libraryHash: dzc.compiled?.libraryHash ?? null, spec: d.design, version: build.mcVersion,
        compileHash: dzc.compiled?.hash ?? null, configVersion: dzc.compiled?.configVersion ?? null, serviceAgreed: dzc.serviceAgreed, javacVerified: dzc.compiled?.javacVerified ?? false,
        modBuildId: build.id, kept: (ar.keptKinds ?? []).includes("design"),
      },
    });
  }
  const dzRows: NonNullable<MbAssets["designs"]> = dzs.map((d) => ({ name: d.name, version: build.mcVersion, specSha256: d.specSha256, compileHash: dzc.compiled?.hash ?? "", serviceAgreed: dzc.serviceAgreed, configVersion: dzc.compiled?.configVersion ?? 1, settings: dzc.compiled?.params.filter((p) => p.item === d.name).length ?? 0, abilities: "abilities" in d.design ? d.design.abilities.length : 0, ...(d.kind !== "item" ? { kind: d.kind } : {}) }));
  return {
    ...base, status: !pack ? "none" : url ? "ready" : "unhosted", revisionId, textures,
    ...(ar.itemModels ? { itemModels: pack ? ims.map((x) => ({ name: x.name, model: `${project!.namespace}:${x.name}`, category: x.spec.category, specSha256: x.specSha256, states: (x.spec.states ?? []).map((s) => ({ id: s.id, texture: s.texture })), modes: x.needs.modes, flags: x.needs.flags, use: x.needs.use })) : [] } : {}), ...(ar.datapacks ? { datapacks: dpRows } : {}), ...(ar.designs ? { designs: dzRows } : {}), ...(hasSounds ? { sounds: soundRows } : {}), ...(hasCreatures ? { creatures: creatureRows } : {}), notices,
    pack: pack && packSha256 ? { sha1: pack.sha1, sha256: packSha256, bytes: pack.bytes, format: pack.packFormat, clientVerified: pack.packClientVerified, url } : null,
    loader,
  };
}

/** Read ModBuild.result.assets defensively (old rows have none). */
export function readBuildAssets(result: unknown): MbAssets | null {
  const a = (result as { assets?: unknown } | null)?.assets as MbAssets | undefined;
  if (!a || typeof a !== "object" || !Array.isArray(a.textures) || typeof a.namespace !== "string") return null;
  return a;
}

// Cyrus Model Studio (Layer 1): the ModelDoc v1, the one saveable unit of a paint session (plan section 2 "Data model
// additions"). Pure + client-safe; the API runs checkModelDoc on every save and every draft.
//   { v: 1, kind, name, base, tex, layers, symmetry, log? }
//   base     what was painted on, by reference + hash: a creature's RigSpec row (the spec itself rides along so the
//            doc is self-contained for the future skin compile), an item texture (its TextureDoc row), or a glTF mesh
//   layers   per-channel lossless paint layers ("rle1", ./layers.ts), bottom to top
//   log      the op count + sha256 of the canonical op log that produced the layers since the base (provenance;
//            the server re-plays a log it is sent and refuses a save whose pixels do not match it)
// The spec stays the build-service contract: painting never edits the RigSpec / TextureSpec, it only adds layers.
import { BLEND_MODES, decodePixels, encodePixels, LAYER_ID, MAX_LAYERS, PAINT_CHANNELS, type BlendMode, type LayerSet, type PaintChannel } from "./layers";
import type { ModelKind } from "./scene";

export const MODELDOC_MIME = "application/vnd.cyrus.modeldoc+json";
export const MODELDOC_VERSION = 1 as const;
export const TEX_SIZES = [16, 32, 64, 128, 256, 512, 1024, 2048] as const;
/** total encoded layer data per doc (a 2048^2 sheet with heavy paint is a few MB; Minecraft items and skins are KBs) */
export const MAX_LAYER_CHARS = 6 * 1024 * 1024;
export const MAX_DOC_BYTES = 8 * 1024 * 1024;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;
const SHA = /^[0-9a-f]{64}$/;
const ID = /^[A-Za-z0-9_-]{1,64}$/;

export type ModelBase =
  | { type: "rigspec"; assetId: string | null; sha256: string; spec: unknown }
  | { type: "texture"; key: string; assetId: string | null; sha256: string }
  | { type: "gltf"; sha256: string; path: string | null };
export type EncodedLayer = { id: string; name: string; channel: PaintChannel; blend: BlendMode; opacity: number; visible: boolean; rle: string };
export type ModelDoc = {
  v: 1;
  kind: ModelKind;
  name: string;
  base: ModelBase;
  tex: { w: number; h: number };
  layers: EncodedLayer[];
  symmetry: "none" | "x";
  log?: { ops: number; folded: number; sha256: string };
};

export const encodeLayers = (set: LayerSet): EncodedLayer[] => set.layers.map((l) => ({ id: l.id, name: l.name, channel: l.channel, blend: l.blend, opacity: l.opacity, visible: l.visible, rle: encodePixels(l.px) }));

export function decodeLayers(doc: Pick<ModelDoc, "tex" | "layers">): LayerSet | null {
  const n = doc.tex.w * doc.tex.h;
  const layers = [];
  for (const l of doc.layers) { const px = decodePixels(l.rle, n); if (!px) return null; layers.push({ id: l.id, name: l.name, channel: l.channel, blend: l.blend, opacity: l.opacity, visible: l.visible, px }); }
  return { w: doc.tex.w, h: doc.tex.h, layers };
}

export type DocCheck = { ok: true; doc: ModelDoc; layers: LayerSet } | { ok: false; error: string };

const int = (v: unknown, lo: number, hi: number): v is number => typeof v === "number" && Number.isInteger(v) && v >= lo && v <= hi;

/** Validate an untrusted ModelDoc. Never throws. */
export function checkModelDoc(raw: unknown): DocCheck {
  const no = (error: string): DocCheck => ({ ok: false, error });
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return no("the model doc must be an object");
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!["v", "kind", "name", "base", "tex", "layers", "symmetry", "log"].includes(k)) return no(`unknown field ${k}`);
  if (r.v !== MODELDOC_VERSION) return no("model doc version must be 1");
  if (r.kind !== "creature" && r.kind !== "item3d" && r.kind !== "mesh") return no("kind must be creature, item3d or mesh");
  if (typeof r.name !== "string" || !NAME.test(r.name)) return no("name must be lowercase letters, digits and underscores (2-32 chars)");
  const t = r.tex as Record<string, unknown> | undefined;
  if (!t || !(TEX_SIZES as readonly unknown[]).includes(t.w) || !(TEX_SIZES as readonly unknown[]).includes(t.h)) return no(`texture size must be one of ${TEX_SIZES.join(", ")}`);
  const tex = { w: t.w as number, h: t.h as number };
  const b = r.base as Record<string, unknown> | undefined;
  let base: ModelBase;
  if (!b || typeof b !== "object") return no("base is required");
  if (b.type === "rigspec") {
    if (r.kind !== "creature") return no("a rigspec base belongs to a creature");
    if (!(b.assetId === null || (typeof b.assetId === "string" && ID.test(b.assetId))) || typeof b.sha256 !== "string" || !SHA.test(b.sha256) || !b.spec || typeof b.spec !== "object") return no("base: rigspec needs assetId, sha256 and spec");
    base = { type: "rigspec", assetId: b.assetId as string | null, sha256: b.sha256, spec: b.spec };
  } else if (b.type === "texture") {
    if (r.kind !== "item3d") return no("a texture base belongs to an item");
    if (typeof b.key !== "string" || !NAME.test(b.key) || !(b.assetId === null || (typeof b.assetId === "string" && ID.test(b.assetId))) || typeof b.sha256 !== "string" || !SHA.test(b.sha256)) return no("base: texture needs key, assetId and sha256");
    base = { type: "texture", key: b.key, assetId: b.assetId as string | null, sha256: b.sha256 };
  } else if (b.type === "gltf") {
    if (r.kind !== "mesh") return no("a glTF base belongs to a mesh");
    if (typeof b.sha256 !== "string" || !SHA.test(b.sha256) || !(b.path === null || (typeof b.path === "string" && b.path.length <= 200 && !b.path.includes(".."))) ) return no("base: gltf needs sha256 and path");
    base = { type: "gltf", sha256: b.sha256, path: b.path as string | null };
  } else return no("base type must be rigspec, texture or gltf");
  if (!Array.isArray(r.layers) || r.layers.length > MAX_LAYERS) return no(`at most ${MAX_LAYERS} layers`);
  const ids = new Set<string>();
  let chars = 0;
  const layers: EncodedLayer[] = [];
  for (const [i, x] of (r.layers as unknown[]).entries()) {
    const l = x as Record<string, unknown>;
    if (!l || typeof l !== "object") return no(`layers[${i}] must be an object`);
    for (const k of Object.keys(l)) if (!["id", "name", "channel", "blend", "opacity", "visible", "rle"].includes(k)) return no(`layers[${i}]: unknown field ${k}`);
    if (typeof l.id !== "string" || !LAYER_ID.test(l.id) || ids.has(l.id)) return no(`layers[${i}]: id must be unique, lowercase, 1-24 chars`);
    ids.add(l.id);
    if (typeof l.name !== "string" || !/^[^\u0000-\u001f]{1,32}$/.test(l.name)) return no(`layers[${i}]: name must be 1-32 characters`);
    if (!(PAINT_CHANNELS as readonly unknown[]).includes(l.channel)) return no(`layers[${i}]: channel must be one of ${PAINT_CHANNELS.join(", ")}`);
    if (!(BLEND_MODES as readonly unknown[]).includes(l.blend)) return no(`layers[${i}]: blend must be one of ${BLEND_MODES.join(", ")}`);
    if (!int(l.opacity, 0, 255) || typeof l.visible !== "boolean" || typeof l.rle !== "string") return no(`layers[${i}]: opacity 0-255, visible and rle are required`);
    chars += l.rle.length;
    if (chars > MAX_LAYER_CHARS) return no("the paint layers are too large for one model doc");
    layers.push({ id: l.id, name: l.name, channel: l.channel as PaintChannel, blend: l.blend as BlendMode, opacity: l.opacity, visible: l.visible, rle: l.rle });
  }
  if (r.symmetry !== "none" && r.symmetry !== "x") return no("symmetry must be none or x");
  let log: ModelDoc["log"];
  if (r.log !== undefined) {
    const g = r.log as Record<string, unknown>;
    if (!g || !int(g.ops, 0, 1_000_000) || !int(g.folded, 0, 1_000_000) || typeof g.sha256 !== "string" || !SHA.test(g.sha256)) return no("log must be { ops, folded, sha256 }");
    log = { ops: g.ops, folded: g.folded, sha256: g.sha256 };
  }
  const doc: ModelDoc = { v: 1, kind: r.kind, name: r.name, base, tex, layers, symmetry: r.symmetry, ...(log ? { log } : {}) };
  const set = decodeLayers(doc);
  if (!set) return no("a paint layer's pixel data is malformed or the wrong size");
  return { ok: true, doc, layers: set };
}

/**
 * The layers a session STARTS from (client and server agree on this, so the server can replay the op log): the saved
 * doc's layers, else one empty albedo layer called "Paint".
 */
export function startLayers(saved: Pick<ModelDoc, "tex" | "layers"> | null, w: number, h: number): LayerSet {
  if (saved && saved.tex.w === w && saved.tex.h === h) { const s = decodeLayers(saved); if (s) return s; }
  return { w, h, layers: [{ id: "paint", name: "Paint", channel: "albedo", blend: "normal", opacity: 255, visible: true, px: new Uint8ClampedArray(w * h * 4) }] };
}
// Cyrus Model Studio (Layer 1): the SERVER service behind /api/cyrus/models/v1. Every dependency is injected: the
// Cyrus tables through the Texture Studio's StudioStore (lib/cyrus/studios/service.ts), the plan through planOf,
// drafts through DraftStore, the preview renderer through PreviewRenderer. ./deps.ts wires the real ones; tests use
// fakes. No Nxeon internals here.
//
// What a project holds that Model Studio paints (nothing new is invented):
//   creature  the newest CyrusProjectAsset kind "model" / RIG_SPEC_MIME row per key (a build's RigSpec), plus the
//             newest ModelDoc row (kind "model", MODELDOC_MIME) for that key = the saved paint layers
//   item3d    every item texture (not a block tile) = an extruded item, with the mod's ItemModelSpec contexts + states
// SAVE (one paint session = one revision, the Texture Studio's rules: expectedHeadId -> 409 stale_head, the plan gate
// first, fail closed):
//   creature  -> a NEW revision kind "asset" + a ModelDoc row. The paint is stored; compiling it into the delivered
//                BetterModel skin is NOT wired yet (next task, documented).
//   item3d    -> the albedo composite becomes the item's TextureDoc (spec untouched + paint layer) through the Texture
//                Studio's own saveTexture, so it ships in the pack exactly like a Texture Studio edit; the layers ride
//                along in the row's provenance so the next session reopens them losslessly.
import { canonicalJson, sha256Hex } from "../assets/textures";
import { canModelStudio, normalizePlan, PLAN_LABEL, type AssetDecision, type AssetPlan, type ModelStudioAction } from "../engine-core/asset-gate";
import type { ManifestEntry } from "../engine-core/revisions";
import { checkRigSpec, type RigSpec } from "../creature/spec";
import { layoutSkin, skinTextureSpec, type SkinLayout } from "../creature/compile";
import { RIG_SPEC_MIME } from "../creature/portal";
import type { TextureSpec } from "../textures/dsl";
import { render } from "../textures/render";
import { renderDoc, paintFromBuffers, MAX_PAINT_COLORS, type TextureDoc, type TextureSize } from "../studios/paint";
import { previewModel, type PreviewModel } from "../itemmodel/preview";
import {
  resolveItemModels, resolveTextures, saveTexture, soundCandidateIds, StudioError, textureCandidateIds,
  type AssetRow, type ProjectRow, type SaveResult, type StudioServiceDeps, type TextureEntry,
