// ---------------------------------------------------------------------------- deps

export type DraftRow = { projectId: string; ownerRef: string; assetKey: string; baseAssetId: string | null; baseHeadId: string | null; doc: unknown; updatedAt: Date | string };
export interface DraftStore {
  get(projectId: string, ownerRef: string, assetKey: string): Promise<DraftRow | null>;
  put(row: Omit<DraftRow, "updatedAt">): Promise<{ updatedAt: Date | string }>;
  drop(projectId: string, ownerRef: string, assetKey: string): Promise<void>;
}
export type ModelServiceDeps = StudioServiceDeps & {
  drafts: DraftStore;
  /** null = the server preview renderer is not configured here (the phone fallback then says so) */
  renderer: () => PreviewRenderer | null;
};

/** In-memory drafts (tests, and devhost when the table is not pushed). */
export function memoryDraftStore(): DraftStore & { rows: Map<string, DraftRow> } {
  const rows = new Map<string, DraftRow>();
  const k = (p: string, o: string, a: string) => `${p}|${o}|${a}`;
  return {
    rows,
    get: async (p, o, a) => rows.get(k(p, o, a)) ?? null,
    put: async (r) => { const updatedAt = new Date(); rows.set(k(r.projectId, r.ownerRef, r.assetKey), { ...r, updatedAt }); return { updatedAt }; },
    drop: async (p, o, a) => { rows.delete(k(p, o, a)); },
  };
}

// ---------------------------------------------------------------------------- the models view

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();
const iso = (d: Date | string) => new Date(d).toISOString();

export type PaintState = { assetId: string; revisionId: string; createdAt: string; doc: ModelDoc; stale: string | null };
export type CreatureModel = {
  kind: "creature"; key: string; label: string; assetId: string; sha256: string; revisionId: string; createdAt: string;
  /** the expanded RigSpec (rest pose geometry) + its skin layout + the skin's generated base spec (render it client side) */
  spec: RigSpec; layout: SkinLayout; skin: TextureSpec;
  stats: { bones: number; cubes: number };
  paint: PaintState | null;
  history: { assetId: string; revisionId: string; createdAt: string; label: string }[];
};
export type ItemModel = {
  kind: "item3d"; key: string; label: string; texture: TextureEntry;
  /** the doc the paint layers sit on (the current texture, or the base a Model Studio save started from) */
  base: { assetId: string; doc: TextureDoc };
  /** layers restored from the last Model Studio save of this texture (null = start with an empty layer) */
  paint: { doc: ModelDoc; assetId: string } | null;
  preview: PreviewModel;
};
export type ModelEntry = CreatureModel | ItemModel;
export type ModelsView = {
  project: { id: string; namespace: string; title: string | null; rootBuildId: string | null } | null;
  access: { plan: AssetPlan | null; planLabel: string; edit: AssetDecision; view: AssetDecision };
  headRevisionId: string | null;
  models: ModelEntry[];
  revisionSeq: Record<string, number>;
  mcVersion: string | null;
  renderer: string | null;
};

/** The current ModelDoc rows per key (newest first per key). */
function modelDocRows(rows: readonly AssetRow[]) {
  const out = new Map<string, { row: AssetRow; doc: ModelDoc }[]>();
  for (const r of rows) {
    if (r.kind !== "model" || r.mime !== MODELDOC_MIME) continue;
    const c = checkModelDoc(obj(r.provenance).doc);
    if (!c.ok) continue;
    out.set(r.assetKey, [...(out.get(r.assetKey) ?? []), { row: r, doc: c.doc }]);
  }
  for (const v of out.values()) v.sort((a, b) => ts(b.row.createdAt) - ts(a.row.createdAt) || (a.row.id < b.row.id ? 1 : -1));
  return out;
}

/** Pure: the models of a project from its asset rows. */
export function resolveModels(rows: readonly AssetRow[], candidateBuildIds: ReadonlySet<string>, ignoreBuildIds: ReadonlySet<string>): ModelEntry[] {
  const out: ModelEntry[] = [];
  const docs = modelDocRows(rows);
  // creatures: newest RigSpec row per key
  const rigs = new Map<string, AssetRow[]>();
  for (const r of rows) if (r.kind === "model" && r.mime === RIG_SPEC_MIME) rigs.set(r.assetKey, [...(rigs.get(r.assetKey) ?? []), r]);
  for (const [key, list] of rigs) {
    list.sort((a, b) => ts(b.createdAt) - ts(a.createdAt) || (a.id < b.id ? 1 : -1));
    const cur = list[0];
    const chk = checkRigSpec(obj(cur.provenance).spec);
    if (!chk.ok) continue;
    const lay = layoutSkin(chk.spec);
    if (!lay.ok) continue;
    const d = docs.get(key) ?? [];
    const latest = d[0];
    let paint: PaintState | null = null;
    if (latest) {
      const base = latest.doc.base;
      const stale = base.type !== "rigspec" ? "this paint was not made on a creature" : latest.doc.tex.w !== lay.layout.size ? `the creature's skin sheet changed size (${latest.doc.tex.w} -> ${lay.layout.size}); the paint was kept in history but not reapplied` : base.sha256 !== cur.sha256 ? "the creature changed in a later build; the paint is reapplied on the new shape and may not line up everywhere" : null;
      // a size change makes the layers unusable on this sheet: start fresh (the old doc stays in history)
      if (!(stale && latest.doc.tex.w !== lay.layout.size)) paint = { assetId: latest.row.id, revisionId: latest.row.revisionId, createdAt: iso(latest.row.createdAt), doc: latest.doc, stale };
    }
    out.push({
      kind: "creature", key, label: String(obj(chk.spec).displayName ?? key), assetId: cur.id, sha256: cur.sha256, revisionId: cur.revisionId, createdAt: iso(cur.createdAt),
      spec: chk.spec, layout: lay.layout, skin: skinTextureSpec(chk.spec, lay.layout),
      stats: { bones: chk.spec.bones.length, cubes: chk.spec.bones.reduce((n, b) => n + b.cubes.length, 0) },
      paint, history: d.slice(0, 20).map((x) => ({ assetId: x.row.id, revisionId: x.row.revisionId, createdAt: iso(x.row.createdAt), label: "Painted in Model Studio" })),
    });
  }
  // items: every item texture (block tiles are not held items)
  const textures = resolveTextures(rows, candidateBuildIds, ignoreBuildIds);
  const specs = resolveItemModels(rows);
  const byId = new Map(rows.map((r) => [r.id, r]));
  for (const t of textures) {
    if (t.doc.tile) continue;
    const row = byId.get(t.assetId);
    const ms = obj(obj(row?.provenance).modelStudio);
    let base: ItemModel["base"] = { assetId: t.assetId, doc: t.doc };
    let paint: ItemModel["paint"] = null;
    // reopen the layers of the last Model Studio save, only when its pixels are still exactly this texture's
    const md = checkModelDoc(ms.doc);
    const baseRow = typeof ms.baseAssetId === "string" ? byId.get(ms.baseAssetId) : undefined;
    const baseEntry = baseRow ? [...t.history].find((h) => h.assetId === baseRow.id) : undefined;
    if (md.ok && baseEntry && md.doc.tex.w === baseEntry.doc.size) {
      const comp = compositeChannel(md.layers, "albedo", imgOf(renderDoc(baseEntry.doc)));
      if (sameAlbedo(comp, imgOf(renderDoc(t.doc)))) { base = { assetId: baseEntry.assetId, doc: baseEntry.doc }; paint = { doc: md.doc, assetId: t.assetId }; }
    }
    out.push({ kind: "item3d", key: t.key, label: t.key, texture: t, base, paint, preview: previewModel(t.key, specs) });
  }
  return out;
}

export const imgOf = (r: { size: number; px: Uint8ClampedArray }): Img => ({ w: r.size, h: r.size, px: r.px });
/** Equal as the game sees it: alpha snapped at 128 (cutout), colour compared where opaque. */
function sameAlbedo(a: Img, b: Img): boolean {
  if (a.w !== b.w || a.h !== b.h) return false;
  for (let i = 0; i < a.w * a.h; i++) {
    const o = i * 4, oa = a.px[o + 3] >= 128, ob = b.px[o + 3] >= 128;
    if (oa !== ob) return false;
    if (oa && (a.px[o] !== b.px[o] || a.px[o + 1] !== b.px[o + 1] || a.px[o + 2] !== b.px[o + 2])) return false;
  }
  return true;
}

