  const key = previewKey(req, r.id);
  const hit = previewCache.get(key);
  if (hit) return { png: hit, key, cached: true, renderer: r.id };
  const out = await r.render(req);
  if (!out.ok) throw new StudioError(out.code === "bad_request" || out.code === "too_large" ? 400 : 503, `render_${out.code}`, out.error);
