describe("Model Studio L2: scene + camera (GPU-free)", () => {
  it("builds 6 faces per visible cube, hides hidden ones, picks the cube under the screen centre", () => {
    const d = docOf("banshee");
    const s = buildScene(d);
    assert.equal(s.faces.length, d.cubes.length * 6);
    const hid = ok(applyOp(d, { op: "setFlag", ids: [bone(d, "head").id], flag: "hidden", value: true })).doc;
    assert.ok(buildScene(hid).faces.length < s.faces.length);
    const cam = fitCamera(s, 600, 600, "front");
    const body = cubesOf(d, bone(d, "body").id)[0];
    const c = project(cam, [(body.from[0] + body.to[0]) / 2, (body.from[1] + body.to[1]) / 2, body.from[2]]);
    assert.ok(pickCube(s, cam, c.x, c.y));
    assert.equal(pickCube(s, cam, 2, 2), null);
  });
  it("axis drag converts screen pixels into units along the axis (y up = negative screen y)", () => {
    const cam = fitCamera({ min: [-8, 0, -8], max: [8, 16, 8] }, 400, 400, "front");
    const u = axisDrag(cam, [0, 8, 0], 1, 0, -cam.zoom * 2);
    assert.ok(Math.abs(u - 2) < 1e-9);
    assert.equal(axisDrag(cam, [0, 8, 0], 2, 10, 10), 0, "z points at the camera in the front view");
  });
});

