describe("scene time hooks (animation / effects are not built; these must not block them)", () => {
  it("playback clock: deterministic tick, loop, stop at the end, speed, scrub, subscribers", () => {
    const c = new PlaybackClock({ end: 2 });
    const seen: number[] = []; c.subscribe((s) => seen.push(Math.round(s.time * 1000) / 1000));
    c.tick(0.5); assert.equal(c.time, 0, "paused clocks do not move");
    c.play(); c.tick(0.5); c.tick(1); assert.equal(c.time, 1.5);
    c.tick(1); assert.equal(Math.round(c.time * 1000) / 1000, 0.5, "loops");
    c.setLoop(false); c.tick(5); assert.equal(c.time, 2); assert.equal(c.state.playing, false, "stops at the end");
    c.play(); assert.equal(c.time, 0, "play from the end restarts");
    c.setSpeed(2); c.tick(0.25); assert.equal(c.time, 0.5);
    c.seek(9); assert.equal(c.time, 2); c.seek(-1); assert.equal(c.time, 0);
    assert.ok(seen.length > 5);
  });
  it("per-node overrides from providers at time t; the posed scene keeps the pure pick exact", () => {
    const r = render(GLOCK), s = sceneFromItem("glock_9mm", imgOf(r));
    const slide = poseProvider("reload_slide", 1, (t) => new Map([[0, T4(-2 * t, 0, 0)]]));
    const lift = poseProvider("lift", 1, () => new Map([[0, T4(0, 1, 0)]]));
    const o = evalPose([slide, lift], 0.5, s);
    assert.deepEqual(apply4(o.get(0)!, [0, 0, 0]), [-1, 1, 0], "providers compose in order");
    const p = posedScene(s, o);
    assert.equal(p.bounds.min[0], s.bounds.min[0] - 1);
    const at = (sc: typeof s, dx: number) => pickScene(sc, { o: [(10 + 0.5) / 2 + dx, 16 - (12 + 0.5) / 2 + 1 * (sc === p ? 1 : 0), 20], d: [0, 0, -1] }, { alphaAt: (x, y) => r.px[(y * 32 + x) * 4 + 3] })!;
    assert.deepEqual(at(p, -1).texel, at(s, 0).texel, "the same texel is hit where the posed part now is");
    assert.equal(posedScene(s, new Map()), s);
    const j = overridesJson(o);
    const req = previewRequest(s, { albedo: imgOf(r) }, { preset: "front", time: 0.5, overrides: j });
    assert.equal(checkPreviewRequest(req), null);
    assert.equal(req.time, 0.5); assert.ok(req.parts);
    assert.notEqual(previewKey(req, "x"), previewKey({ ...req, time: 0.25 }, "x"), "time is part of the cache key");
    assert.notEqual(checkPreviewRequest({ ...req, overrides: { "0": [1, 2] } }), null);
  });
});

