import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { ModelEditor } from "@/components/cyrus/modelstudio/editor/ModelEditor";
import { modelEditorEnabled } from "@/lib/cyrus/modelstudio/editor/deps";
import { modelEditorAccess } from "@/lib/cyrus/modelstudio/editor/gate";
import { studioPlanOf } from "@/lib/cyrus/studios/deps";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Model Studio · Cyrus");
}

/**
 * Model Studio layer 2: the cuboid + bone editor (full page). Hidden (404) until the `cyrus_model_editor_enabled`
 * setting is on (default OFF; devhost can use CYRUS_MODEL_EDITOR_DEV=1 outside production). Viewing is never
 * plan-gated: a plan that may not edit models gets the same page read-only, and the API refuses its edits anyway.
 */
export default async function ModelEditorPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ model?: string | string[]; fakeCandidate?: string }> }) {
  const user = await requireModBuilderUser();
  if (!(await modelEditorEnabled())) notFound();
  const { id } = await params;
  const { mod } = await studioContext(id);
  const access = modelEditorAccess(await studioPlanOf()(user.id).catch(() => null));
  const q = await searchParams;
  const m = typeof q.model === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(q.model) ? q.model : null;
  return <ModelEditor mod={mod} initialKey={m} readOnly={!access.edit.ok} devFakeCandidate={process.env.NODE_ENV !== "production" && q.fakeCandidate === "1"} />;
}

