// Cyrus Model Studio: the PLAYBACK CLOCK object the layer-1 viewport, the Config Studio preview and tests subscribe to.
// There is ONE clock implementation: the game-neutral timeline clock (./editor/timeline/clock.ts, pure functions the
// layer-2 editor and the Motion core already use). This class is only a subscribable holder around it (the viewport
// ticks it from requestAnimationFrame while playing; tests and the server preview set it directly), so "the scene at
// time t" is reproducible everywhere and the two studios cannot drift apart. Pure + client-safe, no timers.
// Range: [start, end] in seconds; the timeline clock runs 0..(end - start) and this holder adds `start` back.
// Speed: clamped to the timeline clock's MIN_SPEED..MAX_SPEED (forward only; the old reverse playback had no caller).
import { clockInit, clockLoop, clockPause, clockPlay, clockScrub, clockSpeed, clockTick, type Clock } from "./editor/timeline/clock";
import type { Fired } from "./editor/timeline/sampler";

export type ClockState = { time: number; playing: boolean; speed: number; loop: boolean; start: number; end: number };
export type ClockListener = (s: Readonly<ClockState>) => void;

export class PlaybackClock {
  private c: Clock;
  private start: number;
  private s: ClockState;
  private subs = new Set<ClockListener>();
  /** instants (clip events, cues) the last tick crossed; empty unless a clip is attached by the caller */
  lastFired: Fired[] = [];
  constructor(o: Partial<ClockState> = {}) {
    this.start = o.start ?? 0;
