// ------------------------------------------------------------------------------------------- the ONE orbit camera ----
// Both studios (the layer-1 paint viewport and the layer-2 cuboid editor) frame, project and pick through these, so a
// screen point means the same world point in the three.js view, the 2D fallback, the pure pick and the gizmo maths.
export type CamPreset = "persp" | "front" | "side" | "top";
/** yaw/pitch per preset for a model that faces +z; creatures face north (-z) and add `facing` 180 */
export const CAM_PRESETS: Record<CamPreset, { yaw: number; pitch: number }> = { persp: { yaw: -32, pitch: 20 }, front: { yaw: 0, pitch: 0 }, side: { yaw: -90, pitch: 0 }, top: { yaw: 0, pitch: 89 } };
export const DEFAULT_FOV = 30;

/** An orbit camera that frames the box [min, max] in a W x H view (the bounding sphere fits the shorter side). */
export function fitOrbit(min: V3, max: V3, W: number, H: number, preset: CamPreset = "persp", facing = 0, fov = DEFAULT_FOV): OrbitCam {
  const target: V3 = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2];
  const r = Math.max(1e-3, len3(sub3(max, min)) / 2);
  const asp = Math.min(1, (W || 1) / (H || 1));
  return { yaw: CAM_PRESETS[preset].yaw + facing, pitch: CAM_PRESETS[preset].pitch, dist: (r / Math.sin(rad(fov) / 2)) * (1.3 / asp), target, fov };
}

/** The camera basis (eye, forward, right, up) shared by rayFromOrbit and projectOrbit. */
function basis(c: OrbitCam): { eye: V3; f: V3; r: V3; u: V3 } {
  const eye = camEye(c);
  const f = norm3(sub3(c.target, eye));
  const up: V3 = Math.abs(f[1]) > 0.999 ? [0, 0, -Math.sign(f[1])] : [0, 1, 0];
  const r = norm3(cross3(f, up));
  return { eye, f, r, u: cross3(r, f) };
}

/** World point -> pixel (x, y) of a W x H view + depth along the view direction (larger = farther). Inverse of rayFromOrbit. */
export function projectOrbit(c: OrbitCam, p: V3, W: number, H: number): { x: number; y: number; z: number } {
  const { eye, f, r, u } = basis(c);
  const d = sub3(p, eye);
  const z = dot3(d, f);
  const t = Math.tan(rad(c.fov) / 2);
  const zz = Math.max(1e-6, z);
  const nx = dot3(d, r) / (zz * t * (W / H)), ny = dot3(d, u) / (zz * t);
  return { x: ((nx + 1) * W) / 2, y: ((1 - ny) * H) / 2, z };
}

/** Screen pixels per world unit at point p (perspective: shrinks with depth). */
export function pxPerUnit(c: OrbitCam, p: V3, H: number): number {
  const { eye, f } = basis(c);
  return H / (2 * Math.max(1e-6, dot3(sub3(p, eye), f)) * Math.tan(rad(c.fov) / 2));
}
EOF
