export const canvasViewport: ModelViewportFactory = (canvas, opts) => {
  const ctx = canvas.getContext("2d");
  const fit = () => {
    const dpr = Math.min(opts.maxDpr, window.devicePixelRatio || 1);
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) { canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr); }
    return dpr;
  };
  return {
    draw(f) {
      if (!ctx) return;
      const dpr = fit();
      const { camera: cam, scene } = f;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, cam.width, cam.height);
      const light = f.theme === "light";
      // floor grid on y = 0 (one block = 16 units, lines every 4 units)
      ctx.lineWidth = 1;
      for (let i = -32; i <= 32; i += 4) {
        const major = i % 16 === 0;
        ctx.strokeStyle = light ? `rgba(60,40,140,${major ? 0.16 : 0.07})` : `rgba(170,150,255,${major ? 0.16 : 0.06})`;
        const a = project(cam, [i, 0, -32]), b = project(cam, [i, 0, 32]), c = project(cam, [-32, 0, i]), d = project(cam, [32, 0, i]);
        ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.moveTo(c.x, c.y); ctx.lineTo(d.x, d.y); ctx.stroke();
      }
      // faces back to front
      for (const { f: face, pts } of drawList(scene, cam)) {
        const sel = f.selected.has(face.cube);
        const lit = face.glow ? 1.05 : 0.62 + 0.38 * Math.max(0, face.normal[0] * LIGHT[0] + face.normal[1] * LIGHT[1] + face.normal[2] * LIGHT[2]);
        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < 4; i++) ctx.lineTo(pts[i].x, pts[i].y);
        ctx.closePath();
        if (!f.wire) { ctx.fillStyle = shade(face.color, lit); ctx.fill(); }
        ctx.strokeStyle = sel ? "#a78bfa" : f.wire ? (light ? "rgba(60,40,140,.55)" : "rgba(200,190,255,.55)") : "rgba(10,8,24,.35)";
        ctx.lineWidth = sel ? 2 : 1;
        ctx.stroke();
      }
      drawOverlay(ctx, f);
    },
    gizmoAxisAt,
    dispose() { /* nothing held */ },
  };
};

/** Selection outlines, bones and the gizmo: drawn over the 3D view by both renderers (same projection). */
export function drawOverlay(ctx: CanvasRenderingContext2D, f: ViewportFrame, o: { outlines?: boolean } = {}) {
  const cam = f.camera, scene = f.scene, light = f.theme === "light";
  if (o.outlines) {
    // the three.js view has no selection material: outline the selected cubes' visible faces instead
    ctx.lineWidth = 2; ctx.strokeStyle = "#a78bfa";
    for (const { f: face, pts } of drawList(scene, cam)) {
      if (!f.selected.has(face.cube)) continue;
      ctx.beginPath(); ctx.moveTo(pts[0].x, pts[0].y); for (let i = 1; i < 4; i++) ctx.lineTo(pts[i].x, pts[i].y); ctx.closePath(); ctx.stroke();
    }
  }
      // bones: parent -> child lines + pivot dots
  if (f.showBones) {
    for (const b of scene.bones) {
      const p = project(cam, b.at);
      if (b.parentAt) {
        const q = project(cam, b.parentAt);
        ctx.strokeStyle = light ? "rgba(109,61,240,.45)" : "rgba(167,139,250,.55)";
        ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(q.x, q.y); ctx.lineTo(p.x, p.y); ctx.stroke(); ctx.setLineDash([]);
      }
      const on = b.id === f.selectedBone;
      ctx.fillStyle = on ? "#a78bfa" : light ? "#ffffff" : "#1b1630";
      ctx.strokeStyle = on ? "#ffffff" : "#a78bfa";
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(p.x, p.y, on ? 5 : 3.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
  }
  // gizmo
  for (const h of gizmoHandles(f)) {
    const hot = f.hot === h.axis;
    ctx.strokeStyle = AX[h.axis]; ctx.fillStyle = AX[h.axis];
    ctx.lineWidth = hot ? 3.5 : 2.2;
    ctx.beginPath(); ctx.moveTo(h.o.x, h.o.y); ctx.lineTo(h.t.x, h.t.y); ctx.stroke();
    const k = f.gizmo!.kind;
    if (k === "resize") ctx.fillRect(h.t.x - 4, h.t.y - 4, 8, 8);
    else if (k === "rotate") { ctx.beginPath(); ctx.arc(h.t.x, h.t.y, hot ? 7 : 5.5, 0, Math.PI * 2); ctx.lineWidth = 2; ctx.stroke(); }
    else { const ang = Math.atan2(h.t.y - h.o.y, h.t.x - h.o.x); ctx.beginPath(); ctx.moveTo(h.t.x + Math.cos(ang) * 7, h.t.y + Math.sin(ang) * 7); ctx.lineTo(h.t.x + Math.cos(ang + 2.5) * 6, h.t.y + Math.sin(ang + 2.5) * 6); ctx.lineTo(h.t.x + Math.cos(ang - 2.5) * 6, h.t.y + Math.sin(ang - 2.5) * 6); ctx.closePath(); ctx.fill(); }
  }
  if (f.gizmo) { const o = project(cam, f.gizmo.origin); ctx.fillStyle = "#ffffff"; ctx.strokeStyle = "#7c4dff"; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(o.x, o.y, 4, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
}

export function gizmoAxisAt(f: ViewportFrame, x: number, y: number): 0 | 1 | 2 | null {
      let best: { axis: 0 | 1 | 2; d: number } | null = null;
      for (const h of gizmoHandles(f)) {
        const vx = h.t.x - h.o.x, vy = h.t.y - h.o.y, l2 = vx * vx + vy * vy || 1;
        const t = Math.max(0.2, Math.min(1.15, ((x - h.o.x) * vx + (y - h.o.y) * vy) / l2));
        const d = Math.hypot(h.o.x + vx * t - x, h.o.y + vy * t - y);
        if (d < 9 && (!best || d < best.d)) best = { axis: h.axis, d };
      }
      return best?.axis ?? null;
    }

}

export function gizmoAxisAt(f: ViewportFrame, x: number, y: number): 0 | 1 | 2 | null {
  let best: { axis: 0 | 1 | 2; d: number } | null = null;
  for (const h of gizmoHandles(f)) {
    const vx = h.t.x - h.o.x, vy = h.t.y - h.o.y, l2 = vx * vx + vy * vy || 1;
    const t = Math.max(0.2, Math.min(1.15, ((x - h.o.x) * vx + (y - h.o.y) * vy) / l2));
    const d = Math.hypot(h.o.x + vx * t - x, h.o.y + vy * t - y);
    if (d < 9 && (!best || d < best.d)) best = { axis: h.axis, d };
  }
  return best?.axis ?? null;
}

