"use client";
// Model Studio L2: the editor's REAL 3D view = the layer-1 three.js ModelViewport (components/cyrus/studios/
// model-viewport.ts), not a second renderer. The editor keeps its own state (doc, pose at the timeline clock's time,
// selection, gizmo) and hands each frame over as the shared layer-1 ModelScene (lib/cyrus/modelstudio/editor/scene.ts
// sceneToModelScene): same lighting presets, same orbit camera (setCamera with the editor's OrbitCam; picking and gizmo
// maths use the identical projectOrbit / rayFromOrbit), same wireframe, grid and DPR budget. Selection outlines, bones
// and the gizmo are drawn on a 2D overlay canvas through the same projection (./viewport-adapter.ts drawOverlay).
// three.js loads lazily (dynamic import inside ModelViewport.create), so the chunk stays on studio routes only.
// No WebGL (old phone, locked-down browser) -> falls back to the 2D canvasViewport, and says so in the frame label.
import { ModelViewport as ThreeView, webglOk } from "@/components/cyrus/studios/model-viewport";
import { sceneToModelScene, type EditorScene } from "@/lib/cyrus/modelstudio/editor/scene";
import type { LightingPreset } from "@/lib/cyrus/modelstudio/look";
import { canvasViewport, drawOverlay, gizmoAxisAt, type ModelViewport, type ModelViewportFactory, type ViewportFrame } from "./viewport-adapter";

export type ThreeViewportOpts = { lighting?: LightingPreset; onFallback?: (why: string) => void };

export function threeViewportFactory(o: ThreeViewportOpts = {}): ModelViewportFactory {
  return (canvas, opts) => {
    if (!webglOk()) { o.onFallback?.("WebGL is not available in this browser: showing the flat 2D view."); return canvasViewport(canvas, opts); }
    let view: ThreeView | null = null;
    let dead = false;
    let last: ViewportFrame | null = null;
    let shown: { scene: EditorScene; wire: boolean; light: boolean } | null = null;
    // the overlay: a sibling canvas on top of the WebGL one, never takes pointer events
    const ov = document.createElement("canvas");
    ov.className = "me-ov";
    ov.setAttribute("aria-hidden", "true");
    Object.assign(ov.style, { position: "absolute", inset: "0", width: "100%", height: "100%", pointerEvents: "none" });
    canvas.parentElement?.insertBefore(ov, canvas.nextSibling);
    const ctx = ov.getContext("2d");
    const apply = (f: ViewportFrame) => {
      if (!view) return;
      const light = f.theme === "light";
      if (!shown || shown.scene !== f.scene) {
        const m = sceneToModelScene(f.scene, "model");
        view.setScene(m.scene, { albedo: m.albedo, emissive: m.glow }, { pixel: true, keepCamera: true });
        view.setGrid(false);
      }
      if (!shown || shown.wire !== f.wire) view.setWire(f.wire);
      if (!shown || shown.light !== light) view.setTheme(light);
      shown = { scene: f.scene, wire: f.wire, light };
      view.setCamera(f.camera);
      view.requestRender();
      if (ctx) {
        const dpr = Math.min(opts.maxDpr, window.devicePixelRatio || 1);
        const w = ov.clientWidth, h = ov.clientHeight;
        if (ov.width !== Math.round(w * dpr) || ov.height !== Math.round(h * dpr)) { ov.width = Math.round(w * dpr); ov.height = Math.round(h * dpr); }
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, w, h);
        drawGrid(ctx, f);
        drawOverlay(ctx, f, { outlines: true });
      }
    };
    void ThreeView.create(canvas, { mobile: opts.maxDpr < 2, light: document.documentElement.getAttribute("data-theme") === "light", interactive: false }).then((v) => {
      if (dead) { v.dispose(); return; }
      view = v;
      if (o.lighting) v.setLighting(o.lighting);
      if (last) apply(last);
    }).catch(() => o.onFallback?.("The 3D view could not start: showing the flat 2D view."));
    const vp: ModelViewport & { setLighting(p: LightingPreset): void } = {
      draw(f) { last = f; apply(f); },
      gizmoAxisAt,
      setLighting(p) { view?.setLighting(p); },
      dispose() { dead = true; view?.dispose(); view = null; ov.remove(); },
    };
    return vp;
  };
}

/** The block grid on y = 0 (one block = 16 units, a line every 4), under the model: drawn on the overlay. */
import { project } from "@/lib/cyrus/modelstudio/editor/scene";
function drawGrid(ctx: CanvasRenderingContext2D, f: ViewportFrame) {
  const light = f.theme === "light", cam = f.camera;
  ctx.save();
  ctx.globalCompositeOperation = "destination-over";
  ctx.lineWidth = 1;
  for (let i = -32; i <= 32; i += 4) {
    const major = i % 16 === 0;
    ctx.strokeStyle = light ? `rgba(60,40,140,${major ? 0.16 : 0.07})` : `rgba(170,150,255,${major ? 0.16 : 0.06})`;
    const a = project(cam, [i, 0, -32]), b = project(cam, [i, 0, 32]), c = project(cam, [-32, 0, i]), d = project(cam, [32, 0, i]);
    ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.moveTo(c.x, c.y); ctx.lineTo(d.x, d.y); ctx.stroke();
  }
  ctx.restore();
}

