// BetterModel pack hand-off (Cyrus R3). BetterModel builds its OWN resource pack on the server at start (and on
// `/bettermodel reload`): `plugins/BetterModel/build.zip` (config pack-type zip, build-folder-location BetterModel/build,
// verified on Paper 26.2 with the pinned 3.5.0). Its item names are per model (`assets/bettermodel/items/b/<model key>_<bone>.json`)
// but its model files are numbered in load order (`models/b/a.json`, ...), so the pack belongs to the SERVER (every
// creature on it), not to one mod. Nxeon therefore:
//   1. reads build.zip from the server (GuestFs), checks it like any pack (zip check, pack.mcmeta, size cap, only
//      `assets/bettermodel/**` + pack.mcmeta/pack.png),
//   2. re-zips it deterministically (sorted entries, fixed timestamps): BetterModel writes the same CONTENT every start
//      but fresh zip timestamps (two real flights: identical CRCs, different zip sha), so without this every restart
//      would be a new sha1 and every player would re-download the pack,
//   3. publishes it content-addressed (packhost publishPack) and upserts ONE Pack Loader entry per server
//      (namespace nx_bmodel00, role "bettermodel"), next to each mod's own pack.
// Pure except the injected GuestFs/PackStore. OFF unless the caller is switched on (see deliver.ts).
import { createHash } from "node:crypto";
import type { HostGuestFs as GuestFs } from "../host/types";
import { readEntry, indexZip, isSymlinkEntry, DEFAULT_ZIP_LIMITS } from "../inventory/zipread";
import { inspectPackZip } from "../packhost/zipcheck";
import { publishPack } from "../packhost/publish";
import type { PackStore } from "../packhost/types";
import { applyPackChange, type LoaderConfig } from "../packhost/loader-config";
import { readLoaderConfig, writeLoaderConfig, MC_BASE } from "../packhost/deliver";
import { zip } from "../textures/zip";

/** Reserved pseudo-namespace for the server-level BetterModel pack entry (never a project namespace: not a hash). */
export const BETTERMODEL_PACK_NAMESPACE = "nx_bmodel00";
export const BETTERMODEL_PACK_ROLE = "bettermodel";
export const BETTERMODEL_BUILD_ZIP = "plugins/BetterModel/build.zip";
export const MAX_BETTERMODEL_PACK_BYTES = 32 * 1024 * 1024;
const ALLOWED = /^(pack\.mcmeta|pack\.png|assets\/bettermodel\/[a-z0-9_./-]+)$/;

export type Normalized = { ok: true; zip: Buffer; entries: number; bytes: number; contentSha256: string } | { ok: false; error: string };

/** Check BetterModel's build.zip and rewrite it deterministically (same content -> same bytes -> same sha1). */
export function normalizeBetterModelPack(buf: Buffer, opts: { maxBytes?: number } = {}): Normalized {
  const max = opts.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES;
  if (buf.length > max) return { ok: false, error: `BetterModel's pack is ${buf.length} bytes; the limit is ${max}` };
  const chk = inspectPackZip(buf, { maxEntries: 20000 });
  if (!chk.ok) return { ok: false, error: `BetterModel's pack is not a valid resource pack: ${chk.error}` };
  const idx = indexZip(buf, { ...DEFAULT_ZIP_LIMITS, maxTotalBytes: max, maxEntryBytes: Math.min(max, 8 * 1024 * 1024) });
  if (!idx.ok) return { ok: false, error: `unreadable zip: ${idx.error}` };
  if (idx.zip.unsafeNames.length || idx.zip.duplicateNames.length) return { ok: false, error: `unsafe or duplicate names in BetterModel's pack: ${[...idx.zip.unsafeNames, ...idx.zip.duplicateNames].slice(0, 3).join(", ")}` };
  const files: { path: string; data: Buffer }[] = [];
  for (const e of idx.zip.entries) {
    if (e.dir || e.name.endsWith("/")) continue;
    if (isSymlinkEntry(e)) return { ok: false, error: `symbolic link in BetterModel's pack: ${e.name.slice(0, 120)}` };
    if (!ALLOWED.test(e.name) || e.name.split("/").includes("..")) return { ok: false, error: `unexpected file in BetterModel's pack: ${e.name.slice(0, 120)}` };
    const r = readEntry(idx.zip, e);
    if (!r.ok) return { ok: false, error: `${e.name.slice(0, 120)}: ${r.error}` };
    files.push({ path: e.name, data: r.data });
  }
  if (!files.some((f) => f.path === "pack.mcmeta")) return { ok: false, error: "BetterModel's pack has no pack.mcmeta" };
  const out = zip(files);
  const h = createHash("sha256");
  for (const f of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) h.update(f.path).update("\0").update(createHash("sha256").update(f.data).digest());
  return { ok: true, zip: out, entries: files.length, bytes: out.length, contentSha256: h.digest("hex") };
}

export type HandoffResult =
  | { ok: true; action: "no_pack" | "added" | "updated" | "unchanged"; sha1?: string; url?: string; wrote: boolean; entries?: number }
  | { ok: false; error: string };

/**
 * After BetterModel (re)built its pack on a server: publish it and point the server's Pack Loader at it.
 * `prompt` is what players see in the accept dialog.
 */
export async function handoffBetterModelPack(deps: { fs: GuestFs; store: PackStore; maxBytes?: number; base?: string; prompt?: string; required?: boolean }): Promise<HandoffResult> {
  const base = deps.base ?? MC_BASE;
  const raw = await deps.fs.readFile(`${base}/${BETTERMODEL_BUILD_ZIP}`, (deps.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES) + 1);
  if (!raw) return { ok: true, action: "no_pack", wrote: false };
  const n = normalizeBetterModelPack(raw, { maxBytes: deps.maxBytes });
  if (!n.ok) return n;
  const pub = await publishPack(deps.store, n.zip, { maxBytes: deps.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES });
  if (!pub.ok) return { ok: false, error: `could not publish BetterModel's pack: ${pub.error}` };
  const cur = await readLoaderConfig(deps.fs, base);
  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
  const r = applyPackChange(cur.config, {
    op: "upsert", namespace: BETTERMODEL_PACK_NAMESPACE, role: BETTERMODEL_PACK_ROLE, sha1: pub.sha1,
    prompt: deps.prompt ?? "This server uses animated custom creatures. Accept the pack to see them.", required: deps.required ?? false, owner: "bettermodel",
  }, { urlFor: () => pub.url });
  if (!r.ok) return { ok: false, error: r.error };
  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config as LoaderConfig, base) : false;
  return { ok: true, action: r.action as "added" | "updated" | "unchanged", sha1: pub.sha1, url: pub.url, wrote, entries: n.entries };
}
// Portal half of the creature specs a build returns (Cyrus R3). The build service validated them with its generated
// JS copy of ./spec.ts; the portal never trusts that: it re-validates, compiles (.bbmodel + skin), runs the skin
// quality bar and identifies each RigSpec by the sha256 of its canonical JSON as WRITTEN (template form stays small).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { compileCreature, type CompiledCreature } from "./compile";
import { skinQuality, type SkinQuality } from "./quality";
import { checkRigSpec, MAX_CREATURES, MAX_RIG_SPEC_BYTES, modelKey, NAME_RE, type RigSpec } from "./spec";

export const RIG_SPEC_MIME = "application/vnd.nxeon.rig-spec+json";

export type CheckedCreature =
  | { ok: true; name: string; key: string; input: unknown; spec: RigSpec; specSha256: string; canonical: string; compiled: CompiledCreature; quality: SkinQuality; warnings: string[] }
  | { ok: false; name: string; reason: string };

export function checkReturnedCreature(c: { name?: unknown; spec?: unknown }, namespace: string): CheckedCreature {
  const name = typeof c.name === "string" && NAME_RE.test(c.name) ? c.name : "?";
  const canonical = canonicalJson(c.spec ?? null);
  if (Buffer.byteLength(canonical) > MAX_RIG_SPEC_BYTES) return { ok: false, name, reason: `the creature spec is larger than ${MAX_RIG_SPEC_BYTES / 1024} KB` };
  const chk = checkRigSpec(c.spec, { namespace });
  if (!chk.ok) return { ok: false, name, reason: chk.error };
  if (chk.spec.name !== name) return { ok: false, name, reason: `spec name ${chk.spec.name} does not match ${name}` };
  const r = compileCreature(chk.spec, namespace);
  if (!r.ok) return { ok: false, name, reason: r.error };
  const quality = skinQuality(r.creature.raster, r.creature.layout);
  if (quality.verdict === "fail") return { ok: false, name, reason: `the skin failed Nxeon's skin checks (${quality.checks.filter((q) => q.verdict === "fail").map((q) => q.id).join(", ")})` };
  return { ok: true, name, key: modelKey(namespace, name), input: c.spec, spec: chk.spec, specSha256: sha256Hex(canonical), canonical, compiled: r.creature, quality, warnings: chk.warnings };
}

/** Re-check every returned creature (at most MAX_CREATURES, first wins on a duplicate name). */
export function checkReturnedCreatures(list: { name?: unknown; spec?: unknown }[] | undefined, namespace: string): { ok: Extract<CheckedCreature, { ok: true }>[]; dropped: { name: string; reason: string }[] } {
  const ok: Extract<CheckedCreature, { ok: true }>[] = [];
  const dropped: { name: string; reason: string }[] = [];
  for (const c of (list ?? []).slice(0, MAX_CREATURES)) {
    const r = checkReturnedCreature(c, namespace);
    if (!r.ok) { dropped.push({ name: r.name, reason: r.reason }); continue; }
    if (ok.some((x) => x.name === r.name)) continue;
    ok.push(r);
  }
  return { ok, dropped };
}

// Creature delivery to ONE server (Cyrus R3, worker side, runs after the Mods engine installed/updated/removed a Cyrus
// mod's jar; same guest connection). For a build with creatures:
//   1. ensure the Nxeon-managed BetterModel (lib/cyrus/managed, ref-counted by project; pinned per family: the 1.21
//      family has NO pin, so this fails closed there),
//   2. write Nxeon's managed BetterModel config (plugins/BetterModel/config.yml) when it is missing or still Nxeon's,
//   3. write each creature's compiled model to plugins/BetterModel/models/<namespace>_<name>.bbmodel (re-compiled from
//      the stored RigSpec, refused when the bytes differ from what the build recorded) and remove this project's models
//      that the new version no longer has,
//   4. the server needs a restart (or `/bettermodel reload`): BetterModel then builds its pack, and the hand-off
//      (./handoff.ts) publishes it and points the Pack Loader at it.
// OFF unless BOTH CYRUS_MANAGED_PLUGINS_REAL=1 (the existing managed-plugin switch) and CYRUS_CREATURES=1: otherwise
// nothing here reads the database or touches a server.
import { readFileSync } from "node:fs";
import path from "node:path";
import type { HostGuestFs as GuestFs } from "../host/types";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { ensureManagedPlugin, releaseManagedPlugin, type ManagedDeps } from "../managed/service";
import { MC_BASE } from "../packhost/deliver";
import { compileCreature } from "./compile";
import { checkRigSpec, modelKey } from "./spec";

export const BETTERMODEL_KEY = "bettermodel";
export const CREATURES_FLAG = "CYRUS_CREATURES";
export const MODELS_DIR = "plugins/BetterModel/models";
export const CONFIG_PATH = "plugins/BetterModel/config.yml";
export const CONFIG_MARKER = "# Nxeon-managed BetterModel";

/** What ModBuild.result.assets.creatures stores per creature (lib/cyrus/assets/sync.ts). */
export type StoredCreature = { name: string; key: string; spec: unknown; bbmodelSha256: string };
export type CreatureDeliverDeps = { managed: ManagedDeps; fs: GuestFs; env?: Record<string, string | undefined>; base?: string; configTemplate?: () => string };
export type CreatureDeliverResult =
  | { ok: true; action: "switched_off" | "no_creatures" | "delivered" | "removed"; wrote: string[]; removed: string[]; restartRequired: boolean; bettermodel?: string; notes: string[] }
  | { ok: false; error: string };

export const creaturesSwitchedOn = (env: Record<string, string | undefined>) => env[MANAGED_REAL_FLAG] === "1" && env[CREATURES_FLAG] === "1";
export function managedConfigTemplate(): string {
  return readFileSync(path.join(__dirname, "../managed/bettermodel-config.yml"), "utf8");
}
const dependentFor = (projectId: string) => `project:${projectId}`;

/** Re-compile stored creatures and prove the bytes equal what the build recorded (shared with lib/cyrus/delivery). */
export function compileStoredCreatures(namespace: string, creatures: StoredCreature[]): { ok: true; files: { rel: string; data: Buffer }[] } | { ok: false; error: string } {
  const files: { rel: string; data: Buffer }[] = [];
  for (const c of creatures) {
    const chk = checkRigSpec(c.spec, { namespace });
    if (!chk.ok) return { ok: false, error: `creature ${c.name}: ${chk.error}` };
    const r = compileCreature(chk.spec, namespace);
    if (!r.ok) return { ok: false, error: `creature ${c.name}: ${r.error}` };
    if (r.creature.bbmodelSha256 !== c.bbmodelSha256 || r.creature.key !== modelKey(namespace, chk.spec.name)) return { ok: false, error: `creature ${c.name}: the model no longer compiles to the recorded bytes (compiler changed?); rebuild the mod` };
    files.push({ rel: `${MODELS_DIR}/${r.creature.key}.bbmodel`, data: Buffer.from(r.creature.bbmodel) });
  }
  return { ok: true, files };
}

export async function deliverCreatures(a: { serverId: string; mcVersion: string; namespace: string; projectId: string; creatures: StoredCreature[] }, deps: CreatureDeliverDeps): Promise<CreatureDeliverResult> {
  const env = deps.env ?? process.env;
  if (!creaturesSwitchedOn(env)) return { ok: true, action: "switched_off", wrote: [], removed: [], restartRequired: false, notes: [`animated creature delivery is switched off (${MANAGED_REAL_FLAG} and ${CREATURES_FLAG} must both be 1)`] };
  const base = deps.base ?? MC_BASE;
  // compile first: nothing touches the server unless every model re-compiles to the recorded bytes
  const compiled = compileStoredCreatures(a.namespace, a.creatures);
  if (!compiled.ok) return compiled;
  const files = compiled.files;
  const notes: string[] = [];
  let bettermodel: string | undefined;
  let restartRequired = false;
  if (files.length) {
    const ens = await ensureManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, mcVersion: a.mcVersion, dependent: dependentFor(a.projectId) });
    if (!ens.ok) return { ok: false, error: `BetterModel: ${ens.error}` };
    bettermodel = ens.action;
    if (ens.action === "installed" || ens.action === "upgraded") { restartRequired = true; notes.push("the Nxeon-managed BetterModel plugin was installed; it starts with the next server restart"); }
  }
  const wrote: string[] = [];
  // managed config: only when absent or still ours (an owner who edited it keeps their file)
  const cfgPath = `${base}/${CONFIG_PATH}`;
  if (files.length) {
    const cur = await deps.fs.readFile(cfgPath, 256 * 1024);
    const want = Buffer.from((deps.configTemplate ?? managedConfigTemplate)());
    if (!cur || (cur.toString("utf8").startsWith(CONFIG_MARKER) && !cur.equals(want))) {
      await deps.fs.mkdirp(path.posix.dirname(cfgPath));
      await deps.fs.writeFile(cfgPath, want);
      wrote.push(CONFIG_PATH); restartRequired = true;
    } else if (!cur.toString("utf8").startsWith(CONFIG_MARKER)) notes.push("BetterModel's config.yml was changed by the server owner, so Nxeon left it as it is");
  }
  await deps.fs.mkdirp(`${base}/${MODELS_DIR}`);
  for (const f of files) {
    const cur = await deps.fs.readFile(`${base}/${f.rel}`, 4 * 1024 * 1024);
    if (cur && cur.equals(f.data)) continue;
    const tmp = `${base}/${f.rel}.nx-part`;
    await deps.fs.writeFile(tmp, f.data);
    await deps.fs.rename(tmp, `${base}/${f.rel}`);
    wrote.push(f.rel); restartRequired = true;
  }
  // this project's models the new version no longer has (only files with OUR namespace prefix; others untouched)
  const keep = new Set(files.map((f) => path.posix.basename(f.rel)));
  const removed: string[] = [];
  for (const name of await deps.fs.list(`${base}/${MODELS_DIR}`).catch(() => [] as string[])) {
    if (!name.startsWith(`${a.namespace}_`) || !name.endsWith(".bbmodel") || keep.has(name)) continue;
    await deps.fs.remove(`${base}/${MODELS_DIR}/${name}`);
    removed.push(`${MODELS_DIR}/${name}`); restartRequired = true;
  }
  if (!files.length) {
    const rel = await releaseManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, dependent: dependentFor(a.projectId) });
    if (!rel.ok) return { ok: false, error: `BetterModel: ${rel.error}` };
    return { ok: true, action: removed.length ? "removed" : "no_creatures", wrote, removed, restartRequired, bettermodel: rel.action, notes };
  }
  if (restartRequired) notes.push("restart the server (or run /bettermodel reload) so BetterModel loads the creatures and rebuilds its resource pack");
  return { ok: true, action: "delivered", wrote, removed, restartRequired, bettermodel, notes };
}

