/** Cyrus's new ids (not in R) renumbered past both sides' counters. Deterministic (document order). */
function renumber(base: ModelDoc, ours: ModelDoc, theirs: ModelDoc): ModelDoc {
  const known = new Set<string>([...base.bones.map((b) => b.id), ...base.cubes.map((c) => c.id), ...base.clips.flatMap((c) => [...c.tracks.flatMap((t) => (t.keys ?? []).map((k) => k.id)), ...(c.events ?? []).map((e) => e.id)])]);
  let seq = Math.max(ours.seq, theirs.seq, base.seq);
  const map = new Map<string, string>();
  const re = (id: string, kind: "b" | "c" | "k" | "e") => { if (known.has(id)) return id; let m = map.get(id); if (!m) { const n = nextId(seq, kind); seq = n.seq; m = n.id; map.set(id, m); } return m; };
  const bones = theirs.bones.map((b) => ({ ...b, id: re(b.id, "b") }));
  const fix = (id: string | null) => (id === null ? null : map.get(id) ?? id);
  return {
    ...theirs,
    bones: bones.map((b) => ({ ...b, parent: fix(b.parent) })),
    cubes: theirs.cubes.map((c) => ({ ...c, id: re(c.id, "c"), bone: fix(c.bone)! })),
    clips: theirs.clips.map((cl) => ({ ...cl, ...(cl.events ? { events: cl.events.map((e) => ({ ...e, id: re(e.id, "e") })) } : {}), tracks: cl.tracks.map((t) => ({ ...t, bone: fix(t.bone)!, ...(t.keys ? { keys: t.keys.map((k) => ({ ...k, id: re(k.id, "k") })) } : {}) })) })),
    seq,
  };
}

/** Every change from `from` to `to`, field by field (also the "What changed" list of the approve view). */
export function diffDocs(from: ModelDoc, to: ModelDoc): Change[] {
  const a = nodesOf(from), b = nodesOf(to);
  const out: Change[] = [];
  for (const [k, n] of b) {
    const o = a.get(k);
    if (!o) { out.push({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "add", label: `${n.label} added` }); continue; }
    for (const f of new Set([...Object.keys(o.value), ...Object.keys(n.value)])) if (!eq(o.value[f], n.value[f])) out.push({ id: `${k}:${f}`, kind: n.kind, node: n.key, field: f, action: "modify", label: `${n.label}: ${fl(f)}` });
  }
  for (const [k, n] of a) if (!b.has(k)) out.push({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "delete", label: `${n.label} removed` });
  return out;
}

