// Cyrus Model Studio: ONE answer to "what is this creature right now?" for every surface that reads it: the layer-1
// paint studio, the layer-2 editor and the build sync (lib/cyrus/assets/sync.ts). Pure (asset rows in, decision out).
//
// The rows a creature key can have (all CyrusProjectAsset kind "model"):
//   generated  a build's RigSpec (mime RIG_SPEC_MIME, provenance.spec). provenance.studioKept = true means a later
//              sync recorded it but kept a studio edit on top (so it never "wins" over that edit).
//   editor     a layer-2 save (provenance.generator "cyrus-model-editor", provenance.doc = editor ModelDoc,
//              provenance.spec = the RigSpec it compiles to, provenance.rigBase = the generated RigSpec it descends from)
//   paint      a layer-1 save (provenance.generator "cyrus-model-studio", provenance.doc = paint ModelDoc: layers on
//              the skin sheet). Paint never changes geometry; it sits on whatever geometry is current.
// Both studio docs share one mime string (MODEL_DOC_MIME); they are told apart by provenance.generator and by their own
// strict validators, never by guessing.
//
// THE RULE (editor saves survive builds): the current geometry is the newest of {editor rows, generated rows NOT
// marked studioKept}. When a build returns a RigSpec while an editor edit is current, the sync 3-way merges
// (./editor/build-merge.ts: base = the edit's rigBase, ours = the edit, theirs = the build) with the existing editor
// merge (./editor/merge.ts mergeCandidate): disjoint changes merge, overlaps keep the human's value.
import { RIG_SPEC_MIME } from "../creature/portal";
import { checkModelDoc as checkEditorDoc, MODEL_DOC_MIME, type ModelDoc as EditorDoc } from "./editor/doc";
import { checkModelDoc as checkPaintDoc, type ModelDoc as PaintDoc } from "./doc";

export const EDITOR_GENERATOR = "cyrus-model-editor";
export const PAINT_GENERATOR = "cyrus-model-studio";

export type ModelRowLike = { id: string; kind: string; assetKey: string; mime: string | null; sha256: string; origin: string; provenance: unknown; createdAt: Date | string };
export type RigBase = { assetId: string | null; sha256: string; spec: unknown };
export type CurrentGeometry =
  | { source: "generated"; assetId: string; sha256: string; spec: unknown; row: ModelRowLike }
