// Model Studio L2: what happens to an editor save when the NEXT BUILD returns a RigSpec for the same creature.
// Pure. Called by the build sync (lib/cyrus/assets/sync.ts) through the current-creature rule
// (../creature-state.ts). The build service does not see editor saves (it re-emits the creature it generated), so a
// plain "newest wins" would silently throw the person's work away. The rule:
//   * no editor edit                      -> the build's spec ships ("build")
//   * the build returned the SAME RigSpec  -> the editor doc ships unchanged ("kept")
//     the edit descends from (sha256 equal)
//   * the build changed the creature       -> 3-way merge with the EXISTING editor merge (./merge.ts mergeCandidate):
//                                             base = the edit's rigBase, ours = the edit, theirs = the build, lined up
//                                             by fromRigSpec(..., { like }). Disjoint changes merge; on an overlap the
//                                             person's value is kept (human wins, the editor's own default). ("merged")
//   * no recorded base / base unreadable   -> the edit ships unchanged, the build's changes are reported as not
//                                             applied ("kept_no_base")
//   * the merge does not validate          -> the edit ships unchanged ("kept_merge_invalid")
// Whatever ships is re-checked and compiled by the caller exactly like a build's own creature.
import { checkRigSpec } from "../../creature/spec";
import { mergeCandidate, type Overlap, type Change } from "./merge";
import { fromRigSpec } from "./rigspec";
import { validateDoc } from "./validate";
import type { ModelDoc } from "./doc";
import type { RigBase } from "../creature-state";

export type BuildMergeDecision = "build" | "kept" | "merged" | "kept_no_base" | "kept_merge_invalid";
export type BuildMergeResult = { decision: BuildMergeDecision; doc: ModelDoc | null; applied: Change[]; overlaps: Overlap[]; notes: string[] };

export function mergeBuildIntoEdit(i: { name: string; build: { spec: unknown; sha256: string }; edit: { doc: ModelDoc; rigBase: RigBase | null } | null }): BuildMergeResult {
  const none = { applied: [] as Change[], overlaps: [] as Overlap[] };
  if (!i.edit) return { decision: "build", doc: null, ...none, notes: [] };
  const ours = i.edit.doc;
  if (i.edit.rigBase && i.edit.rigBase.sha256 === i.build.sha256) return { decision: "kept", doc: ours, ...none, notes: [] };
  const theirsChk = checkRigSpec(i.build.spec);
  if (!theirsChk.ok) return { decision: "kept_no_base", doc: ours, ...none, notes: [`The build's version of ${i.name} could not be read, so your Model Studio edit was kept as it is.`] };
  const baseChk = i.edit.rigBase ? checkRigSpec(i.edit.rigBase.spec) : null;
  if (!baseChk || !baseChk.ok) return { decision: "kept_no_base", doc: ours, ...none, notes: [`${i.name}: your Model Studio edit was kept; this build's own changes to the creature were not applied (the version you edited is not on record, so they could not be merged safely).`] };
  const base = fromRigSpec(baseChk.spec, { like: ours });
  const theirs = fromRigSpec(theirsChk.spec, { like: base });
  const m = mergeCandidate(base, ours, theirs);
  if (!validateDoc(m.doc).ok) return { decision: "kept_merge_invalid", doc: ours, applied: [], overlaps: m.overlaps, notes: [`${i.name}: this build's changes could not be combined with your Model Studio edit into a valid creature, so your edit was kept as it is.`] };
  const notes = [`${i.name}: your Model Studio edit was kept and merged with this build (${m.applied.length} change${m.applied.length === 1 ? "" : "s"} from the build${m.overlaps.length ? `, ${m.overlaps.length} overlap${m.overlaps.length === 1 ? "" : "s"} kept as you made ${m.overlaps.length === 1 ? "it" : "them"}` : ""}).`];
  return { decision: "merged", doc: m.doc, applied: m.applied, overlaps: m.overlaps, notes };
}

