// Cyrus creature paint -> the DELIVERED skin. Model Studio layer 1 saves creature paint as lossless layers on the
// skin sheet (lib/cyrus/modelstudio/doc.ts ModelDoc, kind "creature"); this turns the albedo layers into the skin
// texture embedded in the compiled .bbmodel, which the Nxeon-managed BetterModel plugin reads on the server and packs
// for players. Pure + deterministic: the build sync records the paint with the creature (MbAssets.creatures[].paint)
// and delivery re-compiles from it and proves the bytes equal (./deliver.ts compileStoredCreatures).
// Rules (documented, owner may change): only visible ALBEDO layers ship (a creature skin has no normal/roughness
// maps in BetterModel); the result is snapped to cutout (alpha >= 128 -> opaque, else clear) like Minecraft entity
// skins; the paint must be on a sheet of the same size as the compiled skin, otherwise it is not applied (the caller
// says so, never a silent misalignment).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { decodeLayers, type EncodedLayer, type ModelDoc } from "../modelstudio/doc";
import { compositeChannel } from "../modelstudio/layers";
import type { Raster } from "../textures/render";

export type CreaturePaint = { tex: { w: number; h: number }; layers: EncodedLayer[]; sha256: string };
/** keeps ModBuild.result small: a 128 px skin with heavy paint is well under this */
export const MAX_CREATURE_PAINT_CHARS = 512 * 1024;

/** The shippable part of a creature paint doc (visible albedo layers), or null when nothing would change the skin. */
export function creaturePaintOf(doc: Pick<ModelDoc, "kind" | "tex" | "layers">): CreaturePaint | null {
  if (doc.kind !== "creature") return null;
  const layers = doc.layers.filter((l) => l.channel === "albedo" && l.visible && l.opacity > 0);
  if (!layers.length) return null;
  const set = decodeLayers({ tex: doc.tex, layers });
  if (!set || !set.layers.some((l) => l.px.some((v, i) => i % 4 === 3 && v > 0))) return null;
  if (layers.reduce((n, l) => n + l.rle.length, 0) > MAX_CREATURE_PAINT_CHARS) return null;
  const tex = { w: doc.tex.w, h: doc.tex.h };
  return { tex, layers, sha256: sha256Hex(canonicalJson({ tex, layers })) };
}

export type PaintCheck = { ok: true } | { ok: false; reason: string };
/** Can this paint go on a skin of `size`? (stored paint is re-checked: it comes back from a JSON column) */
export function checkCreaturePaint(p: unknown, size: number): PaintCheck {
  const o = p as Partial<CreaturePaint> | null;
  if (!o || typeof o !== "object" || !o.tex || !Array.isArray(o.layers)) return { ok: false, reason: "the stored paint is malformed" };
  if (o.tex.w !== size || o.tex.h !== size) return { ok: false, reason: `the paint is on a ${o.tex.w} px sheet but the creature's skin is ${size} px` };
  if (!decodeLayers({ tex: o.tex, layers: o.layers })) return { ok: false, reason: "the stored paint layers do not decode" };
  if (o.sha256 !== sha256Hex(canonicalJson({ tex: o.tex, layers: o.layers }))) return { ok: false, reason: "the stored paint does not match its hash" };
  return { ok: true };
}

/** The compile hook: generated skin -> painted skin (same size), cutout-snapped. Call checkCreaturePaint first. */
export function paintSkin(paint: CreaturePaint): (base: Raster) => Raster {
  return (base) => {
    const set = decodeLayers({ tex: paint.tex, layers: paint.layers });
    if (!set || paint.tex.w !== base.size || paint.tex.h !== base.size) return base;
    const img = compositeChannel(set, "albedo", { w: base.size, h: base.size, px: new Uint8ClampedArray(base.px) });
    const px = new Uint8ClampedArray(img.px);
    for (let i = 3; i < px.length; i += 4) px[i] = px[i] >= 128 ? 255 : 0;
    return { size: base.size, px };
  };
}

