// Cyrus Model Studio: the REAL dependencies of /api/cyrus/models/v1 and the page. SERVER ONLY.
// No new Nxeon imports: everything comes through the studios' existing wiring (lib/cyrus/studios/deps.ts: the Cyrus
// access rule, the studios flag, the plan lookup, the store) and the host seam (lib/cyrus/host: settings, rate limit).
import { getHost } from "../host";
import { serviceDeps, studioPlanOf, studioViewer } from "../studios/deps";
import { prismaModelDraftStore } from "../studios/store-prisma";
import { StudioError } from "../studios/service";
import type { StudioViewer } from "../studios/http";
import { MODEL_STUDIO_FLAG, modelStudioOpen } from "./access";
import type { ModelApiDeps } from "./http";
import { memoryDraftStore, type DraftStore, type ModelServiceDeps } from "./service";
import { selectPreviewRenderer } from "./preview/select";

/** The Model Studio setting. Fails CLOSED: a settings error never opens it. */
export async function modelStudioFlagOn(): Promise<boolean> {
  try { return await getHost().settings.getBool(MODEL_STUDIO_FLAG, false); } catch { return false; }
}

/** Who may see Model Studio now: the studios viewer (studios gate) AND (preview account OR the model setting is on). */
export async function modelStudioViewer(): Promise<(StudioViewer & { user: unknown }) | null> {
  const v = await studioViewer().catch(() => null);
  if (!v) return null;
  const flag = await modelStudioFlagOn();
  return modelStudioOpen({ studiosOpen: true, previewUser: v.preview, modelFlagOn: flag }) ? v : null;
}

/** Drafts that never take a request down: a missing table (schema not pushed yet) answers 503, not 500. */
function safeDrafts(inner: DraftStore): DraftStore {
  const wrap = <A extends unknown[], R>(f: (...a: A) => Promise<R>) => async (...a: A): Promise<R> => {
    try { return await f(...a); } catch (e) { console.error("[cyrus-model-studio] drafts:", (e as Error).message); throw new StudioError(503, "drafts_unavailable", "Autosave is not available right now; your edits stay in this tab until you save a revision."); }
  };
  return { get: wrap(inner.get), put: wrap(inner.put), drop: wrap(inner.drop) };
}

const G = globalThis as { __cyrusMemDrafts?: DraftStore };
export function modelServiceDeps(env: Record<string, string | undefined> = process.env): ModelServiceDeps {
  // devhost / tests only: CYRUS_MODEL_DRAFTS=memory keeps drafts in the process (no table needed)
  const drafts = env.CYRUS_MODEL_DRAFTS === "memory" && env.NODE_ENV !== "production" ? (G.__cyrusMemDrafts ??= memoryDraftStore()) : safeDrafts(prismaModelDraftStore);
  return {
    ...serviceDeps(env), planOf: studioPlanOf(env), drafts,
    renderer: () => { const s = selectPreviewRenderer(env); return s.ok ? s.renderer : null; },
  };
}

export function modelApiDeps(env: Record<string, string | undefined> = process.env): ModelApiDeps {
  return {
    viewer: modelStudioViewer,
    service: modelServiceDeps(env),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:${key}`, { max, windowMs }),
  };
}

