a=s[s.index('/** The ModelDoc an asset row holds'):s.index('async function owned(')]
b='''/** The ModelDoc an asset row holds (a build's RigSpec row is converted; a broken row is skipped). */
export function docOfModelRow(row: AssetRow): ModelDoc | null {
  if (row.kind !== "model") return null;
  const p = obj(row.provenance);
  if (row.mime === MODEL_DOC_MIME) { const d = checkModelDoc(p.doc); return d.ok ? d.doc : null; }
  if (row.mime === RIG_SPEC_MIME) { const c = checkRigSpec(p.spec); return c.ok ? fromRigSpec(c.spec) : null; }
  return null;
}

/**
 * Pure: the current model per key, oldest key first. "Current" is the ONE rule both studios and the build sync use
 * (../creature-state.ts studioCreatureOf): the newest editor save, unless a build recorded after it was NOT merged
 * into it (a build the sync merged an edit into is marked studioKept and never wins over that edit).
 */
export function resolveModels(rows: readonly AssetRow[]): ModelEntry[] {
  const out: ModelEntry[] = [];
  for (const key of creatureKeys(rows)) {
    const g = studioCreatureOf(rows, key).geometry;
    if (!g) continue;
    let doc: ModelDoc | null = null;
    if (g.source === "editor") doc = g.doc;
    else { const c = checkRigSpec(g.spec); doc = c.ok ? fromRigSpec(c.spec) : null; }
    if (!doc) continue;
    const r = g.row as AssetRow;
    out.push({ key, assetId: r.id, origin: r.origin, revisionId: r.revisionId, createdAt: new Date(r.createdAt).toISOString(), source: g.source === "editor" ? "modeldoc" : "rigspec", doc });
  }
  return out;
}

