// Cyrus Model Studio integration seams (feature/cyrus-r30-modelstudio): the ONE current-creature rule, editor saves
// surviving the next build (3-way merge through the existing editor merge), the shared draft table surfaces, and
// creature paint compiled into the delivered skin.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { checkRigSpec } from "../lib/cyrus/creature/spec";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { RIG_SPEC_MIME } from "../lib/cyrus/creature/portal";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { EDITOR_GENERATOR, studioCreatureOf, type ModelRowLike } from "../lib/cyrus/modelstudio/creature-state";
import { mergeBuildIntoEdit } from "../lib/cyrus/modelstudio/editor/build-merge";
import { fromRigSpec, toRigSpec } from "../lib/cyrus/modelstudio/editor/rigspec";
import { applyOp } from "../lib/cyrus/modelstudio/editor/ops";
import { MODEL_DOC_MIME, type ModelDoc } from "../lib/cyrus/modelstudio/editor/doc";
import { resolveModels as resolveEditorModels } from "../lib/cyrus/modelstudio/editor/service";
import { prismaEditorDrafts } from "../lib/cyrus/modelstudio/editor/deps";

const ROOT = path.resolve(__dirname, "..");
const NS = "nx_r6cr34tr";
const raw = () => JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-creatures/banshee.json"), "utf8"));
const shaOf = (v: unknown) => sha256Hex(canonicalJson(v));
const expand = (v: unknown) => { const c = checkRigSpec(v); if (!c.ok) throw new Error(c.error); return c.spec; };
const ok = <T,>(r: { ok: true; doc: T } | { ok: false; error: string }): T => { if (!r.ok) throw new Error(r.error); return r.doc; };

/** an in-memory project: asset rows in insertion order (createdAt strictly increasing), content-addressed like the store */
function project() {
  const rows: (ModelRowLike & { revisionId: string; projectId: string; size: number; path: string | null })[] = [];
  let t = Date.parse("2026-10-11T00:00:00Z");
  const add = (a: { assetKey: string; kind: string; sha256: string; origin: string; mime: string | null; provenance: unknown; revisionId?: string }) => {
    const hit = rows.find((r) => r.kind === a.kind && r.assetKey === a.assetKey && r.sha256 === a.sha256);
    if (hit) return hit; // the real store is unique on (project, kind, key, sha256)
    const row = { id: `a${rows.length + 1}`, projectId: "p1", revisionId: a.revisionId ?? "r", size: 1, path: null, createdAt: new Date((t += 1000)), ...a };
    rows.push(row);
    return row;
  };
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: false, reason: "off" }) as never,
    projectForRootBuild: async () => ({ id: "p1", namespace: NS, userId: "u1" }),
    createProject: async () => { throw new Error("no"); },
    findRevisionForBuild: async () => null, headRevisionId: async () => null,
    addRevision: async () => ({ id: `rev${rows.length}` }),
    recordAsset: async (_p, a) => add(a),
    studioCreatureFor: async (_p, name) => studioCreatureOf(rows, name),
  };
  return { rows, add, deps };
}
const svc = (spec: unknown) => ({ namespace: NS, promptVersion: "p", kept: false, downgraded: [], warnings: [], creatures: [{ name: "banshee", spec }] });
const build = (id: string) => ({ id, userId: "u1", rootBuildId: "mb1", mcVersion: "26.2", pluginName: "BansheeHunt", jarName: "B.jar", jarSha256: "a".repeat(64) });

/** what the editor's save writes (lib/cyrus/modelstudio/editor/service.ts saveModelRevision) */
function editorSave(p: ReturnType<typeof project>, doc: ModelDoc, basedOn: ModelRowLike) {
  const spec = toRigSpec(doc).spec;
  return p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(doc), origin: "edited", mime: MODEL_DOC_MIME, provenance: { generator: EDITOR_GENERATOR, doc, spec, basedOn: basedOn.id, rigBase: { assetId: basedOn.id, sha256: basedOn.sha256, spec: (basedOn.provenance as { spec: unknown }).spec } } });
}
const bodyCube = (d: ModelDoc) => d.cubes.find((c) => c.bone === d.bones.find((b) => b.name === "body")!.id)!;

describe("Model Studio: the one current-creature rule", () => {
  it("newest editor save wins; a build the sync kept an edit on top of never replaces it; an unmerged newer build does", () => {
    const p = project();
    const r1 = p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(raw()), origin: "generated", mime: RIG_SPEC_MIME, provenance: { spec: raw() } });
    assert.equal(studioCreatureOf(p.rows, "banshee").geometry!.source, "generated");
    const d0 = fromRigSpec(expand(raw()));
    const e1 = editorSave(p, ok(applyOp(d0, { op: "move", ids: [bodyCube(d0).id], delta: [0, 1, 0] })), r1);
    const g = studioCreatureOf(p.rows, "banshee").geometry!;
    assert.equal(g.source, "editor"); assert.equal(g.assetId, e1.id);
    assert.equal(g.source === "editor" && g.rigBase?.sha256, r1.sha256, "the rigBase is the build row the edit started from");
    const r2spec = { ...raw(), displayName: "Banshee II" };
    p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(r2spec), origin: "generated", mime: RIG_SPEC_MIME, provenance: { spec: r2spec, studioKept: true } });
    assert.equal(studioCreatureOf(p.rows, "banshee").geometry!.assetId, e1.id, "studioKept build rows never win over the edit");
    const r3spec = { ...raw(), displayName: "Banshee III" };
    const r3 = p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(r3spec), origin: "generated", mime: RIG_SPEC_MIME, provenance: { spec: r3spec } });
    assert.equal(studioCreatureOf(p.rows, "banshee").geometry!.assetId, r3.id, "a newer build that was not merged is current (old behaviour, e.g. before this branch)");
    // the editor's own list follows the same rule
    assert.equal(resolveEditorModels(p.rows as never)[0].assetId, r3.id);
  });
});

describe("Model Studio: editor saves are not overwritten by the next build", () => {
  const base = fromRigSpec(expand(raw()));
  const r1 = { spec: raw(), sha256: shaOf(raw()) };
  const human = ok(applyOp(base, { op: "move", ids: [bodyCube(base).id], delta: [0, 2, 0] }));
  it("build returns the same RigSpec -> the edit ships unchanged", () => {
    const m = mergeBuildIntoEdit({ name: "banshee", build: r1, edit: { doc: human, rigBase: { assetId: "a1", ...r1 } } });
    assert.equal(m.decision, "kept"); assert.equal(m.doc, human);
  });
  it("build changed something else -> 3-way merge keeps both; an overlap keeps the human's value", () => {
    const r2 = { ...raw(), skin: { palette: { ...raw().skin.palette, eye: "#ff4040" } } };
    const m = mergeBuildIntoEdit({ name: "banshee", build: { spec: r2, sha256: shaOf(r2) }, edit: { doc: human, rigBase: { assetId: "a1", ...r1 } } });
    assert.equal(m.decision, "merged");
    assert.equal(m.doc!.palette.eye, "#ff4040", "the build's colour change landed");
    assert.deepEqual(bodyCube(m.doc!).from, bodyCube(human).from, "the human's move survived");
    const both = ok(applyOp(human, { op: "setPalette", key: "eye", color: "#22ff22" }));
    const o = mergeBuildIntoEdit({ name: "banshee", build: { spec: r2, sha256: shaOf(r2) }, edit: { doc: both, rigBase: { assetId: "a1", ...r1 } } });
    assert.equal(o.overlaps.length, 1); assert.equal(o.doc!.palette.eye, "#22ff22", "human wins the overlap");
  });
  it("no recorded base -> the edit is kept and the build's changes are reported, not silently applied", () => {
    const m = mergeBuildIntoEdit({ name: "banshee", build: r1, edit: { doc: human, rigBase: null } });
    assert.equal(m.decision, "kept_no_base"); assert.equal(m.doc, human); assert.ok(m.notes[0].includes("not applied"));
  });
  it("sync: the edit is what ships (delivery list + manifest), the build row is studioKept, and a second build merges", async () => {
    const p = project();
    const s1 = await syncBuildAssets(build("mb1"), svc(raw()) as never, p.deps);
    const r1row = p.rows[0];
    assert.equal(s1!.creatures![0].specSha256, r1row.sha256);
    const e1 = editorSave(p, human, r1row);
    // build 2 re-emits the same creature (the usual case: the build changed something else in the mod)
    const s2 = await syncBuildAssets(build("mb2"), svc(raw()) as never, p.deps);
    const shipped = s2!.creatures![0];
    assert.equal(shipped.specSha256, shaOf(toRigSpec(human).spec), "the delivered creature is the human's edit");
    assert.equal(studioCreatureOf(p.rows, "banshee").geometry!.assetId, e1.id, "same doc: the edit row stays current");
    // build 3 changes the eye colour: merged, shipped, and the editor opens the merged doc
    const r3 = { ...raw(), skin: { palette: { ...raw().skin.palette, eye: "#ff4040" } } };
    const s3 = await syncBuildAssets(build("mb3"), svc(r3) as never, p.deps);
    const g = studioCreatureOf(p.rows, "banshee").geometry!;
    assert.equal(g.source, "editor");
    assert.equal(g.source === "editor" && g.doc.palette.eye, "#ff4040");
    assert.deepEqual(g.source === "editor" && bodyCube(g.doc).from, bodyCube(human).from);
    assert.equal(s3!.creatures![0].specSha256, g.sha256 === g.sha256 ? shaOf(toRigSpec((g as { doc: ModelDoc }).doc).spec) : "", "delivered = merged");
    assert.ok(s3!.notices.some((n) => n.includes("merged with this build")));
    const r3row = p.rows.find((r) => r.sha256 === shaOf(r3))!;
    assert.equal((r3row.provenance as { studioKept?: boolean }).studioKept, true);
    // build 4 returns r3 again -> kept (the merged doc's base is r3 now)
    const before = p.rows.length;
    await syncBuildAssets(build("mb4"), svc(r3) as never, p.deps);
    assert.equal(p.rows.length, before, "nothing new: same build spec, same edit");
  });
  it("without the studio dependency the build ships its own spec (old behaviour, byte-identical)", async () => {
    const p = project();
    const a = await syncBuildAssets(build("mb1"), svc(raw()) as never, { ...p.deps, studioCreatureFor: undefined });
    assert.equal(a!.creatures![0].specSha256, shaOf(raw()));
  });
});

describe("Model Studio: one draft table, two surfaces", () => {
  it("the editor's drafts go to surface 'editor' and a database error is a 503, never a 500", async () => {
    const seen: unknown[] = [];
    const inner = {
      get: async () => null,
      put: async (r: unknown) => { seen.push(r); return { updatedAt: new Date() }; },
      drop: async () => { throw new Error("relation \"CyrusModelDraft\" does not exist"); },
    };
    const d = prismaEditorDrafts(inner as never);
    const doc = fromRigSpec(expand(raw()));
    await d.put({ ownerRef: "u1", projectId: "p1", key: "banshee", baseAssetId: null, baseHeadId: null, doc, updatedAt: "" });
    assert.equal((seen[0] as { assetKey: string }).assetKey, "banshee");
    await assert.rejects(d.remove("u1", "p1", "banshee"), (e: { status?: number; code?: string }) => e.status === 503 && e.code === "drafts_unavailable");
    const schema = fs.readFileSync(path.join(ROOT, "prisma/schema.prisma"), "utf8");
    assert.match(schema, /@@unique\(\[projectId, ownerRef, assetKey, surface\]\)/);
    assert.ok(fs.existsSync(path.join(ROOT, "prisma/manual-migrations/2026-10-11-cyrus-model-drafts.sql")));
  });
});

