  let t = Date.parse("2026-10-11T00:00:00Z");
  const add = (a: { assetKey: string; kind: string; sha256: string; origin: string; mime: string | null; provenance: unknown; revisionId?: string }) => {
    const hit = rows.find((r) => r.kind === a.kind && r.assetKey === a.assetKey && r.sha256 === a.sha256);
    if (hit) return hit; // the real store is unique on (project, kind, key, sha256)
    const row = { id: `a${rows.length + 1}`, projectId: "p1", revisionId: a.revisionId ?? "r", size: 1, path: null, createdAt: new Date((t += 1000)), ...a };
    rows.push(row);
    return row;
  };
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: false, reason: "off" }) as never,
    projectForRootBuild: async () => ({ id: "p1", namespace: NS, userId: "u1" }),
    createProject: async () => { throw new Error("no"); },
    findRevisionForBuild: async () => null, headRevisionId: async () => null,
    addRevision: async () => ({ id: `rev${rows.length}` }),
    recordAsset: async (_p, a) => add(a),
    studioCreatureFor: async (_p, name) => studioCreatureOf(rows, name),
  };
  return { rows, add, deps };
}
const svc = (spec: unknown) => ({ namespace: NS, promptVersion: "p", kept: false, downgraded: [], warnings: [], creatures: [{ name: "banshee", spec }] });
const build = (id: string) => ({ id, userId: "u1", rootBuildId: "mb1", mcVersion: "26.2", pluginName: "BansheeHunt", jarName: "B.jar", jarSha256: "a".repeat(64) });

/** what the editor's save writes (lib/cyrus/modelstudio/editor/service.ts saveModelRevision) */
function editorSave(p: ReturnType<typeof project>, doc: ModelDoc, basedOn: ModelRowLike) {
  const spec = toRigSpec(doc).spec;
  return p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(doc), origin: "edited", mime: MODEL_DOC_MIME, provenance: { generator: EDITOR_GENERATOR, doc, spec, basedOn: basedOn.id, rigBase: { assetId: basedOn.id, sha256: basedOn.sha256, spec: (basedOn.provenance as { spec: unknown }).spec } } });
}
const bodyCube = (d: ModelDoc) => d.cubes.find((c) => c.bone === d.bones.find((b) => b.name === "body")!.id)!;

