export const HANDGUN_GRIP_FIX_FLAG = "CYRUS_HANDGUN_GRIP_FIX";
export const handgunGripFixOn = (env: Record<string, string | undefined>) => env[HANDGUN_GRIP_FIX_FLAG] === "1";
