export function gripOnFist(t: DisplayTransform, g: [number, number], fist: Vec3): DisplayTransform {
  const r = rotate(t.rotation, [(g[0] - 8) * t.scale[0], (g[1] - 8) * t.scale[1], 0]);
  return { rotation: [...t.rotation], translation: [clampT(fist[0] - r[0]), clampT(fist[1] - r[1]), clampT(fist[2] - r[2])], scale: [...t.scale] };
}

