// Cyrus handgun grip: the PROPOSED display-transform fix (lib/cyrus/textures/display.ts gripOnFist), OFF by default.
// Golden: with the flag off every pack and every display block is exactly what shipped before; with it on the
// handgun's grip lands on the vanilla fist (grip_in_hand distance 0) in both hands and both views. Owner decision.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { render } from "../lib/cyrus/textures/render";
import { applyDisplay, displayFor, gripPoint, handgunGripFixOn, HANDGUN_GRIP_FIX_FLAG, vanillaFist, type DisplayView } from "../lib/cyrus/textures/display";
import { stateDisplays } from "../lib/cyrus/itemmodel/emit";
import { gunTemplate, swordTemplate } from "../lib/cyrus/itemmodel/templates";
import { gripChecks, gripReference } from "../lib/cyrus/modelstudio/minecraft/contexts";
import { buildPack } from "../lib/cyrus/textures/pack";
import { GLOCK } from "../lib/cyrus/textures/sample-glock";

const sha = (v: unknown) => createHash("sha256").update(JSON.stringify(v)).digest("hex");
const VIEWS: DisplayView[] = ["thirdperson_righthand", "thirdperson_lefthand", "firstperson_righthand", "firstperson_lefthand"];
const dist = (a: number[], b: number[]) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

describe("handgun grip fix (PROPOSED, flag off by default)", () => {
  const glock = render(GLOCK), g = gripPoint(glock, "handgun");
  it("flag off: the display block and the pack are byte-identical to today's (golden)", () => {
    assert.deepEqual(displayFor("glock_9mm", glock), displayFor("glock_9mm", glock, { gripFix: false }));
    // today's shipped numbers, pinned: a change here changes shipped packs and needs the owner
    assert.equal(sha(displayFor("glock_9mm", glock)), GOLDEN.glockDisplay);
    const off = buildPack({ namespace: "nx_gripgold1", description: "t", mcVersion: "1.21.11", textures: [GLOCK] });
    const def = buildPack({ namespace: "nx_gripgold1", description: "t", mcVersion: "1.21.11", textures: [GLOCK], handgunGripFix: false });
    assert.ok(off.ok && def.ok); assert.equal(off.ok && off.pack.sha1, def.ok && def.pack.sha1);
    assert.equal(off.ok && off.pack.sha1, GOLDEN.glockPackSha1);
    assert.equal(handgunGripFixOn({}), false); assert.equal(handgunGripFixOn({ [HANDGUN_GRIP_FIX_FLAG]: "1" }), true);
  });
  it("today: the grip sits off the vanilla fist (the reason for the proposal)", () => {
    const d = displayFor("glock_9mm", glock);
    const off = VIEWS.map((v) => dist(applyDisplay(d[v], [g[0], g[1], 8]), vanillaFist(v)));
    assert.ok(off.every((x) => x > 1), `distances today (1/16 block): ${off.map((x) => x.toFixed(2)).join(", ")}`);
  });
  it("flag on: the grip lands on the fist in every hand view; rotation and scale are unchanged", () => {
    const a = displayFor("glock_9mm", glock), b = displayFor("glock_9mm", glock, { gripFix: true });
    for (const v of VIEWS) {
      assert.ok(dist(applyDisplay(b[v], [g[0], g[1], 8]), vanillaFist(v)) < 0.005, v);
      assert.deepEqual(b[v].rotation, a[v].rotation); assert.deepEqual(b[v].scale, a[v].scale);
    }
    assert.equal(sha(b), GOLDEN.glockDisplayFixed, "the proposed numbers, pinned for review");
  });
  it("flag on: the gun template's idle passes grip_in_hand; explicit state overrides (aim) are not touched", () => {
    const tpl = gunTemplate(), idle = render(tpl.textures[0]);
    const ref = gripReference("gun", idle);
    const before = gripChecks(stateDisplays(tpl.spec, idle), ref), after = gripChecks(stateDisplays(tpl.spec, idle, { gripFix: true }), ref);
    for (const c of after.filter((x) => x.state === "idle")) { assert.ok(c.distance < 0.01, `${c.view} ${c.distance}`); assert.equal(c.status, "pass"); }
    const tp0 = before.find((c) => c.state === "idle" && c.view === "thirdperson")!, fp0 = before.find((c) => c.state === "idle" && c.view === "firstperson")!;
    assert.equal(tp0.distance, 1.948); assert.equal(fp0.distance, 3.148);
    // states with their own translation keep it: the fix only replaces the computed default
    for (const s of (tpl.spec.states ?? []).filter((x) => x.display && Object.values(x.display).some((t) => t?.translation))) {
      const b0 = before.filter((c) => c.state === s.id), a0 = after.filter((c) => c.state === s.id);
      for (const v of ["firstperson", "thirdperson"] as const) {
        const ov = s.display?.[v === "firstperson" ? "firstperson_righthand" : "thirdperson_righthand"];
        if (ov?.translation) assert.equal(a0.find((c) => c.view === v)!.distance, b0.find((c) => c.view === v)!.distance, `${s.id} ${v}: explicit override kept`);
      }
    }
  });
  it("tools are never touched (vanilla handheld with or without the flag)", () => {
    const sw = swordTemplate(), r = render(sw.textures[0]);
    assert.deepEqual(displayFor(sw.spec.name, r, { gripFix: true }), displayFor(sw.spec.name, r));
    assert.deepEqual(stateDisplays(sw.spec, r, { gripFix: true }), stateDisplays(sw.spec, r));
  });
});

// Pinned values (computed on this branch; regenerate only with the owner's sign-off on shipped-pack changes).
const GOLDEN = {
  glockDisplay: "PENDING",
  glockPackSha1: "PENDING",
  glockDisplayFixed: "PENDING",
};

