import { encodeLayers, MODELDOC_MIME } from "../lib/cyrus/modelstudio/doc";
import { newLayer } from "../lib/cyrus/modelstudio/layers";
import { PAINT_GENERATOR } from "../lib/cyrus/modelstudio/creature-state";

function paintDoc(size: number, base: { assetId: string; sha256: string; spec: unknown }, paintAt: [number, number][], color = [255, 0, 170, 255]) {
  const l = newLayer("paint", "Paint", "albedo", size, size);
  for (const [x, y] of paintAt) l.px.set(color, (y * size + x) * 4);
  return { v: 1 as const, kind: "creature" as const, name: "banshee", base: { type: "rigspec" as const, ...base }, tex: { w: size, h: size }, layers: encodeLayers({ w: size, h: size, layers: [l] }), symmetry: "none" as const };
}

describe("Model Studio: creature paint is compiled into the delivered skin", () => {
  const plain = checkReturnedCreature({ name: "banshee", spec: raw() }, NS);
  if (!plain.ok) throw new Error(plain.reason);
  const size = plain.compiled.layout.size;
  // a texel inside the first cube's north face (a real, shipped part of the skin)
  const f = plain.compiled.layout.cubes[0].faces.north;
  const at: [number, number] = [f.x, f.y];
  it("paintSkin composites the albedo layers over the generated skin, cutout-snapped, same size", () => {
    const p = creaturePaintOf(paintDoc(size, { assetId: "a1", sha256: shaOf(raw()), spec: raw() }, [at], [255, 0, 170, 90]))!;
    assert.ok(p); assert.equal(checkCreaturePaint(p, size).ok, true); assert.equal(checkCreaturePaint(p, size * 2).ok, false);
    const out = paintSkin(p)(plain.compiled.raster);
    const o = (at[1] * size + at[0]) * 4;
    assert.equal(out.px[o + 3], 255, "a half-transparent stroke on an opaque skin stays opaque");
    assert.notDeepEqual([...out.px.subarray(o, o + 3)], [...plain.compiled.raster.px.subarray(o, o + 3)], "the colour changed");
    assert.equal(creaturePaintOf({ kind: "creature", tex: { w: size, h: size }, layers: [] }), null, "no layers = nothing to ship");
  });
  it("sync ships the painted skin; delivery re-compiles it from the stored paint to the same bytes", async () => {
    const p = project();
    await syncBuildAssets(build("mb1"), svc(raw()) as never, p.deps);
    const r1 = p.rows[0];
    const doc = paintDoc(size, { assetId: r1.id, sha256: r1.sha256, spec: raw() }, [at, [at[0] + 1, at[1]]]);
    p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(doc), origin: "edited", mime: MODELDOC_MIME, provenance: { generator: PAINT_GENERATOR, layer: 1, doc } });
    const a = (await syncBuildAssets(build("mb2"), svc(raw()) as never, p.deps))!;
    const c = a.creatures![0];
    assert.ok(c.paint, "the paint rides along for delivery");
    assert.notEqual(c.pngSha256, plain.compiled.pngSha256, "the delivered skin is the painted one");
    assert.equal(c.specSha256, plain.specSha256, "geometry unchanged");
    const re = compileStoredCreatures(NS, [{ name: c.name, key: c.key, spec: c.spec, bbmodelSha256: c.bbmodelSha256, paint: c.paint }]);
    assert.ok(re.ok, re.ok ? "" : re.error);
    const bb = JSON.parse(re.ok ? re.files[0].data.toString("utf8") : "{}");
    const png = Buffer.from(String(bb.textures[0].source).split(",")[1], "base64");
    assert.equal(sha256Hex(png), c.pngSha256, "the .bbmodel BetterModel reads embeds the painted PNG");
    // tampered paint is refused, never silently delivered unpainted
    const bad = compileStoredCreatures(NS, [{ name: c.name, key: c.key, spec: c.spec, bbmodelSha256: c.bbmodelSha256, paint: { ...c.paint!, sha256: "0".repeat(64) } }]);
    assert.equal(bad.ok, false);
    // without paint: exactly the old bytes
    const pl = compileStoredCreatures(NS, [{ name: c.name, key: c.key, spec: c.spec, bbmodelSha256: plain.compiled.bbmodelSha256 }]);
    assert.ok(pl.ok);
  });
  it("a paint on a sheet of another size is not applied, and says so", async () => {
    const p = project();
    await syncBuildAssets(build("mb1"), svc(raw()) as never, p.deps);
    const r1 = p.rows[0];
    const other = size === 64 ? 128 : 64;
    const doc = paintDoc(other, { assetId: r1.id, sha256: r1.sha256, spec: raw() }, [[1, 1]]);
    p.add({ assetKey: "banshee", kind: "model", sha256: shaOf(doc), origin: "edited", mime: MODELDOC_MIME, provenance: { generator: PAINT_GENERATOR, layer: 1, doc } });
    const a = (await syncBuildAssets(build("mb2"), svc(raw()) as never, p.deps))!;
    assert.equal(a.creatures![0].paint, undefined);
    assert.equal(a.creatures![0].pngSha256, plain.compiled.pngSha256);
    assert.ok(a.notices.some((n) => n.includes("Repaint it")));
  });
});
