// Cyrus meshgen (wiring phase 2): an ACCEPTED mesh -> the project's asset flow, exactly once. A new "asset" revision
// whose manifest adds assets/models/<assetId>.glb (the head's other files kept), and one CyrusProjectAsset row
// (kind model, origin generated, path = the object-store key, provenance = the meshgen record summary + legal class).
// Idempotent by (project, model, assetId, sha256): a second read of the same finished job returns the same asset.
// Rejected / not-run meshes never reach this (fail closed: the worker stores no glb for them). Deps injected; the
// default uses the engine-core store (Cyrus' own tables only).
import { createHash } from "node:crypto";
import type { MeshgenRecord } from "./output";
import type { ManifestEntry } from "../engine-core/revisions";
import type { IngestResult, MeshProject } from "./api";

export type IngestDeps = {
  findAsset(projectId: string, assetKey: string, sha256: string): Promise<{ id: string; revisionId: string } | null>;
  head(projectId: string): Promise<{ id: string; manifest: ManifestEntry[] } | null>;
  addRevision(projectId: string, input: { kind: "asset"; manifest: ManifestEntry[]; status: "passed"; expectedHeadId: string | null; engine: Record<string, unknown>; message: string }): Promise<{ id: string }>;
  recordAsset(projectId: string, a: { revisionId: string; assetKey: string; kind: "model"; sha256: string; size: number; origin: "generated"; mime: string; path: string; provenance: Record<string, unknown> }): Promise<{ id: string }>;
};

export const meshPath = (assetId: string) => `assets/models/${assetId}.glb`;

export async function ingestMeshRecord(deps: IngestDeps, a: { project: MeshProject; record: MeshgenRecord; glb: Uint8Array }): Promise<IngestResult> {
  const r = a.record;
  if (r.verdict !== "accepted" || !r.outputs.glb) throw new Error("only an accepted mesh can be added to the project");
  if (r.projectId !== a.project.id) throw new Error("the mesh belongs to another project");
  const sha256 = createHash("sha256").update(a.glb).digest("hex");
  if (r.outputs.glb !== `sha256/${sha256}`) throw new Error("the mesh file does not match its record");
  const had = await deps.findAsset(a.project.id, r.assetId, sha256);
  if (had) return { assetId: had.id, revisionId: had.revisionId, already: true };
  for (let attempt = 0; attempt < 4; attempt++) {
    const head = await deps.head(a.project.id);
    const path = meshPath(r.assetId);
    const manifest: ManifestEntry[] = [...(head?.manifest ?? []).filter((e) => e.path !== path), { path, sha256, role: "asset" }];
    let rev: { id: string };
    try {
      rev = await deps.addRevision(a.project.id, { kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: `cyrus-meshgen ${r.rung}${r.module ? ` ${r.module}@${r.moduleVersion ?? "?"}` : ""}; ${r.engine.runner}` }, message: `AI mesh ${r.assetId} (${r.rung})`.slice(0, 200) });
    } catch (e) {
      if ((e as { code?: string }).code === "stale_head") continue;
      throw e;
    }
    const row = await deps.recordAsset(a.project.id, {
      revisionId: rev.id, assetKey: r.assetId, kind: "model", sha256, size: a.glb.length, origin: "generated", mime: "model/gltf-binary", path: r.outputs.glb,
      provenance: { generator: r.provenance.generator, legalClass: r.provenance.legalClass, jobId: r.jobId, rung: r.rung, module: r.module, moduleVersion: r.moduleVersion, stats: r.stats, decimated: r.decimated, tokens: r.tokens, manifestKey: r.outputs.manifest, at: r.at, delivered: false },
    });
    return { assetId: row.id, revisionId: rev.id, already: false };
  }
  throw new Error("the project kept changing; try again");
}

/** Default deps over the engine-core store (lazy import: this module stays light for tests). */
export async function engineIngestDeps(): Promise<IngestDeps> {
  const S = await import("../engine-core/store");
  const { cyrusDb } = await import("../db");
  return {
    findAsset: async (projectId, assetKey, sha256) => cyrusDb.cyrusProjectAsset.findUnique({ where: { projectId_kind_assetKey_sha256: { projectId, kind: "model", assetKey, sha256 } }, select: { id: true, revisionId: true } }),
    head: async (projectId) => { const h = await S.getHead(projectId); return h ? { id: h.id, manifest: S.manifestOf(h) } : null; },
    addRevision: (projectId, input) => S.addRevision(projectId, { ...input, engine: input.engine as never }),
    recordAsset: (projectId, a) => S.recordAsset(projectId, a),
  };
}
