// Cyrus meshgen OUTPUT: the canonical asset manifest (assets3d/manifest.ts, glTF + sidecar) for an accepted mesh,
// and the meshgen RECORD kept for every job (accepted or not): rung, tokens, compute, checks, object-store keys and
// the exact harness/engine that built it. The catalog (feature/cyrus-r14-catalog) can register an accepted asset
// later from manifest + glb; meshgen does not write to any library. Pure.
import { validateAssetManifest, type AssetManifest, type ManifestIssue } from "../assets3d/manifest";
import type { HarnessStats } from "./checks";
import type { MeshIssue } from "./checks";
import type { MeshgenRequest, Rung, TokenUsage } from "./spec";
import { getTemplate, KIT } from "./templates";

export const RECORD_KIND = "cyrus-meshgen-record" as const;
export const GENERATOR = "ai-mesh" as const;

export type MeshgenVerdict = "accepted" | "rejected" | "not_run";

export type MeshgenRecord = {
  schema: 1;
  kind: typeof RECORD_KIND;
  jobId: string;
  requestKey: string;
  assetId: string;
  projectId: string;
  game: string;
  category: string;
  rung: Rung;
  /** template id, "hardsurface" for the kit, null for scratch. */
  module: string | null;
  moduleVersion: number | null;
  verdict: MeshgenVerdict;
  /** Why it did not run (busy build host, transport, timeout, flag off). Only for verdict not_run. */
  notRunReason?: string;
  issues: MeshIssue[];
  stats: HarnessStats | null;
  decimated: { from: number; to: number; ratio: number } | null;
  /** Object-store keys. glb + manifest only when accepted (fail closed). */
  outputs: { glb: string | null; manifest: string | null; sheet: string | null; renders: string[] };
  tokens: { estimate: { totalTokens: number; dollars: number | null } | null; usage: TokenUsage | null };
  compute: { wallMs: number; lockWaitMs: number; blenderSeconds: number | null; exitCode: number | null; worker: string };
  engine: { blender: string | null; harness: number | null; filesSha256: string; runner: string };
  provenance: { generator: typeof GENERATOR; legalClass: "ai-generated-for-user"; source: "ai" };
  at: string;
};

export function moduleOf(req: MeshgenRequest): { module: string | null; version: number | null } {
  if (req.rung === "template") { const t = getTemplate(req.template); return { module: req.template, version: t?.version ?? null }; }
  if (req.rung === "kit") return { module: KIT.id, version: KIT.version };
  return { module: null, version: null };
}

/** Manifest for an accepted mesh: kind model, metres, +Y up (glTF), legal class ai-generated-for-user, source ai. */
export function buildManifest(req: MeshgenRequest, glbSha256: string): { ok: true; manifest: AssetManifest } | { ok: false; errors: ManifestIssue[] } {
  const mod = moduleOf(req);
  const note = `${GENERATOR} rung=${req.rung}${mod.module ? ` module=${mod.module}@v${mod.version}` : ""}`;
  return validateAssetManifest({
    schemaVersion: 1, assetId: req.assetId, kind: "model", game: req.game, units: "m", upAxis: "+Y",
    geometry: { path: `models/${req.assetId}.glb`, sha256: glbSha256, uvSets: 1 },
    channels: [], legalClass: "ai-generated-for-user", retention: "project",
    provenance: { source: "ai", note, derivedFrom: [] },
  });
}
