// Cyrus Model Studio: THE operation log (undo / redo with deterministic replay) every model surface uses: the layer-2
// cuboid editor (./editor/history.ts instantiates it for ModelDoc + editor ops) and the layer-3 retexture/light-edit
// studio (./retex/ops.ts for MeshEditDoc + mesh ops). Pure + client-safe.
// The log is { base, entries, at }: the document at step i is replay(base, entries[0..i)). A per-step document cache
// makes undo/redo O(1); replay() rebuilds any step from the base alone (tests prove both agree byte for byte).
// One gizmo drag, one field commit, one slider release, one accepted candidate = ONE entry (the UI previews drags
// outside the log and commits a single op on release). At most `max` entries: older ones fold into the base.
export const MAX_STEPS = 200;

export type Applied<D> = { ok: true; doc: D; label: string; select?: string[] } | { ok: false; error: string };
export type Apply<D, O> = (doc: D, op: O) => Applied<D>;
export type LogEntry<O> = { op: O; label: string };
export type Log<D, O> = { base: D; entries: LogEntry<O>[]; at: number; docs: D[] };

export function opLog<D, O>(apply: Apply<D, O>) {
  const init = (base: D): Log<D, O> => ({ base, entries: [], at: 0, docs: [base] });
  const current = (l: Log<D, O>): D => l.docs[l.at];
  const canUndo = (l: Log<D, O>) => l.at > 0;
  const canRedo = (l: Log<D, O>) => l.at < l.entries.length;
  /** Apply + record one op (drops any redo branch). A refused op leaves the log unchanged and says why. */
  function push(l: Log<D, O>, op: O, max = MAX_STEPS): { ok: true; log: Log<D, O>; select?: string[] } | { ok: false; error: string; log: Log<D, O> } {
    const r = apply(current(l), op);
    if (!r.ok) return { ok: false, error: r.error, log: l };
    let entries = [...l.entries.slice(0, l.at), { op, label: r.label }];
    let docs = [...l.docs.slice(0, l.at + 1), r.doc];
    let base = l.base;
    while (entries.length > max) { base = docs[1]; entries = entries.slice(1); docs = docs.slice(1); }
    return { ok: true, log: { base, entries, at: entries.length, docs }, select: r.select };
  }
  const undo = (l: Log<D, O>): Log<D, O> => (canUndo(l) ? { ...l, at: l.at - 1 } : l);
  const redo = (l: Log<D, O>): Log<D, O> => (canRedo(l) ? { ...l, at: l.at + 1 } : l);
  const jump = (l: Log<D, O>, at: number): Log<D, O> => ({ ...l, at: Math.max(0, Math.min(l.entries.length, at)) });
  /** Unsaved = steps since the base it was opened (or last saved) as. */
  const unsaved = (l: Log<D, O>) => l.at;
  /** Rebuild the document at step `upTo` from the base and the recorded ops only (deterministic). */
  function replay(base: D, entries: readonly LogEntry<O>[], upTo = entries.length): D {
    let doc = base;
    for (let i = 0; i < upTo; i++) {
      const r = apply(doc, entries[i].op);
      if (!r.ok) throw new Error(`replay diverged at step ${i + 1} (${entries[i].label}): ${r.error}`);
      doc = r.doc;
    }
    return doc;
  }
  return { init, current, canUndo, canRedo, push, undo, redo, jump, unsaved, replay, rebase: init };
}

