// Cyrus Model Studio LAYER 3: the MeshEditDoc v1, the one saveable unit of a retexture + light-edit session on an
// imported or AI-generated glTF mesh (MODEL-STUDIO-PLAN section 2, L3 row). Pure + client-safe, strict validation.
//   base       the glTF the session edits, by sha256 (the mesh bytes are NEVER copied into the doc), plus where it came
//              from (an AI mesh from meshgen, or an imported file) and, for template meshes, the meshgen template +
//              the exact spec that built it (the parameter sliders edit a copy of that spec)
//   legal      the asset's legal class from its manifest (lib/cyrus/assets3d/manifest.ts): retention + "game-derived,
//              not redistributed" are enforced from here, never from the UI
//   parts      per NAMED part (glTF mesh name): translate (metres), rotate (degrees, XYZ), scale, about the part's own
//              centre. Light edit only: no vertex edits, no sculpting (plan section 7: transform, material, UV tweaks)
//   materials  per material slot: base colour, metallic, roughness, emissive values (glTF metallic-roughness)
//   layers     per-CHANNEL lossless paint layers (albedo, normal, roughness, metallic, emissive, mask; the layer-1
//              "rle1" encoding). Channels stay separate here; packing into a game's textures happens ONLY at export,
//              from the adapter asset profile (./export.ts)
import { z } from "zod";
import { LEGAL_CLASSES } from "../../assets3d/manifest";
import { BLEND_MODES, decodePixels, LAYER_ID, MAX_LAYERS, PAINT_CHANNELS, type LayerSet } from "../layers";
import type { EncodedLayer } from "../doc";

export const MESH_EDIT_MIME = "application/vnd.cyrus.mesh-edit+json";
export const MESH_EDIT_VERSION = 1 as const;
export const MESH_TEX_SIZES = [256, 512, 1024, 2048] as const;
export const MAX_PARTS = 256;
export const MAX_SLOTS = 64;
/** a part may move at most this far from where the mesh put it (metres) and scale within these bounds: light edit */
export const PART_LIMITS = { translate: 10, scaleMin: 0.05, scaleMax: 20 } as const;
export const SNAP = { move: [0, 0.005, 0.01, 0.05, 0.1] as const, rotate: [0, 1, 5, 15, 45, 90] as const, scale: [0, 0.01, 0.05, 0.1, 0.25] as const };

const V3 = z.tuple([z.number().finite(), z.number().finite(), z.number().finite()]);
const unit = z.number().finite().min(0).max(1);
const SHA = z.string().regex(/^[0-9a-f]{64}$/);
const NAME = z.string().regex(/^[a-z][a-z0-9_]{1,47}$/);
const PART = z.string().min(1).max(48).regex(/^[^\u0000-\u001f]+$/);

export const PartXformZ = z.strictObject({
  t: V3.refine((v) => v.every((x) => Math.abs(x) <= PART_LIMITS.translate), `parts move at most ${PART_LIMITS.translate} m (light edit)`),
  r: V3.refine((v) => v.every((x) => Math.abs(x) <= 360), "rotation in degrees, -360..360"),
  s: V3.refine((v) => v.every((x) => x >= PART_LIMITS.scaleMin && x <= PART_LIMITS.scaleMax), `scale ${PART_LIMITS.scaleMin}..${PART_LIMITS.scaleMax}`),
});
export const MaterialZ = z.strictObject({ baseColor: z.tuple([unit, unit, unit, unit]), metallic: unit, roughness: unit, emissive: z.tuple([unit, unit, unit]) });
const LayerZ = z.strictObject({ id: z.string().regex(LAYER_ID), name: z.string().min(1).max(32).regex(/^[^\u0000-\u001f]+$/), channel: z.enum(PAINT_CHANNELS), blend: z.enum(BLEND_MODES), opacity: z.number().int().min(0).max(255), visible: z.boolean(), rle: z.string().max(6 * 1024 * 1024) });

export const MeshEditDocZ = z.strictObject({
  v: z.literal(MESH_EDIT_VERSION),
  kind: z.literal("mesh-edit"),
  name: NAME,
  base: z.strictObject({
    sha256: SHA,
    source: z.enum(["meshgen", "import", "upload", "library"]),
    assetId: z.string().max(64).nullable(),
    /** template meshes: the meshgen template and the spec that built the base (sliders edit `spec` in the doc) */
    template: z.strictObject({ id: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/), version: z.number().int().min(1), spec: z.record(z.string(), z.unknown()) }).nullable(),
  }),
  legal: z.strictObject({ legalClass: z.enum(LEGAL_CLASSES), retention: z.enum(["project", "job"]), game: z.string().max(32).nullable(), derivedFrom: z.array(SHA).max(32) }),
  tex: z.strictObject({ w: z.union(MESH_TEX_SIZES.map((n) => z.literal(n)) as unknown as [z.ZodLiteral<256>, z.ZodLiteral<512>]), h: z.union(MESH_TEX_SIZES.map((n) => z.literal(n)) as unknown as [z.ZodLiteral<256>, z.ZodLiteral<512>]) }),
  parts: z.record(PART, PartXformZ).refine((p) => Object.keys(p).length <= MAX_PARTS, `at most ${MAX_PARTS} parts`),
  materials: z.record(z.string().min(1).max(48), MaterialZ).refine((m) => Object.keys(m).length <= MAX_SLOTS, `at most ${MAX_SLOTS} material slots`),
  layers: z.array(LayerZ).max(MAX_LAYERS),
  /** the template spec as edited by the sliders (null = untouched / not a template mesh) */
  params: z.record(z.string(), z.unknown()).nullable(),
}).superRefine((d, ctx) => {
  const ids = new Set<string>();
  d.layers.forEach((l, i) => { if (ids.has(l.id)) ctx.addIssue({ code: "custom", path: ["layers", i, "id"], message: "layer ids must be unique" }); ids.add(l.id); });
  if (d.legal.legalClass === "game-derived" && d.legal.retention !== "job") ctx.addIssue({ code: "custom", path: ["legal", "retention"], message: "game-derived content is kept for the job only" });
  if (d.legal.legalClass === "game-derived" && !d.legal.derivedFrom.length) ctx.addIssue({ code: "custom", path: ["legal", "derivedFrom"], message: "game-derived content lists the base it was derived from" });
  if (d.params && !d.base.template) ctx.addIssue({ code: "custom", path: ["params"], message: "only template meshes have parameters" });
});

export type PartXform = z.infer<typeof PartXformZ>;
export type MeshMaterial = z.infer<typeof MaterialZ>;
export type MeshEditDoc = Omit<z.infer<typeof MeshEditDocZ>, "tex" | "layers"> & { tex: { w: number; h: number }; layers: EncodedLayer[] };
export const IDENTITY_XFORM: PartXform = { t: [0, 0, 0], r: [0, 0, 0], s: [1, 1, 1] };

export type MeshDocCheck = { ok: true; doc: MeshEditDoc } | { ok: false; error: string };
export function checkMeshEditDoc(raw: unknown): MeshDocCheck {
  const r = MeshEditDocZ.safeParse(raw);
  if (!r.success) { const i = r.error.issues[0]; return { ok: false, error: `${i.path.join(".") || "doc"}: ${i.message}` }; }
  const doc = r.data as MeshEditDoc;
  const n = doc.tex.w * doc.tex.h;
  for (const l of doc.layers) if (!decodePixels(l.rle, n)) return { ok: false, error: `layer ${l.id}: pixel data is malformed or the wrong size` };
  return { ok: true, doc };
}

export function layersOf(doc: Pick<MeshEditDoc, "tex" | "layers">): LayerSet {
  const n = doc.tex.w * doc.tex.h;
  return { w: doc.tex.w, h: doc.tex.h, layers: doc.layers.map((l) => ({ id: l.id, name: l.name, channel: l.channel, blend: l.blend, opacity: l.opacity, visible: l.visible, px: decodePixels(l.rle, n)! })) };
}

/** A fresh doc on a base mesh: no transforms, the mesh's own material values, no layers. */
export function newMeshEditDoc(i: { name: string; base: MeshEditDoc["base"]; legal: MeshEditDoc["legal"]; tex: { w: number; h: number }; materials: Record<string, MeshMaterial> }): MeshEditDoc {
  return { v: 1, kind: "mesh-edit", name: i.name, base: i.base, legal: i.legal, tex: i.tex, parts: {}, materials: i.materials, layers: [], params: null };
}

