input.content:
// Cyrus Model Studio LAYER 3: the edit OPERATIONS on a MeshEditDoc, recorded in the one Model Studio op log
// (../oplog.ts, the same log the layer-2 editor uses). Pure + client-safe, deterministic.
//   xform     set / add a named part's translate (m), rotate (deg), scale, with snapping resolved here (so a replay
//             never depends on UI state); reset = back to how the mesh placed it
//   material  set a material slot's base colour / metallic / roughness / emissive
//   paint     one layer-1 paint op (brush, fill of a UV island, decal, layer add/set/delete/move) on the doc's
//             per-channel lossless layers: the SAME paint engine as layer 1 (../paint.ts)
//   param     set one template parameter (a slider) on a template mesh; the spec is re-validated against the meshgen
//             template's own schema, so the doc never holds a spec the Blender template would refuse
import { applyOp as applyPaint, checkOp as checkPaintOp, OP_LABEL as PAINT_LABEL, type Op as PaintOp } from "../paint";
import { encodeLayers } from "../doc";
import { opLog, type Applied } from "../oplog";
import { IDENTITY_XFORM, layersOf, MAX_PARTS, PART_LIMITS, PartXformZ, MaterialZ, type MeshEditDoc, type MeshMaterial, type PartXform } from "./doc";
import { setParam, type ParamValue } from "./params";

export type MeshOp =
  | { op: "xform"; part: string; mode: "set" | "add"; t?: [number, number, number]; r?: [number, number, number]; s?: [number, number, number]; snap?: { move?: number; rotate?: number; scale?: number } }
  | { op: "reset"; part: string }
  | { op: "material"; slot: string; props: Partial<MeshMaterial> }
  | { op: "paint"; p: PaintOp }
  | { op: "param"; key: string; value: ParamValue };

const snapTo = (v: number, step?: number) => (step && step > 0 ? Math.round(v / step) * step : v);
const r6 = (v: number) => Math.round(v * 1e6) / 1e6 || 0;
const v3 = (a: readonly number[], f: (x: number, i: number) => number): [number, number, number] => [r6(f(a[0], 0)), r6(f(a[1], 1)), r6(f(a[2], 2))];

export function applyMeshOp(doc: MeshEditDoc, op: MeshOp, known?: { parts: readonly string[]; slots: readonly string[] }): Applied<MeshEditDoc> {
  const no = (error: string): Applied<MeshEditDoc> => ({ ok: false, error });
  switch (op.op) {
    case "xform": {
      if (known && !known.parts.includes(op.part)) return no(`there is no part called ${op.part}`);
      const cur = doc.parts[op.part] ?? IDENTITY_XFORM;
      if (!doc.parts[op.part] && Object.keys(doc.parts).length >= MAX_PARTS) return no(`at most ${MAX_PARTS} parts can be moved`);
      const add = op.mode === "add";
      const next: PartXform = {
