      if (!chk.success) return no(`${op.part}: ${chk.error.issues[0].message}`);
      const parts = { ...doc.parts };
      if (same(next, IDENTITY_XFORM)) delete parts[op.part]; else parts[op.part] = next;
      return { ok: true, doc: { ...doc, parts }, label: `${labelOf(op)} ${op.part}`, select: [op.part] };
    }
    case "reset": {
