// Cyrus Model Studio LAYER 3: PARAMETER SLIDERS for template-made meshes (meshgen rung 1: rifle, crate, sword).
// Pure + client-safe. A template mesh was built by fixed Blender code from a JSON spec (lib/cyrus/meshgen/templates.ts);
// a slider edits ONE key of a copy of that spec. Every edit is re-validated with the template's own Zod schema
// (meshgen checkSpec), so the doc never holds a spec the Blender template would refuse. Nothing here calls a model:
//   - live: blockout() turns the spec into an APPROXIMATE block-out (one box per named part, same part names as the
//     Blender template), shown in the viewport and labelled as approximate
//   - real: "Rebuild" queues the SAME template on the meshgen worker on node-2 with the edited spec (no model call,
//     0 tokens; lib/cyrus/modelstudio/retex/service.ts rebuildMesh), and the result replaces the base mesh
// Defaults are the values the Blender module uses when a key is absent (copied from lib/cyrus/meshgen/blender/*.py
// for the default style; other styles can differ). A slider that was never touched does not write a key.
import { checkSpec, getTemplate } from "../../meshgen/templates";
import type { Img, ModelScene, ScenePart } from "../scene";
import { SCENE_FACES } from "../scene";

export type ParamValue = number | string | boolean;
export type ParamDef =
  | { key: string; label: string; kind: "range"; min: number; max: number; step: number; def: number; unit: "m" | "" | "deg" }
  | { key: string; label: string; kind: "int"; min: number; max: number; def: number }
  | { key: string; label: string; kind: "enum"; options: readonly string[]; def: string }
  | { key: string; label: string; kind: "bool"; def: boolean };

export const TEMPLATE_PARAMS: Readonly<Record<string, readonly ParamDef[]>> = {
  rifle: [
