// Cyrus Model Studio LAYER 3: the EXPORT-TARGET picker and per-channel PACKING, both driven by the game adapters'
// asset profiles (lib/cyrus/adapters/asset-profile.ts). Pure + client-safe. Honest by construction:
//   - a game is "yes" only when its adapter exists AND its profile takes this mesh format (or a converter exists).
//     Minecraft Java is "no" for 3D meshes: it ships cuboid models (bbmodel / item model JSON) and Cyrus has no
//     glTF-to-Minecraft converter. That stays "no" until a converter is written and tested.
//   - games the research names but no adapter implements are listed as "planned" / "later" with the missing piece,
//     never as exportable.
//   - channels stay separate lossless layers in the doc; packing into a game's files happens HERE, at export, from
//     the profile's channelMap. A channel the game has no slot for is reported as "not shipped", never silently packed.
import type { AssetProfile, ChannelRole } from "../../adapters/asset-profile";
import { ADAPTERS, type GameAdapter } from "../../adapters";
import type { PaintChannel } from "../layers";

export type ExportStatus = "yes" | "no" | "planned" | "later";
export type PackSlot = { file: string; channels: string; roles: ChannelRole[] };
export type ExportTarget = {
  game: string; label: string; status: ExportStatus; reason: string;
  delivery: string | null; maturity: string | null;
  /** how the channels would be packed for this game (null when it cannot take the mesh) */
  packing: { slots: PackSlot[]; notShipped: PaintChannel[] } | null;
};

/** Mesh formats that ARE a glTF (what Model Studio layer 3 edits). */
const GLTF_FORMATS = new Set(["gltf", "glb", "gltf-binary"]);
/** glTF -> engine format converters that exist and are tested. None yet; adding one = an entry here + its tests. */
export const MESH_CONVERTERS: Readonly<Record<string, string>> = {};

/** Research-named games with no adapter yet (MULTIGAME H-3d-games.md); shown so the picker is honest about scope. */
export const PLANNED_TARGETS: readonly { game: string; label: string; status: "planned" | "later"; reason: string }[] = [
  { game: "fivem", label: "FiveM", status: "planned", reason: "No FiveM adapter yet, and its YTD textures need the Windows packing worker, which is not built." },
  { game: "redm", label: "RedM", status: "planned", reason: "No RedM adapter yet; same Windows packing worker as FiveM (not built)." },
  { game: "gmod", label: "Garry's Mod", status: "later", reason: "No adapter yet (VTF textures, Workshop publishing by the owner)." },
  { game: "zomboid", label: "Project Zomboid", status: "later", reason: "No adapter yet." },
];

const ROLE_OF: Record<PaintChannel, ChannelRole> = { albedo: "albedo", normal: "normal", roughness: "roughness", metallic: "metallic", emissive: "emissive", mask: "mask" };

/** Group the doc's channels by the game file they land in (packing happens only at export). */
export function packPlan(profile: AssetProfile, channels: readonly PaintChannel[]): { slots: PackSlot[]; notShipped: PaintChannel[] } {
  const slots = new Map<string, PackSlot>();
  const notShipped: PaintChannel[] = [];
  for (const c of channels) {
    if (c === "mask") continue; // an authoring aid, never shipped
    const t = profile.channelMap[ROLE_OF[c]];
    if (!t) { notShipped.push(c); continue; }
    const s = slots.get(t.file) ?? { file: t.file, channels: "", roles: [] };
    s.roles.push(ROLE_OF[c]); s.channels = s.channels ? `${s.channels}+${t.channels}` : t.channels;
    slots.set(t.file, s);
  }
  return { slots: [...slots.values()], notShipped };
}

export function canTakeMesh(profile: AssetProfile): { ok: boolean; reason: string } {
  const native = profile.meshFormats.some((f) => GLTF_FORMATS.has(f));
  if (native) return { ok: true, reason: `${profile.game} takes glTF meshes` };
  const conv = profile.meshFormats.find((f) => MESH_CONVERTERS[f]);
  if (conv) return { ok: true, reason: `converted to ${conv} by ${MESH_CONVERTERS[conv]}` };
  if (profile.engineFamily === "minecraft-java") return { ok: false, reason: "Minecraft Java has no 3D meshes: it ships cuboid models (bbmodel / item model JSON), and Cyrus has no glTF-to-Minecraft converter. Not exportable until one exists." };
  return { ok: false, reason: `${profile.game} takes ${profile.meshFormats.join(", ") || "no meshes"}; there is no converter from glTF yet.` };
}

/** Every target the picker shows, adapters first (in registry order), then the planned games. */
export function exportTargets(channels: readonly PaintChannel[], adapters: readonly GameAdapter[] = ADAPTERS): ExportTarget[] {
  const out: ExportTarget[] = [];
  for (const a of adapters) {
    const p = a.assetProfile as AssetProfile | undefined;
    if (!p) { out.push({ game: a.game, label: a.label ?? a.game, status: "no", reason: "This game's adapter declares no asset profile.", delivery: null, maturity: null, packing: null }); continue; }
    const can = canTakeMesh(p);
    out.push({ game: p.game, label: labelOf(a), status: can.ok ? "yes" : "no", reason: can.reason, delivery: p.delivery, maturity: p.maturity, packing: can.ok ? packPlan(p, channels) : null });
  }
  for (const t of PLANNED_TARGETS) if (!out.some((o) => o.game === t.game)) out.push({ ...t, delivery: null, maturity: null, packing: null });
  return out;
}
const labelOf = (a: GameAdapter) => (a as { label?: string }).label ?? (a.game === "minecraft" ? "Minecraft Java" : a.game);

