// Cyrus Model Studio LAYER 3: the LEGAL-CLASS badge and the rules it implies, straight from the canonical ledger
// (lib/cyrus/assets3d/manifest.ts ledgerRules + libraryEligible). Pure + client-safe. The UI only shows this; the
// server enforces the same rules (./service.ts): game-derived content is kept for the job only, never enters the
// library, is never redistributed, and only the person's own changes (a delta) can ship.
import { ledgerRules, libraryEligible, type LedgerRules, type LegalClass } from "../../assets3d/manifest";
import type { MeshEditDoc } from "./doc";

export type LegalBadge = { label: string; tone: "ok" | "warn"; summary: string; lines: string[]; rules: LedgerRules; library: "eligible" | "not shared" };

const LABEL: Record<LegalClass, string> = {
  "user-original": "Your own", "ai-generated-for-user": "AI-made for you", "platform-library": "Library (CC0)", "third-party-licensed": "Third-party licence", "game-derived": "Game-derived",
};

export function legalBadge(doc: Pick<MeshEditDoc, "legal" | "base">): LegalBadge {
  const c = doc.legal.legalClass;
  const rules = ledgerRules(c);
  const source = doc.base.source === "meshgen" ? "ai" : doc.base.source === "library" ? "library" : doc.base.source;
  const eligible = libraryEligible({ legalClass: c, provenance: { source, derivedFrom: doc.legal.derivedFrom } as never });
  const lines: string[] = [];
  if (!rules.storeBeyondJob) lines.push("Kept for this session only (job retention), deleted when it ends.");
  if (!rules.redistribute) lines.push("Never redistributed: the base file is not stored, shared or shipped.");
  if (rules.deliverable === "delta-only") lines.push("Only your changes ship (a delta); players use their own game files.");
  lines.push(eligible ? "Eligible for the community library after the content checks." : "Not shared to the community library.");
  const summary = c === "game-derived" ? "Game-derived, not redistributed." : c === "third-party-licensed" ? "Licensed to you; not redistributed." : c === "ai-generated-for-user" ? "Made for you by Cyrus." : c === "platform-library" ? "From the Cyrus library (CC0)." : "Made by you.";
  return { label: LABEL[c], tone: c === "game-derived" || c === "third-party-licensed" ? "warn" : "ok", summary, lines, rules, library: eligible ? "eligible" : "not shared" };
}

/** Server rule: may this doc be saved as a project revision at all? (game-derived content may not outlive its job) */
export function retentionAllowsSave(doc: Pick<MeshEditDoc, "legal">): { ok: true } | { ok: false; reason: string } {
  return ledgerRules(doc.legal.legalClass).storeBeyondJob ? { ok: true } : { ok: false, reason: "Game-derived content is kept for this session only, so it cannot be saved as a revision. Export your changes before you close the session." };
}

