export function retentionAllowsSave(doc: Pick<MeshEditDoc, "legal">): { ok: true } | { ok: false; reason: string } {
  return ledgerRules(doc.legal.legalClass).storeBeyondJob ? { ok: true } : { ok: false, reason: "Game-derived content is kept for this session only, so it cannot be saved as a revision. Export your changes before you close the session." };
}

