// Cyrus Model Studio LAYER 3: named-part transforms -> per-part matrices for the shared viewport (the layer-1
// ModelViewport setPartOverrides) and for the pure pick (../pose.ts posedScene), so what you see is what you pick and
// what the export bakes. Pure + client-safe. Each part turns and scales about its OWN centre (its bounding-box
// centre in the base mesh), rotation order X then Y then Z (same Euler order as the creature rig).
import { mul4, Rx4, Ry4, Rz4, S4, T4, type M4, type V3 } from "../math";
import type { PartOverrides } from "../pose";
import type { ModelScene } from "../scene";
import type { PartXform } from "./doc";

/** Bounding-box centre of every part of a scene, by part index. */
export function partCentres(s: ModelScene): V3[] {
  const lo = s.parts.map(() => [Infinity, Infinity, Infinity] as V3), hi = s.parts.map(() => [-Infinity, -Infinity, -Infinity] as V3);
  for (let t = 0; t < s.triCount; t++) {
    const p = s.part[t];
    for (let k = 0; k < 3; k++) for (let a = 0; a < 3; a++) { const v = s.pos[t * 9 + k * 3 + a]; lo[p][a] = Math.min(lo[p][a], v); hi[p][a] = Math.max(hi[p][a], v); }
  }
  return lo.map((l, i) => (Number.isFinite(l[0]) ? ([(l[0] + hi[i][0]) / 2, (l[1] + hi[i][1]) / 2, (l[2] + hi[i][2]) / 2] as V3) : ([0, 0, 0] as V3)));
}

/** T(c + t) * Rz * Ry * Rx * S * T(-c): the part moves by t and turns/scales about its centre c. */
export function partMatrix(x: PartXform, c: V3): M4 {
  return mul4(T4(c[0] + x.t[0], c[1] + x.t[1], c[2] + x.t[2]), mul4(Rz4(x.r[2]), mul4(Ry4(x.r[1]), mul4(Rx4(x.r[0]), mul4(S4(x.s[0], x.s[1], x.s[2]), T4(-c[0], -c[1], -c[2]))))));
}

/** The doc's part transforms as viewport overrides (part index -> matrix), matched by part NAME. */
export function partOverrides(parts: Readonly<Record<string, PartXform>>, s: ModelScene): PartOverrides {
  const out: PartOverrides = new Map();
  const centres = partCentres(s);
  s.parts.forEach((p, i) => { const x = parts[p.name]; if (x) out.set(i, partMatrix(x, centres[i])); });
  return out;
}

/** Part names in the doc that the mesh does not have (a rebuilt template lost a part): reported, never applied. */
export const orphanParts = (parts: Readonly<Record<string, PartXform>>, s: ModelScene) => Object.keys(parts).filter((n) => !s.parts.some((p) => p.name === n));

