// Cyrus Model Studio LAYER 3: the SERVER service behind /api/cyrus/models/v1/projects/:projectId/meshes/**. SERVER
// ONLY by use (pure logic + injected deps; no Nxeon imports: host seam). Every write is plan-gated HERE, server side,
// fail closed: retexture / transform / material / rebuild / save need the top "All models" plan (canModelStudio,
// kind "model"); an unknown plan is refused for edits and never for viewing. Viewing (list, open, the mesh bytes,
// export targets) is never gated.
//
// What a project holds that layer 3 edits:
//   mesh      a CyrusProjectAsset kind "model", mime model/gltf-binary (meshgen ingest: path = object-store key,
//             provenance.legalClass, .module = the template id, .requestKey = the meshgen request with the spec)
//   edits     the newest MeshEditDoc row for that key (kind "model", mime MESH_EDIT_MIME, origin "edited")
// SAVE = a new revision kind "asset" + a MeshEditDoc row, expectedHeadId -> 409 stale_head (the studios' rule). The
// base mesh bytes are never copied into the doc. Game-derived content (job retention) cannot be saved at all.
// REBUILD (template meshes) = the SAME meshgen template on the node-2 worker with the slider-edited spec and the
// original budget: no model call, 0 tokens. Off unless CYRUS_MESHGEN=1 (503 with the reason; the block-out preview
// still works).
import { canonicalJson, sha256Hex } from "../../assets/textures";
import { canModelStudio, type ModelStudioAction } from "../../engine-core/asset-gate";
import type { ManifestEntry } from "../../engine-core/revisions";
import { checkSpec, getTemplate } from "../../meshgen/templates";
import { StudioError, type AssetRow, type StudioStore } from "../../studios/service";
import { checkMeshEditDoc, MESH_EDIT_MIME, MESH_TEX_SIZES, newMeshEditDoc, type MeshEditDoc, type MeshMaterial } from "./doc";
import { exportTargets, type ExportTarget } from "./export";
import { legalBadge, retentionAllowsSave, type LegalBadge } from "./legal";
import { paramsFor, type ParamDef } from "./params";
import { LEGAL_CLASSES, type LegalClass } from "../../assets3d/manifest";

export const GLB_MIME = "model/gltf-binary";
export const MESH_KEY = /^[a-z][a-z0-9_]{0,47}$/;

export type MeshServiceDeps = {
  store: Pick<StudioStore, "project" | "assets" | "revisions" | "addRevision" | "recordAsset">;
  planOf: (userId: string) => Promise<unknown>;
  /** the object store the meshgen worker writes to (glb + request json) */
  objects: { get(key: string): Promise<Uint8Array | null> };
  /** queue a template rebuild on the meshgen worker; null = CYRUS_MESHGEN is off here */
  rebuild: null | ((req: Record<string, unknown>) => Promise<{ ok: true; jobId: string } | { ok: false; code: string; message: string }>);
};

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();
const newestFirst = (a: AssetRow, b: AssetRow) => ts(b.createdAt) - ts(a.createdAt) || (a.id < b.id ? 1 : -1);
const gate = async (deps: MeshServiceDeps, userId: string, action: ModelStudioAction) => {
  const d = canModelStudio(await deps.planOf(userId).catch(() => null), action);
  if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {});
};
async function owned(deps: MeshServiceDeps, userId: string, projectId: string) {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}

export type MeshEntry = {
  key: string; assetId: string; sha256: string; size: number; path: string | null; createdAt: string;
  legalClass: LegalClass; source: MeshEditDoc["base"]["source"];
  template: { id: string; version: number; label: string } | null;
  stats: unknown; requestKey: string | null;
  edit: { assetId: string; revisionId: string; createdAt: string; doc: MeshEditDoc; stale: string | null } | null;
};

/** Pure: the editable meshes of a project (newest mesh row per key + the newest edit doc on it). */
export function resolveMeshes(rows: readonly AssetRow[]): MeshEntry[] {
  const meshes = new Map<string, AssetRow>(), edits = new Map<string, { row: AssetRow; doc: MeshEditDoc }>();
  for (const r of [...rows].sort(newestFirst)) {
    if (r.kind !== "model") continue;
    if (r.mime === GLB_MIME && !meshes.has(r.assetKey)) meshes.set(r.assetKey, r);
    if (r.mime === MESH_EDIT_MIME && !edits.has(r.assetKey)) { const c = checkMeshEditDoc(obj(r.provenance).doc); if (c.ok) edits.set(r.assetKey, { row: r, doc: c.doc }); }
  }
  const out: MeshEntry[] = [];
  for (const [key, r] of meshes) {
    const p = obj(r.provenance);
    const lc = (LEGAL_CLASSES as readonly string[]).includes(String(p.legalClass)) ? (p.legalClass as LegalClass) : "ai-generated-for-user";
    const tpl = typeof p.module === "string" && p.rung === "template" ? getTemplate(p.module) : null;
    const e = edits.get(key);
    out.push({
      key, assetId: r.id, sha256: r.sha256, size: r.size, path: r.path, createdAt: new Date(r.createdAt).toISOString(),
      legalClass: lc, source: p.generator === "ai-mesh" || p.rung ? "meshgen" : p.source === "upload" ? "upload" : "import",
      template: tpl ? { id: tpl.id, version: tpl.version, label: tpl.label } : null, stats: p.stats ?? null, requestKey: typeof p.requestKey === "string" ? p.requestKey : null,
      edit: e ? { assetId: e.row.id, revisionId: e.row.revisionId, createdAt: new Date(e.row.createdAt).toISOString(), doc: e.doc, stale: e.doc.base.sha256 !== r.sha256 ? "the mesh was rebuilt since these edits; part moves and materials are reapplied by name" : null } : null,
    });
  }
  return out.sort((a, b) => (a.key < b.key ? -1 : 1));
}

export type MeshAccess = { edit: ReturnType<typeof canModelStudio>; view: ReturnType<typeof canModelStudio> };
export type MeshView = { mesh: MeshEntry; doc: MeshEditDoc; legal: LegalBadge; targets: ExportTarget[]; params: readonly ParamDef[]; access: MeshAccess; headRevisionId: string | null; revisionSeq: number | null };

/** The spec the base mesh was built from (template meshes), read from the meshgen request in the object store. */
async function baseSpec(deps: MeshServiceDeps, m: MeshEntry): Promise<Record<string, unknown> | null> {
  if (!m.template || !m.requestKey) return null;
  const raw = await deps.objects.get(m.requestKey).catch(() => null);
  if (!raw) return null;
  try { const j = JSON.parse(new TextDecoder().decode(raw)); return j && typeof j.spec === "object" ? (j.spec as Record<string, unknown>) : null; } catch { return null; }
}

export async function listMeshes(deps: MeshServiceDeps, userId: string, projectId: string) {
  await owned(deps, userId, projectId);
  const plan = await deps.planOf(userId).catch(() => null);
  return { meshes: resolveMeshes(await deps.store.assets(projectId)).map(({ edit, ...m }) => ({ ...m, edited: !!edit })), access: { edit: canModelStudio(plan, "save"), view: canModelStudio(plan, "view") } };
}

export async function openMesh(deps: MeshServiceDeps, userId: string, projectId: string, key: string, defaults: { materials: Record<string, MeshMaterial>; tex: number }): Promise<MeshView> {
  await owned(deps, userId, projectId);
  const m = resolveMeshes(await deps.store.assets(projectId)).find((x) => x.key === key);
  if (!m) throw new StudioError(404, "not_found", `No mesh called ${key} in this mod.`);
  const plan = await deps.planOf(userId).catch(() => null);
  const spec = await baseSpec(deps, m);
  const tex = (MESH_TEX_SIZES as readonly number[]).includes(defaults.tex) ? defaults.tex : 1024;
  const doc = m.edit?.doc ?? newMeshEditDoc({
    name: key, tex: { w: tex, h: tex }, materials: defaults.materials,
    base: { sha256: m.sha256, source: m.source, assetId: m.assetId, template: m.template && spec ? { id: m.template.id, version: m.template.version, spec } : null },
    legal: { legalClass: m.legalClass, retention: m.legalClass === "game-derived" ? "job" : "project", game: null, derivedFrom: [] },
  });
  const revs = await deps.store.revisions(projectId);
  return {
    mesh: m, doc, legal: legalBadge(doc), targets: exportTargets(["albedo", ...new Set(doc.layers.map((l) => l.channel))]), params: m.template ? paramsFor(m.template.id) : [],
    access: { edit: canModelStudio(plan, "save"), view: canModelStudio(plan, "view") }, headRevisionId: revs.at(-1)?.id ?? null, revisionSeq: m.edit ? revs.find((r) => r.id === m.edit!.revisionId)?.seq ?? null : null,
  };
}

