  await gate(deps, i.userId, "save");
  await owned(deps, i.userId, i.projectId);
  const c = checkMeshEditDoc(i.doc);
  if (!c.ok) throw new StudioError(400, "bad_doc", c.error);
  const doc = c.doc;
  if (doc.name !== i.key) throw new StudioError(400, "bad_doc", "the doc name must match the mesh key");
  const m = resolveMeshes(await deps.store.assets(i.projectId)).find((x) => x.key === i.key);
  if (!m) throw new StudioError(404, "not_found", `No mesh called ${i.key} in this mod.`);
  if (doc.base.sha256 !== m.sha256) throw new StudioError(409, "stale_head", "This mesh was rebuilt since you opened it. Reload, then save again.");
  // the server's legal class wins over anything the client sent
  if (doc.legal.legalClass !== m.legalClass) throw new StudioError(400, "bad_doc", "the legal class must be the mesh's own");
  const keep = retentionAllowsSave(doc);
