  if ((i.baseEditId ?? null) !== (m.edit?.assetId ?? null)) throw new StudioError(409, "stale_head", "These edits were saved somewhere else since you opened them. Reload, then save again.");
  if (doc.params) { if (!doc.base.template) throw new StudioError(400, "bad_doc", "only template meshes have parameters"); const s = checkSpec("template", doc.base.template.id, doc.params); if (!s.ok) throw new StudioError(422, "bad_params", s.issues[0]?.message ?? "the template refused these parameters"); }
