    rev = await deps.store.addRevision(i.projectId, { kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: "cyrus-model-studio L3" }, message: (i.message ?? `Edited ${i.key} in Model Studio`).slice(0, 200) });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
