export async function rebuildMesh(deps: MeshServiceDeps, i: { userId: string; projectId: string; key: string; params: unknown }): Promise<{ jobId: string }> {
  await gate(deps, i.userId, "rebuild");
  await owned(deps, i.userId, i.projectId);
  const m = resolveMeshes(await deps.store.assets(i.projectId)).find((x) => x.key === i.key);
  if (!m) throw new StudioError(404, "not_found", `No mesh called ${i.key} in this mod.`);
  if (!m.template) throw new StudioError(400, "not_template", "Only meshes made from a template can be rebuilt from parameters.");
  const s = checkSpec("template", m.template.id, i.params);
  if (!s.ok) throw new StudioError(422, "bad_params", s.issues[0]?.message ?? "the template refused these parameters");
  if (!deps.rebuild) throw new StudioError(503, "rebuild_off", "Rebuilding runs the Blender template on the mesh worker, which is switched off here. The block-out preview still shows the change.");
  const orig = m.requestKey ? await deps.objects.get(m.requestKey).catch(() => null) : null;
  let base: Record<string, unknown> | null = null;
  try { base = orig ? JSON.parse(new TextDecoder().decode(orig)) : null; } catch { base = null; }
  if (!base) throw new StudioError(409, "request_missing", "The original mesh request is not on record, so the rebuild cannot reuse its budget.");
