// Cyrus Model Studio LAYER 3: the REAL dependencies of /api/cyrus/models/v1/projects/:projectId/meshes/**. SERVER
// ONLY. No new Nxeon imports: the Model Studio viewer + plan lookup + StudioStore come through the studios' wiring
// (../deps.ts, ../../studios/deps.ts), the mesh bytes and template requests from the meshgen object store
// (../../meshgen/queue.ts), the rebuild through the meshgen worker queue (inert unless CYRUS_MESHGEN=1).
import { getHost } from "../../host";
import { prismaStudioStore, studioPlanOf } from "../../studios/deps";
import { meshgenQueue } from "../../meshgen/queue";
import { meshgenEnabled, submitMeshgen } from "../../meshgen/worker";
import { modelStudioViewer } from "../deps";
import type { MeshApiDeps } from "./http";
import type { MeshServiceDeps } from "./service";

export function meshServiceDeps(env: Record<string, string | undefined> = process.env): MeshServiceDeps {
  const { queue, store } = meshgenQueue(env);
  return {
    store: prismaStudioStore, planOf: studioPlanOf(env),
    objects: { get: (k) => store.get(k) },
    rebuild: meshgenEnabled(env) ? async (req) => {
      const r = await submitMeshgen(req as never, { queue, store, env });
      return r.ok ? { ok: true, jobId: r.job.id } : { ok: false, code: r.code, message: r.issues[0]?.message ?? r.code };
    } : null,
  };
}

export function meshApiDeps(env: Record<string, string | undefined> = process.env): MeshApiDeps {
  return {
    viewer: modelStudioViewer,
    service: meshServiceDeps(env),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:${key}`, { max, windowMs }),
  };
}
