// Cyrus Model Studio LAYER 3: HTTP handlers of /api/cyrus/models/v1/projects/:projectId/meshes/** (framework-free,
// tested with fakes; the app routes are one-line wrappers with meshApiDeps()). Same chain as layer 1: viewer (Model
// Studio gate; anyone else gets 404) -> rate limit -> input validation -> plan gate inside the service (writes only,
// fail closed) -> the service.
//   GET  .../meshes                      the project's editable meshes + access
//   GET  .../meshes/:key                 open one: mesh record, edit doc (saved or fresh), legal badge, export targets, sliders
//   GET  .../meshes/:key/glb             the base mesh bytes (never plan-gated; the owner only; sha-checked)
//   POST .../meshes/:key/revisions       { doc, baseEditId, expectedHeadId } save the edit session as a revision
//   POST .../meshes/:key/rebuild         { params } rebuild a template mesh on the meshgen worker (no model call)
import { StudioError } from "../../studios/service";
import type { StudioViewer } from "../../studios/http";
import { listMeshes, meshBytes, MESH_KEY, openMesh, rebuildMesh, saveMeshEdit, type MeshServiceDeps } from "./service";

export type MeshApiDeps = {
  viewer: () => Promise<StudioViewer | null>;
  service: MeshServiceDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
};
const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
const PROJECT = /^cp[0-9a-f]{20}$/, ID = /^[A-Za-z0-9_-]{1,64}$/;
const MAX_BODY = 8 * 1024 * 1024;
const need = (ok: boolean, msg: string) => { if (!ok) throw new StudioError(400, "bad_request", msg); };
const idOrNull = (v: unknown, name: string): string | null => { if (v === null || v === undefined) return null; need(typeof v === "string" && ID.test(v), `${name} is not valid`); return v as string; };

async function readJson(req: Request): Promise<Record<string, unknown>> {
  const text = await req.text();
  if (text.length > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  try { const v = JSON.parse(text || "{}"); if (v && typeof v === "object" && !Array.isArray(v)) return v; } catch { /* fallthrough */ }
  throw new StudioError(400, "bad_json", "Send a JSON object.");
}
async function run(deps: MeshApiDeps, limit: { key: string; max: number }, body: (v: StudioViewer) => Promise<Response>): Promise<Response> {
  const viewer = await deps.viewer().catch(() => null);
  if (!viewer) return json(404, { error: "Not found" });
  const rl = deps.rateLimit(`mesh:${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try { return await body(viewer); } catch (e) {
    if (e instanceof StudioError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    console.error("[cyrus-model-studio L3]", limit.key, (e as Error).message);
    return json(500, { error: "Something went wrong on our side. Nothing was changed.", code: "server_error" });
  }
}
type P = { projectId?: string; key?: string };
const pid = (p: P) => { need(PROJECT.test(p.projectId ?? ""), "projectId is not valid"); return p.projectId!; };
const key = (p: P) => { need(MESH_KEY.test(p.key ?? ""), "key is not valid"); return p.key!; };

export const handleMeshes = (_req: Request, p: P, deps: MeshApiDeps) => run(deps, { key: "read", max: 120 }, async (v) => json(200, await listMeshes(deps.service, v.userId, pid(p))));
export const handleMesh = (_req: Request, p: P, deps: MeshApiDeps) => run(deps, { key: "read", max: 120 }, async (v) => json(200, await openMesh(deps.service, v.userId, pid(p), key(p))));
export const handleMeshGlb = (_req: Request, p: P, deps: MeshApiDeps) => run(deps, { key: "glb", max: 60 }, async (v) => {
  const b = await meshBytes(deps.service, v.userId, pid(p), key(p));
  return new Response(Buffer.from(b), { status: 200, headers: { ...H, "content-type": "model/gltf-binary" } });
});
export const handleSaveMesh = (req: Request, p: P, deps: MeshApiDeps) => run(deps, { key: "save", max: 30 }, async (v) => {
  const b = await readJson(req);
  return json(201, await saveMeshEdit(deps.service, { userId: v.userId, projectId: pid(p), key: key(p), doc: b.doc, baseEditId: idOrNull(b.baseEditId, "baseEditId"), expectedHeadId: idOrNull(b.expectedHeadId, "expectedHeadId"), message: typeof b.message === "string" ? b.message.slice(0, 200) : null }));
});
export const handleRebuildMesh = (req: Request, p: P, deps: MeshApiDeps) => run(deps, { key: "rebuild", max: 6 }, async (v) => {
  const b = await readJson(req);
  need(!!b.params && typeof b.params === "object" && !Array.isArray(b.params), "params must be an object");
  return json(202, await rebuildMesh(deps.service, { userId: v.userId, projectId: pid(p), key: key(p), params: b.params }));
});

