export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Model Studio · Cyrus");
}

/**
 * Full-page Model Studio (Cyrus Layer 1: viewport + paint). Gates: the Cyrus access rule -> the studios gate
 * (studioContext) -> Model Studio's own visibility (cyrus_model_studio_enabled OR a preview account; else 404).
 * Every plan may VIEW (orbit, channels, in-game contexts, previews); painting and saving are refused by the API on
 * plans below "All models" (and the UI shows the view-only state from the same decision).
 */
export default async function ModelStudioPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ model?: string | string[] }> }) {
  await requireModBuilderUser();
  const { id } = await params;
  const { mod } = await studioContext(id);
  if (!(await modelStudioViewer())) notFound();
  const m = (await searchParams).model;
  // the glTF sample (the PBR lane, not part of any mod) only exists off production
  return <ModelStudio mod={mod} initialKey={typeof m === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(m) ? m : null} samples={process.env.NODE_ENV !== "production"} />;
}
