function Body({ mod, initialKey, samples }: { mod: StudioMod; initialKey: string | null; samples: boolean }) {
  const [view, setView] = useState<ModelsView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const narrow = useNarrow();
  const load = useCallback(async () => { try { setView(await modelApi.models(mod.rootId)); } catch (e) { setErr((e as Error).message); } }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);
  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s models…</div>;
  const entries: AnyEntry[] = [...view.models, ...(samples ? [{ kind: "mesh", key: "sample_crate", label: "sample_crate", sample: true } as SampleEntry] : [])];
  if (!entries.length) {
    return (
      <main className="ms-ws ms-empty"><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
        <div className="cys-empty" style={{ maxWidth: 440 }}><SI n="cube" /><p><b>This mod has no models to paint yet.</b></p><p className="cys-hint">Model Studio paints the mod&apos;s animated creatures and held items. Ask Cyrus for a creature or a custom item in your next change.</p></div>
      </div></main>
    );
  }
  return narrow ? <Narrow mod={mod} view={view} entries={entries} initialKey={initialKey} reload={load} /> : <Editor mod={mod} view={view} entries={entries} initialKey={initialKey} reload={load} setView={setView} />;
}

// ======================================================================================================== editor

function Editor({ mod, view, entries, initialKey, reload, setView }: { mod: StudioMod; view: ModelsView; entries: AnyEntry[]; initialKey: string | null; reload: () => Promise<void>; setView: (v: ModelsView) => void }) {
  const toast = useToast();
  const light = useLight();
  const canEdit = view.access.edit.ok;
  const project = view.project;
  const [cur, setCur] = useState<string>(entries.find((e) => e.key === initialKey)?.key ?? entries[0].key);
  const [ed, setEd] = useState<Ed | null>(null);
  const edRef = useRef<Ed | null>(null);
  edRef.current = ed;
  const [ver, setVer] = useState(0); // bumps when live pixels change (UV canvas, checks)
  const [tool, setTool] = useState<Tool>("brush");
  const [color, setColor] = useState<[number, number, number]>([201, 204, 214]);
  const [size, setSize] = useState(1);
  const [shape, setShape] = useState<BrushShape>("square");
  const [mirror, setMirror] = useState(false);
  const [fillMode, setFillMode] = useState<"face" | "area">("face");
  const [stamp, setStamp] = useState<StampId>("star");
  const [activeLayer, setActiveLayer] = useState("paint");
  const [mode, setMode] = useState<ViewMode>("lit");
  const [wire, setWire] = useState(false);
  const [uvView, setUvView] = useState(false);
  const [lighting, setLighting] = useState<LightingPreset>("studio");
  const [camPreset, setCamPreset] = useState<CamPreset>("persp");
  const [ctx, setCtx] = useState<ViewContext>("firstperson");
  const [stateId, setStateId] = useState("idle");
  const [tab, setTab] = useState<"checks" | "paint" | "history">("checks");
  const [hover, setHover] = useState<{ hit: Hit; x: number; y: number } | null>(null);
  const [draftState, setDraftState] = useState<"idle" | "saving" | "saved" | "off">("idle");
  const [draftAt, setDraftAt] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [webgl] = useState(() => (typeof window === "undefined" ? true : webglOk()));

  const entry = entries.find((e) => e.key === cur)!;
  const isItem = entry.kind === "item3d";
  const profileChannels = useMemo(() => (ed ? paintChannels(ed.prep.profile) : []), [ed]);
  const modes = useMemo(() => (ed ? viewModes(ed.prep.profile) : []), [ed]);

  // ---------------------------------------------------------------- open a model (+ restore its draft)
  useEffect(() => {
    let off = false;
    (async () => {
      let draft: DraftView | null = null;
      if (project && !("sample" in entry)) draft = await modelApi.getDraft(project.id, entry.key).then((r) => r.draft, () => null);
      if (off) return;
      const e = edFor(entry, view.headRevisionId, draft);
      setEd(e); setActiveLayer(e.live.layers.find((l) => l.channel === "albedo")?.id ?? e.live.layers[0]?.id ?? "paint");
      setStateId("idle"); setMode("lit"); setDraftState(draft && e.restored ? "saved" : "idle"); setDraftAt(e.restored);
      const pal = entry.kind === "creature" ? Object.values(entry.spec.skin.palette) : entry.kind === "item3d" && entry.base.doc.spec ? Object.values(entry.base.doc.spec.palette) : [];
      if (pal[0]) setColor(rgbOf(pal.find((c, i) => i > 0) ?? pal[0]));
    })();
    return () => { off = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cur, view.headRevisionId]);

  // ---------------------------------------------------------------- composites
  const comps = useRef<Partial<Record<PaintChannel, Img>>>({});
  const recomposite = useCallback((e: Ed) => {
    const next: Partial<Record<PaintChannel, Img>> = {};
    for (const c of PAINT_CHANNELS) next[c] = compositeChannel(e.live, c, c === "albedo" ? e.prep.base : null);
    comps.current = next;
  }, []);
  const maps = useCallback((e: Ed): ViewMaps => {
    const out: ViewMaps = { albedo: comps.current.albedo! };
    if (!e.prep.profile) for (const c of ["normal", "roughness", "metallic", "emissive"] as const) if (!channelUntouched(e.live, c)) out[c] = comps.current[c];
    return out;
  }, []);

  // ---------------------------------------------------------------- the main viewport
  const cvRef = useRef<HTMLCanvasElement>(null);
  const vpRef = useRef<ModelViewport | null>(null);
  const [vpReady, setVpReady] = useState(false);
  useEffect(() => {
    if (!cvRef.current || !webgl) return;
    let dead = false;
    ModelViewport.create(cvRef.current, { mobile: false, light }).then((v) => { if (dead) { v.dispose(); return; } vpRef.current = v; setVpReady(true); });
    return () => { dead = true; vpRef.current?.dispose(); vpRef.current = null; setVpReady(false); };
    // the canvas only exists once a model is open (the first render shows "Opening the model")
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl, !!ed]);
  useEffect(() => { vpRef.current?.setTheme(light); }, [light]);
  const shownKey = useRef<string | null>(null);
  useEffect(() => {
    const v = vpRef.current;
    if (!v || !ed) return;
    recomposite(ed);
    const same = shownKey.current === ed.key;
    v.setScene(ed.scene, maps(ed), { pixel: !!ed.prep.profile, keepCamera: same });
    if (!same) v.preset(camPreset);
    shownKey.current = ed.key;
    setVer((x) => x + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vpReady, ed?.key, ed?.session.base]);
  // view mode / overlays
  useEffect(() => {
    const v = vpRef.current;
    if (!v || !ed) return;
    if (uvView) v.setDisplay({ kind: "image", img: uvChecker(ed.live.w, ed.live.h) });
    else if (mode === "lit" || mode === "ao") v.setDisplay({ kind: "lit" });
    else v.setDisplay({ kind: "image", img: channelImage(ed.live, mode, ed.prep.base) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, uvView, ver, vpReady]);
  useEffect(() => { vpRef.current?.setWire(wire); }, [wire, vpReady]);
  useEffect(() => { vpRef.current?.setLighting(lighting); }, [lighting, vpReady]);

  // ---------------------------------------------------------------- painting
  const stroke = useRef<{ op: Op; seen: Set<string>; last: { x: number; y: number } | null } | null>(null);
  const layerOf = (e: Ed, id: string) => e.live.layers.find((l) => l.id === id);
  const paintBlock = (e: Ed): string | null => {
    if (!canEdit) return view.access.edit.ok ? null : (view.access.edit as { reason: string }).reason;
    if ("sample" in e.entry) return null;
    const l = layerOf(e, activeLayer);
    if (!l) return "Pick a layer to paint on.";
    const pc = profileChannels.find((c) => c.channel === l.channel);
    if (pc && !pc.paintable) return pc.reason;
    return null;
  };
  const alphaAt = (x: number, y: number) => comps.current.albedo?.px[(y * comps.current.albedo.w + x) * 4 + 3] ?? 255;
  const valueColor = (e: Ed): [number, number, number] => { const l = layerOf(e, activeLayer); return l && (l.channel === "roughness" || l.channel === "metallic" || l.channel === "mask") ? [color[0], color[0], color[0]] : color; };

  /** Apply an op to the live layers now (no replay), update the touched region of the composite and the GPU texture. */
  const applyLive = (e: Ed, op: Op) => {
    applyOpMut(e.live, op, e.scene.tex.wrap);
    const r = opRect(op as never);
    const ch = "layer" in op ? layerOf(e, op.layer)?.channel : undefined;
    if (r && ch) compositeRegion(e.live, ch, ch === "albedo" ? e.prep.base : null, r, comps.current[ch]!);
    else recomposite(e);
    if (e.entry.kind === "item3d" && ch === "albedo") e.scene = sceneFromItem(e.key, comps.current.albedo!, e.scene.grip); // the silhouette may change
    vpRef.current?.setMaps(maps(e));
    if (e.entry.kind === "item3d") vpRef.current?.setScene(e.scene, maps(e), { pixel: true, keepCamera: true });
  };
  /** several ops as several steps in one go (a mirrored stamp), applied in order on the same live layers */
  const commitMany = (e: Ed, ops: Op[]) => {
    let session = e.session;
    for (const op of ops) { applyLive(e, op); session = sessionPush(session, op); }
    setEd({ ...e, session, dirty: true }); setVer((x) => x + 1);
  };
  const commit = (e: Ed, op: Op, alreadyApplied: boolean) => {
    if (!alreadyApplied) applyLive(e, op);
    const session = sessionPush(e.session, op);
    const next: Ed = { ...e, session, dirty: true };
    setEd(next); setVer((x) => x + 1);
  };
  // pick on the POSED scene (per-node overrides at the clock's time) so painting stays exact while a pose plays
  const pickOn = (e: Ed) => vpRef.current?.posed() ?? e.scene;
  const texelsFor = (e: Ed, ray: Parameters<typeof pickScene>[1]): Hit[] => {
    const sc = pickOn(e);
    const h = pickScene(sc, ray, { alphaAt });
    if (!h) return [];
    if (!mirror) return [h];
    const m = mirrorHit(sc, ray, { alphaAt });
    return m ? [h, m] : [h];
  };

  useEffect(() => {
    const v = vpRef.current;
    if (!v) return;
    v.readOnly = !canEdit && !(ed && "sample" in ed.entry);
    v.events = {
      onPaintStart: (ray) => {
        const e = edRef.current;
        if (!e || tool === "orbit") return false;
        const hits = texelsFor(e, ray);
        if (!hits.length) return false; // empty space = orbit
        const block = paintBlock(e);
        if (block && tool !== "pick") { toast(block, true); return false; }
        const h = hits[0];
        if (tool === "pick") {
          const l = layerOf(e, activeLayer);
          const img = comps.current[l?.channel ?? "albedo"];
          if (img) { const o = (h.texel[1] * img.w + h.texel[0]) * 4; if (img.px[o + 3]) setColor([img.px[o], img.px[o + 1], img.px[o + 2]]); }
          return true;
        }
        if (tool === "fill") {
          const spans = hits.flatMap((x) => { const region = regionOf(e.scene, x); const l = layerOf(e, activeLayer)!; return fillMode === "face" ? region : floodSpans(comps.current[l.channel]!, x.texel[0], x.texel[1], region); });
          if (spans.length) commit(e, { t: "fill", layer: activeLayer, color: valueColor(e), spans: dedupeSpans(spans) }, false);
          return true;
        }
        if (tool === "decal") {
          const st = makeStamp(stamp, valueColor(e));
          commitMany(e, hits.map((x) => ({ t: "decal", layer: activeLayer, x: x.texel[0] - Math.floor(st.w / 2), y: x.texel[1] - Math.floor(st.h / 2), stamp: st, clip: regionOf(e.scene, x) })));
          return true;
        }
        const pts: Px[] = hits.map((x) => [x.texel[0], x.texel[1]]);
        const op: Op = tool === "erase" ? { t: "erase", layer: activeLayer, size, shape, pts } : { t: "brush", layer: activeLayer, color: valueColor(e), size, shape, pts };
        stroke.current = { op, seen: new Set(pts.map((p) => p.join(","))), last: null };
        applyLive(e, op);
        return true;
      },
      onPaintMove: (ray, ev) => {
        const e = edRef.current, s = stroke.current;
        if (!e || !s || (s.op.t !== "brush" && s.op.t !== "erase")) return;
        // sub-steps in screen space so fast drags do not skip texels (never interpolated across UV seams)
        const from = s.last ?? { x: ev.clientX, y: ev.clientY };
        const steps = Math.max(1, Math.ceil(Math.hypot(ev.clientX - from.x, ev.clientY - from.y) / 3));
        const fresh: Px[] = [];
        for (let k = 1; k <= steps; k++) {
          const x = from.x + ((ev.clientX - from.x) * k) / steps, y = from.y + ((ev.clientY - from.y) * k) / steps;
          for (const h of texelsFor(e, vpRef.current!.rayAt(x, y))) { const key = h.texel.join(","); if (!s.seen.has(key) && s.op.pts.length + fresh.length < 4000) { s.seen.add(key); fresh.push([h.texel[0], h.texel[1]]); } }
        }
        s.last = { x: ev.clientX, y: ev.clientY };
        void ray;
        if (!fresh.length) return;
        s.op.pts.push(...fresh);
        applyLive(e, { ...s.op, pts: fresh } as Op);
        setVer((x) => x + 1);
      },
      onPaintEnd: () => { const e = edRef.current, s = stroke.current; stroke.current = null; if (e && s && (s.op.t === "brush" || s.op.t === "erase")) commit(e, s.op, true); },

  // ---------------------------------------------------------------- derived panels
  const painted = useMemo(() => (ed ? paintedCount(ed.live) : { total: 0, perLayer: {} as Record<string, number> }), [ed, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const itemDisplays = useMemo(() => (ed && entry.kind === "item3d" && comps.current.albedo ? previewDisplays(entry.preview, rasterOf(comps.current.albedo)) : null), [ed, entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const gripRef = useMemo(() => (entry.kind === "item3d" && comps.current.albedo ? gripReference(entry.preview.spec.category, rasterOf(comps.current.albedo)) : null), [entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const grips = useMemo<GripCheck[]>(() => (itemDisplays && gripRef ? gripChecks(itemDisplays, gripRef) : []), [itemDisplays, gripRef]);
  const quality = useMemo(() => (ed && entry.kind === "item3d" && comps.current.albedo ? textureQuality(rasterOf(comps.current.albedo)) : null), [ed, entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const budget = useMemo(() => (ed ? sceneBudget(ed.scene, 1 + (ed.prep.profile ? 0 : ["normal", "roughness", "metallic", "emissive"].filter((c) => !channelUntouched(ed.live, c as PaintChannel)).length)) : []), [ed, ver]); // eslint-disable-line react-hooks/exhaustive-deps

  if (!ed) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Opening the model…</div>;
  const block = paintBlock(ed);
  const activeL = layerOf(ed, activeLayer);
  const swatches = (entry.kind === "creature" ? Object.values(entry.spec.skin.palette) : entry.kind === "item3d" && entry.base.doc.spec ? Object.values(entry.base.doc.spec.palette) : ["#7a5230", "#b07a46", "#d9a066", "#3b2a1a", "#c9ccd6", "#ff8a1f"]).slice(0, 12);
  const sampleOnly = "sample" in ed.entry;
  const tip = hover ? `${ed.scene.parts[hover.hit.part]?.name ?? ""} · ${hover.hit.face} · ${hover.hit.texel[0]}, ${hover.hit.texel[1]}` : null;

  return (
    <main className="ms-ws">
      {/* ---------------------------------------------------------------- left */}
      <section className="ms-col scroll">
        <div className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Models</span><span className="ms-n">{entries.length}</span></div>
          <div className="ms-list">
            {orderEntries(entries).map(({ m, state }) => (
              <button key={m.key} type="button" className={`ms-mrow ${m.key === cur ? "on" : ""} ${state ? "sub" : ""}`} onClick={() => { if (ed.dirty && m.key !== cur && !window.confirm("You have unsaved paint on this model. It is kept as a draft; switch anyway?")) return; setCur(m.key); }}>
                <span className="th3">{m.kind === "item3d" ? <RasterCanvas raster={renderDoc(m.texture.doc)} className="pix" /> : <SI n="cube" />}</span>
                <span className="tx"><b>{m.key}</b><small>{state ? `state · ${state}` : subLine(m)}</small></span>
                {"sample" in m && <span className="cys-tag dim">dev</span>}
              </button>
            ))}
          </div>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">UV texture</span><span className="cys-tag dim">{ed.live.w} × {ed.live.h}</span></div>
          <UvPanel ed={ed} comps={comps.current} channel={activeL?.channel ?? "albedo"} hover={hover?.hit ?? null} ver={ver} />
