/** Item STATE textures (a bow's pull stages, a gun's aiming / reloading) are listed under their item, indented. */
function orderEntries(entries: AnyEntry[]): { m: AnyEntry; state: string | null }[] {
  const stateOf = new Map<string, { parent: string; label: string }>();
  for (const e of entries) if (e.kind === "item3d" && !e.preview.derived && e.preview.spec.name === e.key) for (const st of e.preview.states) if (st.texture !== e.key) stateOf.set(st.texture, { parent: e.key, label: st.label });
  const out: { m: AnyEntry; state: string | null }[] = [];
  for (const e of entries) {
    if (stateOf.has(e.key) && entries.some((x) => x.key === stateOf.get(e.key)!.parent)) continue;
    out.push({ m: e, state: null });
    for (const x of entries) { const s2 = stateOf.get(x.key); if (s2 && s2.parent === e.key) out.push({ m: x, state: s2.label }); }
  }
  return out;
}

