// Cyrus Model Studio LAYER 3: a glTF mesh as the shared layer-1 ModelScene + what layer 3 needs on top of it:
// which material slot each part uses, its UV islands (for the island view and island fills) and an honest UV
// overlap check (parts that share texels cannot be painted independently). Pure + client-safe.
import { parseGltf, type GltfParsed } from "../gltf";
import { sceneFromGltf, triUv, type ModelScene, type Spans } from "../scene";
import { rasterTris, uvIslands } from "../pick";
import type { V2 } from "../math";

export type MeshScene = { scene: ModelScene; gltf: GltfParsed; slots: (string | null)[]; islands: Island[] };
export type Island = { id: number; part: number; tris: number; spans: Spans; texels: number; bbox: [number, number, number, number] };

/** Parse a glb into the shared scene. Part i = the i-th glTF mesh that has UVs (sceneFromGltf's rule). */
export function meshScene(name: string, glb: Uint8Array, tex: { w: number; h: number }): { ok: true; mesh: MeshScene } | { ok: false; error: string } {
  const g = parseGltf(glb);
  if (!g.ok) return { ok: false, error: g.error };
  const scene = sceneFromGltf(name, g.gltf, tex);
  const withUv = g.gltf.meshes.filter((m) => m.uv);
  const slots = withUv.map((m) => (m.material !== null ? g.gltf.materials[m.material]?.name ?? null : null));
  return { ok: true, mesh: { scene, gltf: g.gltf, slots, islands: islandsOf(scene) } };
}

/** UV islands with their texel spans on the scene's texture size, in a stable order (part, then first triangle). */
export function islandsOf(s: ModelScene): Island[] {
  const isl = uvIslands(s);
  const by = new Map<number, number[]>();
  for (let t = 0; t < s.triCount; t++) { const k = isl[t]; let a = by.get(k); if (!a) by.set(k, (a = [])); a.push(t); }
  const out: Island[] = [];
  for (const [id, tris] of [...by].sort((a, b) => s.part[a[1][0]] - s.part[b[1][0]] || a[0] - b[0])) {
    const uvs: [V2, V2, V2][] = tris.map((t) => triUv(s, t));
    const spans = rasterTris(uvs, s.tex.w, s.tex.h);
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity, n = 0;
    for (const [y, a, b] of spans) { x0 = Math.min(x0, a); x1 = Math.max(x1, b); y0 = Math.min(y0, y); y1 = Math.max(y1, y + 1); n += b - a; }
    out.push({ id, part: s.part[tris[0]], tris: tris.length, spans, texels: n, bbox: n ? [x0, y0, x1, y1] : [0, 0, 0, 0] });
  }
  return out;
}

/** Texels claimed by islands of DIFFERENT parts (a fill on one would also colour the other). */
export function uvOverlap(islands: readonly Island[], w: number): { texels: number; parts: [number, number][] } {
  const owner = new Map<number, number>();
  const pairs = new Set<string>();
  let texels = 0;
  for (const is of islands) for (const [y, a, b] of is.spans) for (let x = a; x < b; x++) {
    const k = y * w + x, o = owner.get(k);
    if (o === undefined) owner.set(k, is.part);
    else if (o !== is.part) { texels++; pairs.add(o < is.part ? `${o},${is.part}` : `${is.part},${o}`); }
  }
  return { texels, parts: [...pairs].map((p) => p.split(",").map(Number) as [number, number]) };
}

// sRGB <-> linear for the colour fields (glTF stores linear factors; people pick sRGB colours)
const toLin = (c: number) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const toSrgb = (c: number) => (c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055);
export const linToHex = (v: readonly number[]) => `#${[0, 1, 2].map((i) => Math.round(Math.max(0, Math.min(1, toSrgb(v[i]))) * 255).toString(16).padStart(2, "0")).join("")}`;
export const hexToLin = (h: string): [number, number, number] => [1, 3, 5].map((i) => Math.round(toLin(parseInt(h.slice(i, i + 2), 16) / 255) * 1e5) / 1e5) as [number, number, number];

