// Cyrus Model Studio: who SEES it. Pure + client-safe; the server runs it on every page load and API request.
// Layered on the studios gate (lib/cyrus/studios/access.ts studiosOpen: a Cyrus user AND (preview OR
// cyrus_studios_enabled)), plus its own setting `cyrus_model_studio_enabled` (default OFF). With the setting off only
// preview accounts see Model Studio, the same rule the other studios follow, so customers see nothing until the owner
// flips BOTH settings. The PLAN gate (who may paint) is separate: lib/cyrus/engine-core/asset-gate.ts canModelStudio.
export const MODEL_STUDIO_FLAG = "cyrus_model_studio_enabled";

export const modelStudioOpen = (o: { studiosOpen: boolean; previewUser: boolean; modelFlagOn: boolean }) => o.studiosOpen && (o.previewUser || o.modelFlagOn);
