"use client";
// Client calls of the Model Studio layer-3 API (/api/cyrus/models/v1/projects/:projectId/meshes). The UI talks to
// nothing else (host seam).
import type { MeshEditDoc } from "@/lib/cyrus/modelstudio/retex/doc";
import type { MeshEntry, MeshView } from "@/lib/cyrus/modelstudio/retex/service";
import { ApiError } from "@/components/cyrus/studios/api";

export type { MeshEntry, MeshView };
export type MeshListView = { meshes: (Omit<MeshEntry, "edit"> & { edited: boolean })[]; access: MeshView["access"] };
const BASE = "/api/cyrus/models/v1/projects";

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(BASE + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
  return j as T;
}

export const meshApi = {
  list: (projectId: string) => call<MeshListView>(`/${projectId}/meshes`),
  open: (projectId: string, key: string) => call<MeshView>(`/${projectId}/meshes/${key}`),
  glb: async (projectId: string, key: string): Promise<Uint8Array> => {
    const r = await fetch(`${BASE}/${projectId}/meshes/${key}/glb`, { cache: "no-store" });
    if (!r.ok) { const j = (await r.json().catch(() => ({}))) as Record<string, unknown>; throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "The mesh could not be loaded."), j); }
    return new Uint8Array(await r.arrayBuffer());
  },
  save: (projectId: string, key: string, body: { doc: MeshEditDoc; baseEditId: string | null; expectedHeadId: string | null; message?: string }) =>
    call<{ revisionId: string; seq: number; assetId: string; sha256: string }>(`/${projectId}/meshes/${key}/revisions`, { method: "POST", body: JSON.stringify(body) }),
  rebuild: (projectId: string, key: string, params: Record<string, unknown>) => call<{ jobId: string }>(`/${projectId}/meshes/${key}/rebuild`, { method: "POST", body: JSON.stringify({ params }) }),
};
EOF
