function edFor(m: AnyEntry, headId: string | null, draft?: DraftView | null): Ed {
  const prep = prepare(m);
  let start = prep.start, restored: string | null = null, fromSaved = true;
  if (draft && draft.baseAssetId === prep.baseAssetId && draft.doc.tex.w === prep.start.w) {
    const s = startLayers(draft.doc, prep.start.w, prep.start.h);
    start = s; restored = draft.updatedAt; fromSaved = false;
  }
  const session = sessionInit(start, prep.scene.tex.wrap);
  return { key: m.key, entry: m, prep, scene: prep.scene, session, live: sessionState(session), fromSaved, baseAssetId: prep.baseAssetId, headId: draft && !fromSaved ? draft.baseHeadId : headId, dirty: !!restored, restored, merged: null };
}

function docOf(ed: Ed): ModelDoc {
  const m = ed.entry, w = ed.live.w, h = ed.live.h;
  const ops = appliedOps(ed.session);
  const base: ModelDoc["base"] = m.kind === "creature" ? { type: "rigspec", assetId: m.assetId, sha256: m.sha256, spec: m.spec }
    : m.kind === "item3d" ? { type: "texture", key: m.key, assetId: m.texture.assetId, sha256: sha256Text(canonical(m.texture.doc)) }
    : { type: "gltf", sha256: "0".repeat(64), path: null };
  return {
    v: 1, kind: m.kind === "mesh" ? "mesh" : m.kind, name: m.key, base, tex: { w, h }, layers: encodeLayers(ed.live), symmetry: "none",
    log: { ops: ops.length, folded: ed.session.folded + (ed.fromSaved ? 0 : 1), sha256: sha256Text(canonical(ops)) },
  };
}

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const q = window.matchMedia(`(max-width: ${PERF_BUDGET.mobileBreakpointPx}px)`); const f = () => setN(q.matches); f(); q.addEventListener("change", f); return () => q.removeEventListener("change", f); }, []);
  return n;
}
function useLight() {
  const [l, setL] = useState(false);
  useEffect(() => { const f = () => setL(document.documentElement.getAttribute("data-theme") === "light"); f(); const mo = new MutationObserver(f); mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] }); return () => mo.disconnect(); }, []);
  return l;
}

export function ModelStudio({ mod, initialKey, samples }: { mod: StudioMod; initialKey: string | null; samples: boolean }) {
  return (
    <StudioShell mod={mod} current="Model Studio" studio="model" showModel>
      <Body mod={mod} initialKey={initialKey} samples={samples} />
    </StudioShell>
  );

