"use client";
// Cyrus MODEL STUDIO, layer 3: mesh RETEXTURE + LIGHT EDIT for imported and AI-generated glTF meshes. Anatomy from
// the v3 retexture mockup (/root/agent-notes/cyrus-designs/v3-model-studio/retexture.html, NOT owner-reviewed yet):
// left = source + legal class, material slots, named parts, channel layers; centre = model bar, the shared layer-1
// three.js viewport (part transforms + per-part materials applied live), UV island view, the selected part's
// transform bar; right = export targets (from the adapter asset profiles), what ships, template parameters, checks.
// Phones get the read-only card with Approve / Reject. Every rule lives in lib/cyrus/modelstudio/retex (pure, tested);
// this file is state, wiring and drawing. Writes are plan-gated by the server; the UI only mirrors the decision.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { StudioShell, useToast, type StudioMod } from "@/components/cyrus/studios/StudioShell";
import { SI } from "@/components/cyrus/studios/icons";
import { ModelViewport, webglOk, type CamPreset, type PartMaterial } from "@/components/cyrus/studios/model-viewport";
import { modelApi } from "@/components/cyrus/studios/model-api";
import { ApiError } from "@/components/cyrus/studios/api";
import { pickScene } from "@/lib/cyrus/modelstudio/pick";
import { posedScene } from "@/lib/cyrus/modelstudio/pose";
import { compositeChannel, CHANNEL_LABEL, type PaintChannel } from "@/lib/cyrus/modelstudio/layers";
import { channelImage, uvChecker, viewModes, type ViewMode } from "@/lib/cyrus/modelstudio/channels";
import { LIGHTING_PRESETS, type LightingPreset } from "@/lib/cyrus/modelstudio/look";
import { sceneBudget } from "@/lib/cyrus/modelstudio/budget";
import type { Img, ModelScene } from "@/lib/cyrus/modelstudio/scene";
import { layersOf, SNAP, IDENTITY_XFORM, type MeshEditDoc, type PartXform } from "@/lib/cyrus/modelstudio/retex/doc";
import { meshLog, type MeshOp } from "@/lib/cyrus/modelstudio/retex/ops";
import type { Log } from "@/lib/cyrus/modelstudio/oplog";
import { blockout, paramValue, type ParamDef } from "@/lib/cyrus/modelstudio/retex/params";
import { orphanParts, partOverrides } from "@/lib/cyrus/modelstudio/retex/xform";
import { hexToLin, linToHex, meshScene, uvOverlap, type MeshScene } from "@/lib/cyrus/modelstudio/retex/scene";
import { meshApi, type MeshListView, type MeshView } from "./mesh-api";
import "@/components/cyrus/studios/model-studio.css";
import "./mesh-studio.css";

type Loaded = { projectId: string; view: MeshView; mesh: MeshScene; saved: MeshEditDoc };
const UV_CHANNELS: PaintChannel[] = ["albedo", "roughness", "metallic", "emissive"];
const r3 = (v: number) => Math.round(v * 1000) / 1000;

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const q = window.matchMedia("(max-width: 760px)"); const f = () => setN(q.matches); f(); q.addEventListener("change", f); return () => q.removeEventListener("change", f); }, []);
  return n;
}
function useLight() {
  const [l, setL] = useState(false);
  useEffect(() => { const f = () => setL(document.documentElement.getAttribute("data-theme") === "light"); f(); const mo = new MutationObserver(f); mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] }); return () => mo.disconnect(); }, []);
  return l;
}

export function MeshStudio({ mod, initialKey }: { mod: StudioMod; initialKey: string | null }) {
  return (
    <StudioShell mod={mod} current="Model Studio · Mesh" studio="model" showModel>
      <Body mod={mod} initialKey={initialKey} />
    </StudioShell>
  );
}

function Body({ mod, initialKey }: { mod: StudioMod; initialKey: string | null }) {
  const narrow = useNarrow();
  const [list, setList] = useState<{ projectId: string; list: MeshListView } | null>(null);
  const [key, setKey] = useState<string | null>(null);
  const [loaded, setLoaded] = useState<Loaded | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => {
    (async () => {
      try {
        const m = await modelApi.models(mod.rootId);
        if (!m.project) { setErr("This mod has no Cyrus project yet. Build it once, then open Model Studio."); return; }
        const l = await meshApi.list(m.project.id);
        setList({ projectId: m.project.id, list: l });
        setKey(l.meshes.find((x) => x.key === initialKey)?.key ?? l.meshes[0]?.key ?? null);
      } catch (e) { setErr(e instanceof ApiError ? e.message : "Model Studio could not load this mod."); }
    })();
  }, [mod.rootId, initialKey]);
  const open = useCallback(async (projectId: string, k: string) => {
    setLoaded(null);
    try {
      const view = await meshApi.open(projectId, k);
      const bytes = await meshApi.glb(projectId, k);
      const ms = meshScene(k, bytes, view.doc.tex);
      if (!ms.ok) { setErr(`The mesh could not be read: ${ms.error}`); return; }
      setLoaded({ projectId, view, mesh: ms.mesh, saved: view.doc });
    } catch (e) { setErr(e instanceof ApiError ? e.message : "The mesh could not be opened."); }
  }, []);
  useEffect(() => { if (list && key) void open(list.projectId, key); }, [list, key, open]);

  if (err) return <main className="ms-ws ms-empty"><div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div></main>;
  if (!list) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s meshes…</div>;
  if (!list.list.meshes.length) {
    return (
      <main className="ms-ws ms-empty"><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
        <div className="cys-empty" style={{ maxWidth: 460 }}><SI n="cube" /><p><b>This mod has no meshes to edit yet.</b></p><p className="cys-hint">Layer 3 edits glTF meshes: AI meshes Cyrus made for you, or a template you bring for a game that takes meshes. Minecraft mods use the cuboid editor instead.</p></div>
      </div></main>
    );
  }
  if (!loaded) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Opening the mesh…</div>;
  return narrow
    ? <Narrow loaded={loaded} onSaved={() => list && key && void open(list.projectId, key)} />
    : <Editor loaded={loaded} meshes={list.list.meshes} cur={key!} setCur={setKey} reopen={() => key && void open(list.projectId, key)} />;
}

// ======================================================================================================== editor
function Editor({ loaded, meshes, cur, setCur, reopen }: { loaded: Loaded; meshes: MeshListView["meshes"]; cur: string; setCur: (k: string) => void; reopen: () => void }) {
  const toast = useToast();
  const light = useLight();
  const { view, mesh, projectId } = loaded;
  const canEdit = view.access.edit.ok;
  const jobOnly = view.doc.legal.retention === "job";
  const [log, setLog] = useState<Log<MeshEditDoc, MeshOp>>(() => meshLog.init(loaded.saved));
  useEffect(() => { setLog(meshLog.init(loaded.saved)); }, [loaded.saved]);
  const doc = meshLog.current(log);
  const [selPart, setSelPart] = useState<number | null>(null);
  const [selSlot, setSelSlot] = useState<string | null>(Object.keys(loaded.saved.materials)[0] ?? null);
  const [uvChan, setUvChan] = useState<PaintChannel>("albedo");
  const [selIsland, setSelIsland] = useState<number | null>(null);
  const [mode, setMode] = useState<ViewMode | "uv">("lit");
  const [wire, setWire] = useState(false);
  const [lighting, setLighting] = useState<LightingPreset>("studio");
  const [cam, setCam] = useState<CamPreset>("persp");
  const [snap, setSnap] = useState<{ move: number; rotate: number; scale: number }>({ move: 0.01, rotate: 15, scale: 0.05 });
  const [blockPreview, setBlockPreview] = useState(false);
  const [fillHex, setFillHex] = useState("#e8742a");
  const [fillVal, setFillVal] = useState(0.35);
  const [saving, setSaving] = useState(false);
  const [rebuilding, setRebuilding] = useState(false);
  const [tgt, setTgt] = useState<string>(view.targets[0]?.game ?? "");
  const [webgl] = useState(() => (typeof window === "undefined" ? true : webglOk()));
  const unsaved = meshLog.unsaved(log);

  const commit = useCallback((op: MeshOp) => {
    if (!canEdit) { toast(view.access.edit.ok ? "View only." : (view.access.edit as { reason: string }).reason, true); return false; }
    const r = meshLog.push(log, op);
    if (!r.ok) { toast(r.error, true); return false; }
    setLog(r.log);
    return true;
  }, [canEdit, log, toast, view.access.edit]);

  // ---------------------------------------------------------------- what the viewport shows
  const showBlock = blockPreview && !!doc.params && !!view.mesh.template;
  const scene: ModelScene = useMemo(() => (showBlock ? blockout(view.mesh.template!.id, doc.params!).scene : mesh.scene), [showBlock, doc.params, mesh.scene, view.mesh.template]);
  const layers = useMemo(() => layersOf(doc), [doc]);
  const comps = useMemo(() => Object.fromEntries(UV_CHANNELS.map((c) => [c, compositeChannel(layers, c, c === "albedo" ? { w: doc.tex.w, h: doc.tex.h, px: new Uint8ClampedArray(doc.tex.w * doc.tex.h * 4).fill(255) } : null)])) as Record<PaintChannel, Img>, [layers, doc.tex]);
  const overrides = useMemo(() => partOverrides(doc.parts, scene), [doc.parts, scene]);
  const partMats = useMemo<(PartMaterial | null)[]>(() => scene.parts.map((_, i) => {
    const slot = showBlock ? null : mesh.slots[i];
    const m = slot ? doc.materials[slot] : null;
    const base: PartMaterial = m ? { color: [m.baseColor[0], m.baseColor[1], m.baseColor[2]], metallic: m.metallic, roughness: m.roughness, emissive: [...m.emissive] as [number, number, number] } : { color: [0.55, 0.53, 0.62], metallic: 0, roughness: 0.7, emissive: [0, 0, 0] };
    return i === selPart ? { ...base, emissive: [base.emissive[0] + 0.05, base.emissive[1] + 0.02, base.emissive[2] + 0.16] } : base;
  }), [scene, mesh.slots, doc.materials, selPart, showBlock]);

  const cvRef = useRef<HTMLCanvasElement>(null);
  const vpRef = useRef<ModelViewport | null>(null);
  const [vpReady, setVpReady] = useState(false);
  useEffect(() => {
    if (!cvRef.current || !webgl) return;
    let dead = false;
    ModelViewport.create(cvRef.current, { mobile: false, light }).then((v) => { if (dead) { v.dispose(); return; } vpRef.current = v; setVpReady(true); });
    return () => { dead = true; vpRef.current?.dispose(); vpRef.current = null; setVpReady(false); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl]);
  const shown = useRef<ModelScene | null>(null);
  useEffect(() => {
    const v = vpRef.current;
    if (!v) return;
    const fresh = shown.current !== scene;
    if (fresh) { v.setScene(scene, { albedo: showBlock ? blockout("x", {}).albedo : comps.albedo }, { pixel: false, keepCamera: !!shown.current && shown.current.name === scene.name }); if (!shown.current) v.preset(cam); shown.current = scene; }
    else v.setMaps({ albedo: comps.albedo, ...(doc.layers.some((l) => l.channel === "roughness") ? { roughness: comps.roughness } : {}), ...(doc.layers.some((l) => l.channel === "metallic") ? { metallic: comps.metallic } : {}), ...(doc.layers.some((l) => l.channel === "emissive") ? { emissive: comps.emissive } : {}) });
    v.setPartOverrides(overrides);
    v.setPartMaterials(partMats);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vpReady, scene, comps, overrides, partMats]);
  useEffect(() => { vpRef.current?.setTheme(light); }, [light, vpReady]);
  useEffect(() => { vpRef.current?.setWire(wire); }, [wire, vpReady]);
  useEffect(() => { vpRef.current?.setLighting(lighting); }, [lighting, vpReady]);
  useEffect(() => {
    const v = vpRef.current;
    if (!v) return;
    if (mode === "uv") v.setDisplay({ kind: "image", img: uvChecker(doc.tex.w, doc.tex.h) });
    else if (mode === "lit" || mode === "ao" || mode === "normal" || mode === "mask") v.setDisplay({ kind: "lit" });
    else v.setDisplay({ kind: "image", img: channelImage(layers, mode, mode === "albedo" ? comps.albedo : null) });
  }, [mode, vpReady, layers, comps, doc.tex]);
  // click a part to select it (empty space orbits); the pick runs on the POSED scene, so moved parts pick where they are
  useEffect(() => {
    const v = vpRef.current;
    if (!v) return;
    v.events = {
      onPaintStart: (ray) => { const h = pickScene(posedScene(scene, overrides), ray); setSelPart(h ? h.part : null); if (h && !showBlock && mesh.slots[h.part]) setSelSlot(mesh.slots[h.part]); return false; },
    };
  }, [vpReady, scene, overrides, mesh.slots, showBlock]);

  // ---------------------------------------------------------------- keyboard
  useEffect(() => {
    const on = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (t && (t.tagName === "INPUT" || t.tagName === "SELECT" || t.tagName === "TEXTAREA")) return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); setLog((l) => (e.shiftKey ? meshLog.redo(l) : meshLog.undo(l))); }
      else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "y") { e.preventDefault(); setLog((l) => meshLog.redo(l)); }
      else if (e.key === "Escape") setSelPart(null);
    };
    window.addEventListener("keydown", on);
    return () => window.removeEventListener("keydown", on);
  }, []);

  const save = async () => {
    setSaving(true);
    try {
      const r = await meshApi.save(projectId, cur, { doc, baseEditId: view.mesh.edit?.assetId ?? null, expectedHeadId: view.headRevisionId });
      toast(`Saved as revision ${r.seq}.`);
      reopen();
    } catch (e) { toast(e instanceof ApiError ? e.message : "Saving failed. Nothing was changed.", true); }
    finally { setSaving(false); }
  };
  const rebuild = async () => {
    if (!doc.params) return;
    setRebuilding(true);
    try { const r = await meshApi.rebuild(projectId, cur, doc.params); toast(`Rebuild queued on the mesh worker (job ${r.jobId}). No AI model is called.`); }
    catch (e) { toast(e instanceof ApiError ? e.message : "The rebuild could not be queued.", true); }
    finally { setRebuilding(false); }
  };

  // ---------------------------------------------------------------- derived panels
  const islands = mesh.islands;
  const overlap = useMemo(() => uvOverlap(islands, doc.tex.w), [islands, doc.tex.w]);
  const orphans = orphanParts(doc.parts, mesh.scene);
  const budget = useMemo(() => sceneBudget(mesh.scene, 1 + doc.layers.filter((l, i, a) => a.findIndex((x) => x.channel === l.channel) === i && l.channel !== "albedo").length), [mesh.scene, doc.layers]);
  const modes = viewModes(null);
  const partName = selPart !== null ? scene.parts[selPart]?.name ?? null : null;
  const xf: PartXform = (partName && doc.parts[partName]) || IDENTITY_XFORM;
  const slot = selSlot ? doc.materials[selSlot] : null;
  const target = view.targets.find((t) => t.game === tgt) ?? view.targets[0];
  const exportable = view.targets.filter((t) => t.status === "yes");
  const changed = useMemo(() => changesOf(loaded.saved, doc), [loaded.saved, doc]);
  const readOnly = !canEdit;

  const fillIsland = (isl: number) => {
    const is = islands.find((x) => x.id === isl);
    if (!is || readOnly) return;
    const layerId = `${uvChan}_fill`.slice(0, 24);
    const ops: MeshOp[] = [];
    if (!doc.layers.some((l) => l.id === layerId)) ops.push({ op: "paint", p: { t: "layer.add", id: layerId, name: `${CHANNEL_LABEL[uvChan]} edits`, channel: uvChan } });
    const g = Math.round(fillVal * 255);
    const color: [number, number, number] = uvChan === "albedo" || uvChan === "emissive" ? [parseInt(fillHex.slice(1, 3), 16), parseInt(fillHex.slice(3, 5), 16), parseInt(fillHex.slice(5, 7), 16)] : [g, g, g];
    ops.push({ op: "paint", p: { t: "fill", layer: layerId, color, spans: is.spans } });
    let l = log;
    for (const op of ops) { const r = meshLog.push(l, op); if (!r.ok) { toast(r.error, true); return; } l = r.log; }
    setLog(l);
  };

  return (
    <main className="ms-ws mx-ws">
      {/* ---------------------------------------------------------------- left */}
      <section className="ms-col scroll">
        <div className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Source</span><span className={`cys-tag ${view.legal.tone === "warn" ? "warn" : "dim"}`}>{view.legal.tone === "warn" && <SI n="lock" />}{view.legal.label}</span></div>
          <div className="mx-src">
            {meshes.length > 1 ? (
              <select className="cys-field mx-pick" aria-label="Mesh" value={cur} onChange={(e) => { if (unsaved && !window.confirm("You have unsaved edits on this mesh. Switch anyway?")) return; setCur(e.target.value); }}>{meshes.map((m) => <option key={m.key} value={m.key}>{m.key}</option>)}</select>
            ) : <b className="mx-file">{cur}.glb</b>}
            <small>glTF 2.0 · {Object.keys(doc.materials).length} slots · {mesh.scene.triCount.toLocaleString()} tris{view.mesh.template ? ` · template ${view.mesh.template.id}` : ""}</small>
          </div>
          <div className={`mx-legal ${view.legal.tone}`}>
            <SI n={view.legal.tone === "warn" ? "warn" : "info"} />
            <div><b>{view.legal.summary}</b>{view.legal.lines.map((l) => <span key={l}>{l}</span>)}</div>
          </div>
          <dl className="mx-kv">
            <dt>Retention</dt><dd>{doc.legal.retention === "job" ? "job · ends on close" : "project"}</dd>
            <dt>Fingerprint</dt><dd className="mono">{view.mesh.sha256.slice(0, 4)}…{view.mesh.sha256.slice(-4)}</dd>
            <dt>Library</dt><dd><span className="cys-tag dim">{view.legal.library === "eligible" ? "after checks" : "not shared"}</span></dd>
          </dl>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Material slots</span><span className="ms-n">{Object.keys(doc.materials).length}</span></div>
          <div className="ms-list">
            {Object.entries(doc.materials).map(([k, m]) => (
              <button key={k} type="button" className={`ms-mrow mx-slot ${k === selSlot ? "on" : ""}`} onClick={() => setSelSlot(k)}>
                <span className="sw" style={{ background: linToHex(m.baseColor) }} />
                <span className="tx"><b>{k}</b><small>metal {m.metallic.toFixed(2)} · rough {m.roughness.toFixed(2)}</small></span>
                {loaded.saved.materials[k] && JSON.stringify(loaded.saved.materials[k]) !== JSON.stringify(m) && <span className="cys-dot warn" title="changed" />}
              </button>
            ))}
          </div>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Parts</span><span className="ms-n">{scene.parts.length}</span></div>
          <div className="ms-list">
            {scene.parts.map((p, i) => (
              <button key={`${p.name}-${i}`} type="button" className={`ms-mrow mx-part ${i === selPart ? "on" : ""}`} onClick={() => setSelPart(i)}>
                <span className="tx"><b>{p.name}</b><small>{showBlock ? "block-out" : mesh.slots[i] ?? "no material"}</small></span>
                {doc.parts[p.name] && <span className="cys-tag dim">moved</span>}
              </button>
            ))}
          </div>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Channel layers</span><span className="ms-n">{doc.layers.length}</span></div>
          <div className="ms-layers">
            {doc.layers.length ? [...doc.layers].reverse().map((l) => (
              <div key={l.id} className={`ms-lay ${l.visible ? "" : "off"}`}>
                <button type="button" className="cys-ib sm" disabled={readOnly} aria-label={l.visible ? `Hide ${l.name}` : `Show ${l.name}`} onClick={() => commit({ op: "paint", p: { t: "layer.set", id: l.id, visible: !l.visible } })}><SI n={l.visible ? "eye" : "eyeoff"} /></button>
                <span className="grow"><b>{l.name}</b><small>{CHANNEL_LABEL[l.channel]} · lossless · {Math.round((l.opacity / 255) * 100)}%</small></span>
                <button type="button" className="cys-ib sm" disabled={readOnly} aria-label={`Delete ${l.name}`} onClick={() => commit({ op: "paint", p: { t: "layer.del", id: l.id } })}><SI n="trash" /></button>
              </div>
            )) : <p className="cys-hint" style={{ margin: "0 2px 6px" }}>No channel edits yet. Pick an island in the UV view and fill it.</p>}
            <div className="ms-lay locked"><span className="cys-ib sm"><SI n="lock" /></span><span className="grow"><b>Base mesh</b><small>{view.mesh.source === "meshgen" ? "AI mesh · not editable here" : "your file · never copied"}</small></span></div>
            <p className="cys-hint" style={{ margin: "6px 2px 0" }}>Each channel is its own lossless layer. Packing into a game&apos;s textures happens only at export.</p>
          </div>
        </div>
      </section>

      {/* ---------------------------------------------------------------- centre */}
      <section className="ms-col">
        <div className="cys-panel cys-glass cys-hairline ms-hdr">
          <span className="ic"><SI n="cube" /></span><span className="nm">{cur}</span>
          <span className="ms-pill">retexture</span>
          <span className="ms-pill">{doc.tex.w} × {doc.tex.h}</span>
          {readOnly && <span className="cys-tag warn"><SI n="lock" />view only</span>}
          <span className="sp" />
          <button type="button" className="cys-ib sm" aria-label="Undo (Ctrl Z)" title="Undo (Ctrl Z)" disabled={!meshLog.canUndo(log)} onClick={() => setLog(meshLog.undo(log))}><SI n="undo" /></button>
          <button type="button" className="cys-ib sm" aria-label="Redo (Ctrl Shift Z)" title="Redo (Ctrl Shift Z)" disabled={!meshLog.canRedo(log)} onClick={() => setLog(meshLog.redo(log))}><SI n="redo" /></button>
          <span className="ms-saved"><span className={`cys-dot ${unsaved ? "warn" : "ok"}`} />{unsaved ? `${unsaved} unsaved` : "saved"}</span>
          <button type="button" className="cys-btn sm primary" disabled={readOnly || !unsaved || saving || jobOnly} title={jobOnly ? "Game-derived content is kept for this session only" : undefined} onClick={() => void save()}><SI n="check" />{saving ? "Saving…" : "Save revision"}</button>
        </div>
        {view.mesh.edit?.stale && <div className="ms-note cys-soft"><SI n="info" /><span>{view.mesh.edit.stale}.</span></div>}
        <div className="mx-stage">
          <div className="cys-panel cys-glass ms-vp">
            {webgl ? <canvas ref={cvRef} className="ms-cv orbit" aria-label={`3D view of ${cur}`} /> : <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>This browser has no WebGL, so the 3D view is off.</p></div>}
            <div className="ms-vpbar">
              <span className="cys-float ms-stat"><SI n="cube" /> glTF · <b>PBR</b>{showBlock ? <> · <b className="mx-warn">block-out preview (approximate)</b></> : null}</span>
              <span className="sp" />
              <div className="cys-float ms-chan" aria-label="Overlays"><button type="button" className={wire ? "on" : ""} aria-pressed={wire} onClick={() => setWire((w) => !w)}><SI n="wire" />Wire</button></div>
              <div className="cys-float ms-chan" aria-label="Camera">{(["persp", "front", "side", "top"] as CamPreset[]).map((p) => <button key={p} type="button" className={cam === p ? "on" : ""} onClick={() => { setCam(p); vpRef.current?.preset(p); }}>{p === "persp" ? "Persp" : p[0].toUpperCase() + p.slice(1)}</button>)}</div>
            </div>
            <div className="ms-vpfoot">
              <div className="cys-float ms-chan" aria-label="Channel">
                <span className="lab">Channel</span>
                {modes.map((m) => <button key={m.id} type="button" className={mode === m.id ? "on" : ""} disabled={!m.enabled} title={m.reason ?? m.label} onClick={() => setMode(m.id)}>{m.label}</button>)}
                <button type="button" className={mode === "uv" ? "on" : ""} onClick={() => setMode("uv")}>UV</button>
              </div>
              <span className="sp" />
              <div className="cys-float ms-chan" aria-label="Lighting">{(Object.keys(LIGHTING_PRESETS) as LightingPreset[]).map((p) => <button key={p} type="button" className={lighting === p ? "on" : ""} onClick={() => setLighting(p)}>{LIGHTING_PRESETS[p].label}</button>)}</div>
            </div>
          </div>
          <div className="cys-panel cys-glass mx-uv">
            <div className="cys-ph"><span className="cys-eyebrow">UV islands</span>
              <div className="cys-seg sm cys-soft" role="group" aria-label="UV channel">{UV_CHANNELS.map((c) => <button key={c} type="button" className={uvChan === c ? "on" : ""} onClick={() => setUvChan(c)}>{c === "albedo" ? "Albedo" : c === "roughness" ? "Rough" : c === "metallic" ? "Metal" : "Emit"}</button>)}</div>
            </div>
            <UvIslands mesh={mesh} img={uvChan === "albedo" ? comps.albedo : channelImage(layers, uvChan as Exclude<ViewMode, "lit" | "ao">, null)} sel={selIsland} setSel={setSelIsland} selPart={selPart} />
            <div className="mx-fill">
              {uvChan === "albedo" || uvChan === "emissive"
                ? <label className="mx-color"><input type="color" value={fillHex} onChange={(e) => setFillHex(e.target.value)} aria-label="Fill colour" disabled={readOnly} /><span style={{ background: fillHex }} /></label>
                : <label className="mx-val"><span>{uvChan === "roughness" ? "Rough" : "Metal"}</span><input type="range" min={0} max={1} step={0.01} value={fillVal} disabled={readOnly} onChange={(e) => setFillVal(Number(e.target.value))} aria-label="Fill value" /><b className="mono">{fillVal.toFixed(2)}</b></label>}
              <button type="button" className="cys-btn xs" disabled={readOnly || selIsland === null} onClick={() => selIsland !== null && fillIsland(selIsland)}><SI n="facefill" />Fill island</button>
            </div>
            <p className="cys-hint mx-uvnote">{islands.length} islands{selIsland !== null ? ` · island ${islands.findIndex((x) => x.id === selIsland) + 1} (${scene.parts[islands.find((x) => x.id === selIsland)?.part ?? 0]?.name})` : ""}{overlap.texels ? ` · ${overlap.texels.toLocaleString()} texels shared by parts: a fill there colours both` : ""}</p>
          </div>
        </div>
        <div className="cys-panel cys-glass mx-xbar" aria-label="Part transform">
          <span className="cys-eyebrow">{partName ?? "No part selected"}</span>
          {partName ? (
            <>
              <XField label="Move" unit="m" v={xf.t} step={snap.move || 0.001} disabled={readOnly} onSet={(t) => commit({ op: "xform", part: partName, mode: "set", t, snap: { move: snap.move } })} />
              <XField label="Rotate" unit="°" v={xf.r} step={snap.rotate || 1} disabled={readOnly} onSet={(r) => commit({ op: "xform", part: partName, mode: "set", r, snap: { rotate: snap.rotate } })} />
              <XField label="Scale" unit="×" v={xf.s} step={snap.scale || 0.01} disabled={readOnly} onSet={(s) => commit({ op: "xform", part: partName, mode: "set", s, snap: { scale: snap.scale } })} />
              <label className="me-snap cys-soft mx-snap"><span>Snap</span><select aria-label="Move snap" value={snap.move} onChange={(e) => setSnap({ ...snap, move: Number(e.target.value) })}>{SNAP.move.map((s) => <option key={s} value={s}>{s ? `${s} m` : "off"}</option>)}</select></label>
              <label className="me-snap cys-soft mx-snap"><span>Angle</span><select aria-label="Angle snap" value={snap.rotate} onChange={(e) => setSnap({ ...snap, rotate: Number(e.target.value) })}>{SNAP.rotate.map((s) => <option key={s} value={s}>{s ? `${s}°` : "off"}</option>)}</select></label>
              <button type="button" className="cys-btn xs ghost" disabled={readOnly || !doc.parts[partName]} onClick={() => commit({ op: "reset", part: partName })}>Reset</button>
            </>
          ) : <span className="cys-hint">Click a part in the view or the list to move, turn or scale it. Light edit only: no sculpting.</span>}
        </div>
        <div className="cys-dock cys-glass ms-dock" aria-disabled="true">
          <span className="route"><SI n="edit" />Edit {cur}</span>
          <input disabled placeholder="Asking Cyrus to restyle a mesh is not connected yet (nothing is sent)" aria-label="Change request (not available yet)" />
          <button type="button" className="send" disabled aria-label="Send"><SI n="send" /></button>
        </div>
      </section>

      {/* ---------------------------------------------------------------- right */}
      <section className="ms-col scroll">
        {readOnly && (
          <div className="cys-panel cys-glass mx-lock">
            <span className="ic"><SI n="lock" /></span>
            <div><b>Editing meshes is part of the All models plan</b><p>{(view.access.edit as { reason?: string }).reason ?? ""} You can still open, turn and inspect every mesh.</p>
              <Link className="cys-btn xs primary" href="/dashboard/cyrus/plans">See All models</Link></div>
          </div>
        )}
        <div className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Export to</span><span className="cys-tag dim">{doc.legal.legalClass === "game-derived" ? "delta only" : "full"}</span></div>
          <div className="mx-targets">
            {view.targets.map((t) => (
              <button key={t.game} type="button" className={`mx-tgt ${t.status} ${t.game === target?.game ? "on" : ""}`} onClick={() => setTgt(t.game)}>
                <span className="ab">{t.label.slice(0, 2).toUpperCase()}</span>
                <span className="tx"><b>{t.label}</b><small>{t.status === "yes" ? `${t.delivery ?? ""}` : t.reason}</small></span>
                <span className={`cys-tag ${t.status === "yes" ? "ok" : t.status === "no" ? "bad" : "warn"}`}>{t.status === "yes" ? "ready" : t.status === "no" ? "no" : t.status}</span>
              </button>
            ))}
          </div>
          <div className="mx-expnote"><SI n="info" /><span>{exportable.length ? `${exportable.length} target${exportable.length > 1 ? "s" : ""} can take this mesh.` : "No game Cyrus supports today can take a glTF mesh: Minecraft has no 3D meshes and there is no converter yet. Saved edits stay in the project until a target exists."}</span></div>
          <div className="mx-expbtn"><button type="button" className="cys-btn sm primary" disabled={!exportable.length} style={{ width: "100%" }}><SI n="download" />Export</button></div>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">What ships</span></div>
          <dl className="mx-kv wide">
            <dt>Base mesh</dt><dd>{doc.legal.legalClass === "game-derived" ? "never shipped (players use their own)" : "with your mod (yours)"}</dd>
            <dt>Your edits</dt><dd>{Object.keys(doc.parts).length} parts moved · {Object.entries(doc.materials).filter(([k, m]) => JSON.stringify(loaded.saved.materials[k]) !== JSON.stringify(m) || JSON.stringify(view.doc.materials[k]) !== JSON.stringify(m)).length} slots changed · {doc.layers.length} layers</dd>
            <dt>Packing</dt><dd>{target?.packing ? target.packing.slots.map((s) => `${s.file} (${s.roles.join("+")})`).join(", ") || "nothing" : "at export, per target (none ready)"}</dd>
          </dl>
        </div>
        {view.mesh.template && (
          <div className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Parameters · {view.mesh.template.label}</span>
              <button type="button" className={`cys-fchip ${blockPreview ? "on" : ""}`} aria-pressed={blockPreview} disabled={!doc.params} onClick={() => setBlockPreview((b) => !b)}>Block-out</button></div>
            <div className="mx-params">
              {view.params.map((d) => <Param key={d.key} d={d} v={paramValue(doc.params ?? view.doc.base.template?.spec ?? {}, d)} disabled={readOnly || !view.doc.base.template} onSet={(value) => { if (commit({ op: "param", key: d.key, value })) setBlockPreview(true); }} />)}
              {!view.doc.base.template && <p className="cys-hint">The spec this mesh was built from is not on record, so its parameters cannot be changed.</p>}
              <p className="cys-hint">The block-out is an approximate preview drawn here. <b>Rebuild</b> runs the same Blender template on the mesh worker: no AI model call, no tokens.</p>
              <button type="button" className="cys-btn sm" disabled={readOnly || !doc.params || rebuilding} onClick={() => void rebuild()}><SI n="restore" />{rebuilding ? "Queuing…" : "Rebuild mesh"}</button>
            </div>
          </div>
        )}
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">{slot ? `Material · ${selSlot}` : "Material"}</span></div>
          {slot && selSlot ? (
            <div className="mx-mat">
              <label><span>Base colour</span><input type="color" value={linToHex(slot.baseColor)} disabled={readOnly} aria-label="Base colour" onChange={(e) => { const [r, g, b] = hexToLin(e.target.value); commit({ op: "material", slot: selSlot, props: { baseColor: [r, g, b, slot.baseColor[3]] } }); }} /><b className="mono">{linToHex(slot.baseColor)}</b></label>
              <label><span>Metallic</span><input type="range" min={0} max={1} step={0.01} value={slot.metallic} disabled={readOnly} aria-label="Metallic" onChange={(e) => commit({ op: "material", slot: selSlot, props: { metallic: Number(e.target.value) } })} /><b className="mono">{slot.metallic.toFixed(2)}</b></label>
              <label><span>Roughness</span><input type="range" min={0} max={1} step={0.01} value={slot.roughness} disabled={readOnly} aria-label="Roughness" onChange={(e) => commit({ op: "material", slot: selSlot, props: { roughness: Number(e.target.value) } })} /><b className="mono">{slot.roughness.toFixed(2)}</b></label>
              <label><span>Emissive</span><input type="color" value={linToHex(slot.emissive)} disabled={readOnly} aria-label="Emissive colour" onChange={(e) => commit({ op: "material", slot: selSlot, props: { emissive: hexToLin(e.target.value) } })} /><b className="mono">{linToHex(slot.emissive)}</b></label>
            </div>
          ) : <p className="cys-hint" style={{ margin: "0 14px 12px" }}>Pick a material slot.</p>}
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Checks</span></div>
          <ul className="mx-checks">
            {budget.filter((b) => b.id !== "cubes").map((b) => <li key={b.id} className={b.status}><span className={`cys-dot ${b.status === "pass" ? "ok" : b.status}`} />{b.message}<b className="mono">{b.value.toLocaleString()} / {b.limit.toLocaleString()}</b></li>)}
            <li className={overlap.texels ? "warn" : "pass"}><span className={`cys-dot ${overlap.texels ? "warn" : "ok"}`} />UV islands shared by parts<b className="mono">{overlap.texels ? `${overlap.parts.length} pairs` : "none"}</b></li>
            <li className={orphans.length ? "warn" : "pass"}><span className={`cys-dot ${orphans.length ? "warn" : "ok"}`} />Part edits that match no part<b className="mono">{orphans.length ? orphans.join(", ") : "none"}</b></li>
            <li className="not_run"><span className="cys-dot" />Checked in a real game client<b className="mono">not run</b></li>
          </ul>
          {changed.length > 0 && <p className="cys-hint" style={{ margin: "0 14px 12px" }}>Unsaved: {changed.slice(0, 4).join(" · ")}{changed.length > 4 ? ` and ${changed.length - 4} more` : ""}</p>}
        </div>
      </section>
    </main>
  );
}

// ------------------------------------------------------------------------------------------------ small parts
function XField({ label, unit, v, step, disabled, onSet }: { label: string; unit: string; v: readonly number[]; step: number; disabled: boolean; onSet: (v: [number, number, number]) => void }) {
  const [txt, setTxt] = useState(v.map((x) => String(r3(x))));
  useEffect(() => { setTxt(v.map((x) => String(r3(x)))); }, [v]);
  const fire = (i: number, s: string) => { const n = Number(s); if (!Number.isFinite(n)) { setTxt(v.map((x) => String(r3(x)))); return; } if (n === v[i]) return; const out = [...v] as [number, number, number]; out[i] = n; onSet(out); };
  return (
    <div className="mx-xf" role="group" aria-label={label}>
      <span className="lab">{label}</span>
      {["X", "Y", "Z"].map((a, i) => (
        <label key={a} className={`ax ${a.toLowerCase()}`}><i>{a}</i>
          <input type="number" step={step} value={txt[i]} disabled={disabled} aria-label={`${label} ${a}`} onChange={(e) => { const t = [...txt]; t[i] = e.target.value; setTxt(t); }} onBlur={(e) => fire(i, e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") fire(i, (e.target as HTMLInputElement).value); }} />
        </label>
      ))}
      <span className="u">{unit}</span>
    </div>
  );
}

function Param({ d, v, disabled, onSet }: { d: ParamDef; v: unknown; disabled: boolean; onSet: (v: number | string | boolean) => void }) {
  const [local, setLocal] = useState(v);
  useEffect(() => { setLocal(v); }, [v]);
  if (d.kind === "enum") return <label className="mx-param"><span>{d.label}</span><select className="cys-field" value={String(local)} disabled={disabled} aria-label={d.label} onChange={(e) => onSet(e.target.value)}>{d.options.map((o) => <option key={o} value={o}>{o.replace(/_/g, " ")}</option>)}</select></label>;
  if (d.kind === "bool") return <label className="mx-param"><span>{d.label}</span><input type="checkbox" checked={!!local} disabled={disabled} aria-label={d.label} onChange={(e) => onSet(e.target.checked)} /></label>;
  const step = d.kind === "int" ? 1 : d.step;
  return (
    <label className="mx-param"><span>{d.label}</span>
      <input type="range" min={d.min} max={d.max} step={step} value={Number(local)} disabled={disabled} aria-label={d.label}
        onChange={(e) => setLocal(Number(e.target.value))} onPointerUp={(e) => onSet(Number((e.target as HTMLInputElement).value))} onKeyUp={(e) => onSet(Number((e.target as HTMLInputElement).value))} />
      <b className="mono">{d.kind === "int" ? Number(local) : `${Number(local).toFixed(2)}${d.kind === "range" && d.unit ? ` ${d.unit}` : ""}`}</b>
    </label>
  );
}

function UvIslands({ mesh, img, sel, setSel, selPart }: { mesh: MeshScene; img: Img; sel: number | null; setSel: (n: number | null) => void; selPart: number | null }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const N = 256;
  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    cv.width = N; cv.height = N;
    const c = cv.getContext("2d")!;
    // the channel composite, scaled down
    const tmp = document.createElement("canvas"); tmp.width = img.w; tmp.height = img.h;
    const id = new ImageData(new Uint8ClampedArray(img.px), img.w, img.h); tmp.getContext("2d")!.putImageData(id, 0, 0);
    c.clearRect(0, 0, N, N); c.imageSmoothingEnabled = true; c.globalAlpha = 0.9; c.drawImage(tmp, 0, 0, N, N); c.globalAlpha = 1;
    const css = getComputedStyle(cv), line = css.getPropertyValue("--uv-line") || "rgba(167,139,250,.4)", hi = css.getPropertyValue("--uv-hi") || "#a78bfa";
    const k = N / mesh.scene.tex.w;
    for (const is of mesh.islands) {
      const on = is.id === sel, part = is.part === selPart;
      c.fillStyle = on ? "rgba(124,77,255,.35)" : part ? "rgba(124,77,255,.16)" : "rgba(124,77,255,.06)";
      for (const [y, a, b] of is.spans) if (y % Math.max(1, Math.round(1 / k)) === 0) c.fillRect(a * k, y * k, Math.max(1, (b - a) * k), Math.max(1, k));
      const [x0, y0, x1, y1] = is.bbox;
      c.strokeStyle = on ? hi : line; c.lineWidth = on ? 2 : 1;
      c.strokeRect(x0 * k + 0.5, y0 * k + 0.5, Math.max(1, (x1 - x0) * k - 1), Math.max(1, (y1 - y0) * k - 1));
    }
  }, [mesh, img, sel, selPart]);
  return (
    <div className="ms-uvbox mx-uvbox">
      <canvas ref={ref} aria-label="UV island view" role="img" onClick={(e) => {
        const r = (e.target as HTMLCanvasElement).getBoundingClientRect();
        const x = Math.floor(((e.clientX - r.left) / r.width) * mesh.scene.tex.w), y = Math.floor(((e.clientY - r.top) / r.height) * mesh.scene.tex.h);
        const hit = mesh.islands.find((is) => is.spans.some(([yy, a, b]) => yy === y && x >= a && x < b));
        setSel(hit ? hit.id : null);
      }} />
    </div>
  );
}

/** People-facing list of what changed between two docs (the phone's "What changed", the Checks hint). */
function changesOf(a: MeshEditDoc, b: MeshEditDoc): string[] {
  const out: string[] = [];
  for (const k of new Set([...Object.keys(a.parts), ...Object.keys(b.parts)])) if (JSON.stringify(a.parts[k]) !== JSON.stringify(b.parts[k])) out.push(`${k} ${b.parts[k] ? "moved" : "reset"}`);
  for (const k of Object.keys(b.materials)) if (JSON.stringify(a.materials[k]) !== JSON.stringify(b.materials[k])) out.push(`${k} material`);
  const la = new Map(a.layers.map((l) => [l.id, l])), lb = new Map(b.layers.map((l) => [l.id, l]));
  for (const [id, l] of lb) if (!la.has(id)) out.push(`${CHANNEL_LABEL[l.channel].toLowerCase()} layer added`); else if (JSON.stringify(la.get(id)) !== JSON.stringify(l)) out.push(`${l.name} painted`);
  for (const id of la.keys()) if (!lb.has(id)) out.push("a layer removed");
  if (JSON.stringify(a.params) !== JSON.stringify(b.params)) out.push("template parameters");
  return out;
}

// ======================================================================================================== phone
function Narrow({ loaded, onSaved }: { loaded: Loaded; onSaved: () => void }) {
  const toast = useToast();
  const light = useLight();
  const { view, mesh, projectId } = loaded;
  const doc = loaded.saved;
  const ref = useRef<HTMLCanvasElement>(null);
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    const cv = ref.current;
    if (!cv || !webglOk()) return;
    let dead = false, vp: ModelViewport | null = null;
    ModelViewport.create(cv, { mobile: true, light }).then((v) => {
      if (dead) { v.dispose(); return; }
      vp = v; v.readOnly = true;
      v.setScene(mesh.scene, { albedo: { w: 1, h: 1, px: new Uint8ClampedArray([255, 255, 255, 255]) } }, { pixel: false });
      v.setPartOverrides(partOverrides(doc.parts, mesh.scene));
      v.setPartMaterials(mesh.scene.parts.map((_, i) => { const s = mesh.slots[i]; const m = s ? doc.materials[s] : null; return m ? { color: [m.baseColor[0], m.baseColor[1], m.baseColor[2]], metallic: m.metallic, roughness: m.roughness, emissive: [...m.emissive] as [number, number, number] } : null; }));
      v.preset("persp");
    });
    return () => { dead = true; vp?.dispose(); };
  }, [mesh, doc, light]);
  const edits = Object.keys(doc.parts).length + doc.layers.length;
  const canApprove = view.access.edit.ok && doc.legal.retention !== "job";
  return (
    <main className="ms-narrow" aria-label="Mesh review">
      <div className="cys-glass ms-ncard">
        <div className="ms-nh"><span className="ic"><SI n="cube" /></span><div><h1>{doc.name}</h1><small>mesh · retexture{view.revisionSeq ? ` · revision ${view.revisionSeq}` : ""}</small></div>
          <span className={`cys-tag ${view.legal.tone === "warn" ? "warn" : "dim"}`}>{view.legal.label}</span></div>
        <div className="ms-nview">
          <span className="cys-tag dim ms-nro"><SI n="eye" />read only</span>
          <canvas ref={ref} aria-label={`Turntable of ${doc.name}`} role="img" />
          <small className="cys-hint ms-nhint">Drag to turn</small>
        </div>
        <div className="ms-nsec"><span className="cys-eyebrow">What changed</span>
          {edits ? <ul className="ms-nlist">{Object.keys(doc.parts).slice(0, 4).map((p) => <li key={p}><code>part</code>{p} moved</li>)}{doc.layers.slice(0, 3).map((l) => <li key={l.id}><code>layer</code>{l.name} ({CHANNEL_LABEL[l.channel]})</li>)}</ul> : <p className="cys-hint">No saved edits on this mesh yet.</p>}
        </div>
        <div className="ms-nsec"><span className="cys-eyebrow">What ships</span><p className="cys-hint">{doc.legal.legalClass === "game-derived" ? "Only your changes. The base file is never stored or shared." : "The mesh with your edits, once a game target can take it. None can today (Minecraft has no 3D meshes)."}</p></div>
        <div className="ms-nsec mx-nnote"><SI n="info" /><span>{view.legal.summary} Not checked in a real game client. Editing needs a larger screen.</span></div>
        <div className="ms-nact">
          <button type="button" className="cys-btn" disabled={!edits} onClick={() => toast("Kept the saved version.")}>Reject</button>
          <button type="button" className="cys-btn primary" disabled={!canApprove || saving || !edits} onClick={async () => { setSaving(true); try { await meshApi.save(projectId, doc.name, { doc, baseEditId: view.mesh.edit?.assetId ?? null, expectedHeadId: view.headRevisionId, message: `Approved ${doc.name} on a phone` }); toast("Approved."); onSaved(); } catch (e) { toast(e instanceof ApiError ? e.message : "Approving failed.", true); } finally { setSaving(false); } }}><SI n="check" />{view.access.edit.ok ? "Approve revision" : "View only"}</button>
        </div>
      </div>
    </main>
  );
}

