/* Cyrus Model Studio layer 3: mesh retexture + light edit. Built on the layer-1 ms-* classes (model-studio.css) and
   the studios' tokens (studios.css .cys). One accent (violet); amber = warn (game-derived, not ready), red = no,
   green = ready. Light theme follows html[data-theme=light] through the tokens. Every class here is mx-*. */
.cys .mx-ws { grid-template-columns: 250px minmax(0, 1fr) 320px; }
.cys .mx-src { padding: 0 14px 10px; display: flex; flex-direction: column; gap: 4px; }
.cys .mx-src small { font: 400 10.5px/1.4 var(--mono); color: var(--muted); }
.cys .mx-file { font: 500 12.5px/1.2 var(--mono); color: var(--ink); }
.cys .mx-pick { height: 30px; font: 500 12px/1 var(--mono); }
.cys .mx-legal { margin: 0 12px 10px; display: flex; gap: 9px; padding: 10px 11px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); font-size: 12px; line-height: 1.45; color: var(--ink-2); }
.cys .mx-legal > svg { flex: none; margin-top: 2px; color: var(--accent-ink); }
.cys .mx-legal b { display: block; color: var(--ink); font-weight: 600; margin-bottom: 2px; }
.cys .mx-legal span { display: block; }
.cys .mx-legal.warn { border-color: color-mix(in srgb, var(--warn) 45%, transparent); background: var(--warn-soft); }
.cys .mx-legal.warn > svg { color: var(--warn); }
.cys .mx-kv { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; margin: 0; padding: 0 14px 12px; font-size: 11.5px; }
.cys .mx-kv dt { color: var(--muted); }
.cys .mx-kv dd { margin: 0; text-align: right; color: var(--ink-2); font: 500 11px/1.3 var(--mono); }
.cys .mx-kv.wide dd { text-align: right; font: 400 11px/1.35 var(--mono); }
.cys .mx-slot .sw { width: 14px; height: 14px; border-radius: 4px; flex: none; border: 1px solid var(--line-2); }
.cys .mx-stage { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 236px; gap: 12px; }
.cys .mx-uv { display: flex; flex-direction: column; min-height: 0; overflow-y: auto; }
.cys .mx-uv .cys-ph { flex-wrap: wrap; gap: 6px; }
.cys .mx-uvbox { margin: 0 12px; }
.cys .mx-uvbox canvas { cursor: pointer; image-rendering: auto; }
.cys .mx-fill { display: flex; align-items: center; gap: 8px; padding: 10px 12px 4px; }
.cys .mx-fill .cys-btn { margin-left: auto; }
.cys .mx-color { position: relative; width: 28px; height: 28px; flex: none; }
.cys .mx-color input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.cys .mx-color span { display: block; width: 100%; height: 100%; border-radius: 8px; border: 1px solid var(--line-2); }
.cys .mx-val { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); flex: 1; min-width: 0; }
.cys .mx-val input { flex: 1; min-width: 0; accent-color: var(--accent-solid); }
.cys .mx-val b { font: 500 10.5px/1 var(--mono); color: var(--ink); }
.cys .mx-uvnote { margin: 6px 12px 12px; font-size: 11px; }
.cys .mx-xbar { display: flex; align-items: center; gap: 12px; padding: 8px 12px; flex: none; flex-wrap: wrap; min-height: 46px; }
.cys .mx-xbar .cys-eyebrow { min-width: 86px; color: var(--accent-ink); }
.cys .mx-xf { display: inline-flex; align-items: center; gap: 4px; }
.cys .mx-xf .lab { font-size: 11px; color: var(--muted); margin-right: 2px; }
.cys .mx-xf .u { font: 500 10.5px/1 var(--mono); color: var(--faint); }
.cys .mx-xf .ax { display: inline-flex; align-items: center; height: 26px; border-radius: 7px; border: 1px solid var(--line-2); background: var(--well); overflow: hidden; }
.cys .mx-xf .ax i { font: 600 9.5px/1 var(--mono); font-style: normal; padding: 0 5px; height: 100%; display: grid; place-items: center; border-right: 1px solid var(--line); }
.cys .mx-xf .ax.x i { color: #d0605e; } .cys .mx-xf .ax.y i { color: #5fae6e; } .cys .mx-xf .ax.z i { color: #5f86d6; }
.cys .mx-xf .ax input { width: 54px; height: 100%; border: 0; background: transparent; color: var(--ink); font: 500 11px/1 var(--mono); padding: 0 5px; outline: none; -moz-appearance: textfield; }
.cys .mx-xf .ax input::-webkit-inner-spin-button { display: none; }
.cys .mx-xf .ax:focus-within { border-color: var(--accent-line); }
.cys .mx-snap { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 4px 0 9px; border-radius: 9px; font-size: 11px; color: var(--muted); }
.cys .mx-snap select { border: 0; background: transparent; font: 500 11px/1 var(--mono); color: var(--ink); outline: none; }
.cys .mx-snap select option { background: var(--solid); }
.cys .mx-lock { display: flex; gap: 12px; padding: 14px; flex: none; }
.cys .mx-lock .ic { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; flex: none; color: var(--accent-ink); border: 1px solid var(--line-2); background: var(--accent-soft); }
.cys .mx-lock b { display: block; color: var(--ink); font-size: 13px; margin-bottom: 4px; }
.cys .mx-lock p { margin: 0 0 10px; font-size: 12px; line-height: 1.45; color: var(--muted); }
.cys .mx-targets { padding: 0 10px 8px; display: flex; flex-direction: column; gap: 6px; }
.cys .mx-tgt { display: flex; align-items: center; gap: 10px; padding: 8px 9px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); width: 100%; text-align: left; color: var(--ink-2); }
.cys .mx-tgt.on { border-color: var(--accent-line); box-shadow: inset 0 0 0 1px var(--accent-line); }
.cys .mx-tgt .ab { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; flex: none; font: 600 10px/1 var(--mono); color: var(--muted); border: 1px solid var(--line-2); }
.cys .mx-tgt .tx { flex: 1; min-width: 0; }
.cys .mx-tgt .tx b { display: block; font-size: 12.5px; color: var(--ink); font-weight: 600; }
.cys .mx-tgt .tx small { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: 10.5px; line-height: 1.35; color: var(--muted); margin-top: 2px; }
.cys .mx-tgt.no .tx b, .cys .mx-tgt.later .tx b { color: var(--ink-2); }
.cys .mx-expnote { display: flex; gap: 8px; margin: 0 12px 10px; padding: 9px 10px; border-radius: var(--r); border: 1px dashed var(--line-2); font-size: 11.5px; line-height: 1.45; color: var(--muted); }
.cys .mx-expnote > svg { flex: none; margin-top: 2px; }
.cys .mx-expbtn { padding: 0 12px 12px; }
.cys .mx-params { padding: 0 14px 12px; display: flex; flex-direction: column; gap: 8px; }
.cys .mx-param { display: grid; grid-template-columns: 92px minmax(0, 1fr) auto; align-items: center; gap: 8px; font-size: 11.5px; color: var(--muted); }
.cys .mx-param input[type=range] { width: 100%; accent-color: var(--accent-solid); }
.cys .mx-param .cys-field { height: 26px; font-size: 11.5px; grid-column: 2 / 4; }
.cys .mx-param b { font: 500 10.5px/1 var(--mono); color: var(--ink); min-width: 54px; text-align: right; }
.cys .mx-params .cys-btn { align-self: flex-start; }
.cys .mx-mat { padding: 0 14px 12px; display: flex; flex-direction: column; gap: 8px; }
.cys .mx-mat label { display: grid; grid-template-columns: 78px minmax(0, 1fr) auto; align-items: center; gap: 8px; font-size: 11.5px; color: var(--muted); }
.cys .mx-mat input[type=range] { width: 100%; accent-color: var(--accent-solid); }
.cys .mx-mat input[type=color] { width: 100%; height: 26px; border: 1px solid var(--line-2); border-radius: 7px; background: var(--well); padding: 2px; cursor: pointer; }
.cys .mx-mat b { font: 500 10.5px/1 var(--mono); color: var(--ink); min-width: 58px; text-align: right; }
.cys .mx-checks { list-style: none; margin: 0; padding: 0 14px 12px; display: flex; flex-direction: column; gap: 7px; font-size: 11.5px; color: var(--ink-2); }
.cys .mx-checks li { display: flex; align-items: center; gap: 8px; }
.cys .mx-checks li b { margin-left: auto; font: 500 10.5px/1.2 var(--mono); color: var(--muted); text-align: right; max-width: 50%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .mx-checks li.not_run { color: var(--muted); }
.cys .mx-warn { color: var(--warn); }
.cys .mx-nnote { flex-direction: row; align-items: flex-start; font-size: 12.5px; color: var(--muted); line-height: 1.45; }
.cys .mx-nnote > svg { flex: none; margin-top: 2px; }
@container (max-width: 1240px) { .cys .mx-ws { grid-template-columns: 224px minmax(0, 1fr) 296px; } .cys .mx-stage { grid-template-columns: minmax(0, 1fr) 200px; } .cys .mx-snap > span { display: none; } }

