import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { MeshStudio } from "@/components/cyrus/modelstudio/retex/MeshStudio";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Model Studio · Mesh · Cyrus");
}

/**
