// Cyrus Model Studio LAYER 3 (feature/cyrus-r30-modelstudio): mesh retexture + light edit for glTF meshes. The doc,
// the op log (the same one the layer-2 editor uses), snapping and light-edit limits, per-channel lossless layers and
// island fills, template parameter sliders (validated by the meshgen schema) + block-out, the export-target picker
// from the adapter asset profiles (Minecraft = no for 3D), the legal-class rules, and the server: plan gate (All
// models, fail closed), stale checks, retention, rebuild without a model call, drafts. Real meshgen glbs as fixtures.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { checkMeshEditDoc, IDENTITY_XFORM, layersOf, newMeshEditDoc, type MeshEditDoc } from "../lib/cyrus/modelstudio/retex/doc";
import { applyMeshOp, meshLog } from "../lib/cyrus/modelstudio/retex/ops";
import { blockout, blockoutBoxes, paramsFor, paramValue, setParam } from "../lib/cyrus/modelstudio/retex/params";
import { canTakeMesh, exportTargets, packPlan } from "../lib/cyrus/modelstudio/retex/export";
import { legalBadge, retentionAllowsSave } from "../lib/cyrus/modelstudio/retex/legal";
import { partCentres, partMatrix, partOverrides, orphanParts } from "../lib/cyrus/modelstudio/retex/xform";
import { hexToLin, linToHex, meshScene, uvOverlap } from "../lib/cyrus/modelstudio/retex/scene";
import { getMeshDraft, listMeshes, meshBytes, openMesh, putMeshDraft, rebuildMesh, resolveMeshes, saveMeshEdit, GLB_MIME, type MeshServiceDeps } from "../lib/cyrus/modelstudio/retex/service";
import { handleMesh, handleMeshGlb, type MeshApiDeps } from "../lib/cyrus/modelstudio/retex/http";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { apply4 } from "../lib/cyrus/modelstudio/math";
import { getTemplate } from "../lib/cyrus/meshgen/templates";
import type { AssetRow, ProjectRow, RevRow } from "../lib/cyrus/studios/service";

const ROOT = path.resolve(__dirname, "..");
const glbOf = (n: string) => new Uint8Array(fs.readFileSync(path.join(ROOT, `test/fixtures/cyrus-meshes/${n}.glb`)));
const sha = (b: Uint8Array) => createHash("sha256").update(b).digest("hex");
const RIFLE = glbOf("rifle_ak"), CRATE = glbOf("crate_scifi");
const near = (a: number[], b: number[], e = 1e-9) => a.every((v, i) => Math.abs(v - b[i]) < e);
const ok = <T,>(r: { ok: true; doc: T } | { ok: false; error: string }) => { if (!r.ok) throw new Error(r.error); return r.doc; };

function docFor(o: Partial<MeshEditDoc> = {}): MeshEditDoc {
  const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
  if (!ms.ok) throw new Error(ms.error);
  const materials = Object.fromEntries(ms.mesh.gltf.materials.map((m) => [m.name, { baseColor: m.baseColor, metallic: m.metallic, roughness: m.roughness, emissive: m.emissive }]));
  const tpl = getTemplate("rifle")!;
  return { ...newMeshEditDoc({ name: "rifle_ak", tex: { w: 512, h: 512 }, materials, base: { sha256: sha(RIFLE), source: "meshgen", assetId: "as1", template: { id: "rifle", version: tpl.version, spec: tpl.example } }, legal: { legalClass: "ai-generated-for-user", retention: "project", game: null, derivedFrom: [] } }), ...o };
}

describe("layer 3: the real meshgen glb as the shared scene", () => {
  it("named parts, material slots per part, UV islands, an honest overlap check", () => {
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    assert.ok(ms.ok);
    if (!ms.ok) return;
    assert.deepEqual(ms.mesh.scene.parts.map((p) => p.name), ["barrel", "grip", "handguard", "magazine", "receiver", "sights", "stock"]);
    assert.equal(ms.mesh.gltf.materials.length, 5);
    assert.ok(ms.mesh.slots.every((s) => s && s.startsWith("mat_")), "every part has its material slot");
    assert.ok(ms.mesh.islands.length >= ms.mesh.scene.parts.length);
    assert.ok(ms.mesh.islands.every((i) => i.texels > 0 || i.tris > 0));
    const ov = uvOverlap(ms.mesh.islands, 512);
    assert.ok(ov.texels >= 0 && Array.isArray(ov.parts), "overlap is measured, not assumed");
    assert.equal(linToHex(hexToLin("#e8742a")), "#e8742a", "sRGB <-> linear round trip for the colour fields");
  });
});

describe("layer 3: doc + ops + the one op log", () => {
  it("validates: game-derived must be job-only and name its base; params only on template meshes", () => {
    assert.ok(checkMeshEditDoc(docFor()).ok);
    assert.equal(checkMeshEditDoc({ ...docFor(), legal: { legalClass: "game-derived", retention: "project", game: "fivem", derivedFrom: [sha(RIFLE)] } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), legal: { legalClass: "game-derived", retention: "job", game: "fivem", derivedFrom: [] } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), base: { ...docFor().base, template: null }, params: { barrel: { length: 0.5 } } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), extra: 1 }).ok, false, "strict");
  });
  it("part transforms snap, stay inside the light-edit limits, and an identity transform removes the entry", () => {
    const d0 = docFor();
    const d1 = ok(applyMeshOp(d0, { op: "xform", part: "barrel", mode: "set", t: [0.1234, 0, 0], snap: { move: 0.05 } }));
    assert.deepEqual(d1.parts.barrel.t, [0.1, 0, 0]);
    const d2 = ok(applyMeshOp(d1, { op: "xform", part: "barrel", mode: "add", r: [0, 0, 20], snap: { rotate: 15 } }));
    assert.deepEqual(d2.parts.barrel.r, [0, 0, 15]);
    assert.equal(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", t: [50, 0, 0] }).ok, false, "10 m light-edit limit");
    assert.equal(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", s: [0, 1, 1] }).ok, false);
    assert.equal(applyMeshOp(d2, { op: "xform", part: "nope", mode: "set", t: [0, 0, 0] }, { parts: ["barrel"], slots: [] }).ok, false);
    const back = ok(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", t: [0, 0, 0], r: [0, 0, 0] }));
    assert.equal(back.parts.barrel, undefined);
    assert.equal(applyMeshOp(back, { op: "reset", part: "barrel" }).ok, false);
  });
  it("materials are validated; channel layers are lossless and per channel; island fill writes only that island", () => {
    const d0 = docFor();
    const slot = Object.keys(d0.materials)[0];
    assert.equal(applyMeshOp(d0, { op: "material", slot, props: { roughness: 2 } }).ok, false);
    const d1 = ok(applyMeshOp(d0, { op: "material", slot, props: { roughness: 0.2, metallic: 0.9 } }));
    assert.equal(d1.materials[slot].roughness, 0.2);
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    const is = ms.mesh.islands.find((i) => i.texels > 20)!;
    const d2 = ok(applyMeshOp(d1, { op: "paint", p: { t: "layer.add", id: "roughness_fill", name: "Roughness edits", channel: "roughness" } }));
    const d3 = ok(applyMeshOp(d2, { op: "paint", p: { t: "fill", layer: "roughness_fill", color: [64, 64, 64], spans: is.spans } }));
    const L = layersOf(d3).layers[0];
    let n = 0; for (let i = 3; i < L.px.length; i += 4) if (L.px[i]) n++;
    assert.equal(n, is.texels, "exactly the island's texels");
    assert.equal(d3.layers.filter((l) => l.channel === "roughness").length, 1);
    assert.ok(checkMeshEditDoc(d3).ok, "a painted doc is still a valid doc (lossless rle)");
  });
  it("the op log: undo/redo O(1), replay from the base gives the same doc byte for byte", () => {
    let l = meshLog.init(docFor());
    for (const op of [
      { op: "xform", part: "stock", mode: "set", t: [-0.05, 0, 0] },
      { op: "material", slot: Object.keys(docFor().materials)[1], props: { metallic: 0.5 } },
      { op: "param", key: "barrel.length", value: 0.55 },
      { op: "xform", part: "magazine", mode: "add", r: [0, 0, 10] },
    ] as const) { const r = meshLog.push(l, op as never); assert.ok(r.ok, !r.ok ? r.error : ""); l = r.log; }
    assert.equal(meshLog.unsaved(l), 4);
    const cur = meshLog.current(l);
    assert.deepEqual(meshLog.replay(l.base, l.entries), cur);
    const u = meshLog.undo(meshLog.undo(l));
    assert.equal(meshLog.current(u).parts.magazine, undefined);
    assert.deepEqual(meshLog.current(meshLog.redo(meshLog.redo(u))), cur);
    const bad = meshLog.push(l, { op: "param", key: "barrel.length", value: 9 });
    assert.equal(bad.ok, false); assert.equal(bad.log, l, "a refused op leaves the log unchanged");
  });
  it("replace (draft restore) must stay on the same mesh and legal class", () => {
    const d0 = docFor(), d1 = ok(applyMeshOp(d0, { op: "xform", part: "grip", mode: "set", t: [0, 0.01, 0] }));
    assert.equal(ok(applyMeshOp(d0, { op: "replace", doc: d1, label: "Restore draft" })).parts.grip.t[1], 0.01);
    assert.equal(applyMeshOp(d0, { op: "replace", doc: { ...d1, base: { ...d1.base, sha256: sha(CRATE) } }, label: "x" }).ok, false);
    assert.equal(applyMeshOp(d0, { op: "replace", doc: { ...d1, legal: { ...d1.legal, legalClass: "user-original" } }, label: "x" }).ok, false);
  });
});

describe("layer 3: template parameter sliders + deterministic block-out", () => {
  it("every slider is validated by the meshgen template's own schema", () => {
    const spec = getTemplate("rifle")!.example;
    const r = setParam("rifle", spec, "barrel.length", 0.613);
    assert.ok(r.ok); if (!r.ok) return;
    assert.equal((r.spec.barrel as { length: number }).length, 0.61, "snapped to the slider step");
    assert.equal(setParam("rifle", spec, "barrel.length", 0.01).ok, false);
    assert.equal(setParam("rifle", spec, "stock.style", "laser").ok, false);
    assert.equal(setParam("rifle", spec, "barrel.colour", 1).ok, false, "only the declared sliders");
    assert.equal(paramValue({}, paramsFor("rifle").find((p) => p.key === "magazine.capacity")!), 30, "untouched = the template default");
    const st = setParam("rifle", spec, "stock.style", "none"); assert.ok(st.ok);
    for (const id of ["rifle", "crate", "sword"]) for (const p of paramsFor(id)) assert.ok(getTemplate(id), `${id} ${p.key}`);
  });
  it("block-out: deterministic, uses the Blender template's part names, follows the sliders", () => {
    const spec = getTemplate("rifle")!.example;
    const a = blockout("rifle", spec), b = blockout("rifle", spec);
    assert.deepEqual(a.scene.pos, b.scene.pos);
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    for (const p of a.scene.parts) assert.ok(ms.mesh.scene.parts.some((q) => q.name === p.name), `${p.name} is a real rifle part`);
    const long = setParam("rifle", spec, "barrel.length", 0.8);
    if (!long.ok) throw new Error(long.error);
    const bx = (s: Record<string, unknown>) => blockoutBoxes("rifle", s).find((x) => x.part === "barrel")!.s[0];
    assert.ok(bx(long.spec) > bx(spec));
    const noStock = setParam("rifle", spec, "stock.style", "none");
    if (!noStock.ok) throw new Error(noStock.error);
    assert.ok(!blockoutBoxes("rifle", noStock.spec).some((x) => x.part === "stock"));
    const crate = blockout("crate", {}); assert.ok(crate.scene.parts.some((p) => p.name === "body") && crate.scene.parts.some((p) => p.name === "lid"));
  });
});

describe("layer 3: export targets from the adapter asset profiles (honest)", () => {
  it("Minecraft is 'no' for 3D meshes (no converter); planned games are listed as planned, never exportable", () => {
    assert.equal(canTakeMesh(minecraftAssetProfile).ok, false);
    const t = exportTargets(["albedo", "roughness"]);
    const mc = t.find((x) => x.game === "minecraft")!;
    assert.equal(mc.status, "no"); assert.match(mc.reason, /no glTF-to-Minecraft converter/);
    assert.equal(t.filter((x) => x.status === "yes").length, 0, "nothing can take a glTF mesh today");
    assert.ok(["fivem", "redm"].every((g) => t.find((x) => x.game === g)?.status === "planned"));
  });
  it("packing happens only at export, from the profile channel map; unknown channels are reported, never packed", () => {
    const p = packPlan(minecraftAssetProfile, ["albedo", "roughness", "mask"]);
    assert.equal(p.slots.length, 1); assert.deepEqual(p.slots[0].roles, ["albedo"]);
    assert.deepEqual(p.notShipped, ["roughness"], "mask is an authoring aid; roughness has no Minecraft slot");
  });
});

describe("layer 3: legal class badge + rules (lib/cyrus/assets3d/manifest.ts)", () => {
  it("game-derived: job-only, not redistributed, delta only, never in the library, cannot be saved", () => {
    const d = docFor({ legal: { legalClass: "game-derived", retention: "job", game: "fivem", derivedFrom: [sha(RIFLE)] }, base: { ...docFor().base, source: "upload", template: null } });
    const b = legalBadge(d);
    assert.equal(b.tone, "warn"); assert.equal(b.summary, "Game-derived, not redistributed.");
    assert.equal(b.library, "not shared"); assert.equal(b.rules.deliverable, "delta-only");
    assert.equal(retentionAllowsSave(d).ok, false);
    const ai = legalBadge(docFor());
    assert.equal(ai.tone, "ok"); assert.equal(ai.library, "eligible");
  });
});

describe("layer 3: part transforms about each part's own centre", () => {
  it("translation moves the centre; rotation and scale keep it fixed; overrides match parts by name", () => {
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    const s = ms.mesh.scene, c = partCentres(s), i = s.parts.findIndex((p) => p.name === "magazine");
    assert.ok(near(apply4(partMatrix({ ...IDENTITY_XFORM, r: [10, 20, 30], s: [2, 2, 2] }, c[i]), c[i]), c[i], 1e-9));
    assert.ok(near(apply4(partMatrix({ ...IDENTITY_XFORM, t: [0.1, 0, 0] }, c[i]), c[i]), [c[i][0] + 0.1, c[i][1], c[i][2]], 1e-9));
    const o = partOverrides({ magazine: { ...IDENTITY_XFORM, t: [0, -0.02, 0] } }, s);
    assert.deepEqual([...o.keys()], [i]);
    assert.deepEqual(orphanParts({ magazine: IDENTITY_XFORM, drum: IDENTITY_XFORM }, s), ["drum"]);
  });
});

// ------------------------------------------------------------------------------------------------ server
type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[] };
const PID = "cp0123456789abcdef0123";
function server(plan: unknown = "all", o: { meshgenOn?: boolean; legalClass?: string } = {}) {
  const mem: Mem = { projects: new Map([[PID, { id: PID, userId: "u1", namespace: "nx_r30mesh01", rootBuildId: "mb1", headRevisionId: null, title: null }]]), revs: [], assets: [] };
  let t = Date.parse("2026-10-11T00:00:00Z");
  const objects = new Map<string, Uint8Array>();
  const put = (b: Uint8Array) => { const k = `sha256/${sha(b)}`; objects.set(k, b); return k; };
  const glbKey = put(RIFLE);
  const tpl = getTemplate("rifle")!;
  const reqKey = put(new TextEncoder().encode(JSON.stringify({ v: 1, rung: "template", template: "rifle", spec: tpl.example, game: "fivem", category: "weapon-ranged", budget: { maxTriangles: 20000, maxMaterials: 8, lods: [], decimate: true }, render: { samples: 32 } })));
  const store: MeshServiceDeps["store"] = {
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq: mem.revs.length + 1, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: null };
      mem.revs.push(r); p.headRevisionId = r.id; return r;
    },
    async recordAsset(pid, a) {
      const hit = mem.assets.find((x) => x.projectId === pid && x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256);
      if (hit) return hit;
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) };
      mem.assets.push(row); return row;
    },
  };
  mem.assets.push({ id: "as0", projectId: PID, revisionId: "rev0", assetKey: "rifle_ak", kind: "model", sha256: sha(RIFLE), size: RIFLE.length, origin: "generated", mime: GLB_MIME, path: glbKey, provenance: { generator: "ai-mesh", legalClass: o.legalClass ?? "ai-generated-for-user", rung: "template", module: "rifle", moduleVersion: 1, requestKey: reqKey, game: "fivem" }, createdAt: new Date(t) });
  const drafts = new Map<string, { doc: unknown; baseAssetId: string | null; baseHeadId: string | null; updatedAt: Date }>();
  const queued: Record<string, unknown>[] = [];
  const deps: MeshServiceDeps = {
    store, planOf: async () => plan, objects: { get: async (k) => objects.get(k) ?? null },
    drafts: { get: async (p, u, k) => drafts.get(`${p}|${u}|${k}`) ?? null, put: async (r) => { const updatedAt = new Date(); drafts.set(`${r.projectId}|${r.ownerRef}|${r.assetKey}`, { ...r, updatedAt }); return { updatedAt }; }, drop: async (p, u, k) => { drafts.delete(`${p}|${u}|${k}`); } },
    rebuild: o.meshgenOn ? async (req) => { queued.push(req); return { ok: true, jobId: "job_9" }; } : null,
  };
  return { mem, deps, objects, queued, drafts };
}

describe("layer 3 server: plan gate (All models, server side, fail closed), stale checks, retention, rebuild, drafts", () => {
  it("viewing is never gated: list, open (materials from the glb, the template spec from the request), bytes", async () => {
    for (const plan of ["free", "saka", null, "nope"]) {
      const s = server(plan);
      const l = await listMeshes(s.deps, "u1", PID);
      assert.equal(l.meshes.length, 1); assert.equal(l.access.edit.ok, false);
      const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
      assert.equal(Object.keys(v.doc.materials).length, 5);
      assert.equal(v.doc.base.template?.id, "rifle"); assert.ok(v.doc.base.template?.spec.receiver);
      assert.equal(v.params.length, paramsFor("rifle").length);
      assert.equal(sha(await meshBytes(s.deps, "u1", PID, "rifle_ak")), sha(RIFLE));
    }
    await assert.rejects(listMeshes(server().deps, "u2", PID), (e: { status: number }) => e.status === 404, "another owner's project does not exist");
  });
  it("save: All models only; Saka = asset_locked, unknown plan = plan_unknown; stale head / base / edit -> 409", async () => {
    const s = server();
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "barrel", mode: "set", t: [0.02, 0, 0] }));
    for (const [plan, code] of [["saka", "asset_locked"], ["katara", "asset_locked"], [null, "plan_unknown"], ["weird", "plan_unknown"]] as const) {
      const x = server(plan);
      await assert.rejects(saveMeshEdit(x.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number; code: string }) => e.status === 403 && e.code === code, String(plan));
    }
    const r = await saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null });
    assert.equal(r.seq, 1);
    const row = s.mem.assets.at(-1)!;
    assert.equal(row.mime, "application/vnd.cyrus.mesh-edit+json"); assert.equal(row.origin, "edited");
    assert.equal((row.provenance as { meshSha256: string }).meshSha256, sha(RIFLE));
    assert.ok(!JSON.stringify(row.provenance).includes("glTF"), "the mesh bytes are never copied into the edit row");
    assert.equal(s.mem.revs.at(-1)!.manifest.at(-1)!.path, "assets/models/rifle_ak.meshedit.json");
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number }) => e.status === 409, "stale head");
    const again = await openMesh(s.deps, "u1", PID, "rifle_ak");
    assert.equal(again.mesh.edit?.assetId, r.assetId); assert.deepEqual(again.doc.parts.barrel.t, [0.02, 0, 0]);
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc: { ...doc, base: { ...doc.base, sha256: sha(CRATE) } }, baseEditId: r.assetId, expectedHeadId: again.headRevisionId }), (e: { status: number }) => e.status === 409);
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc: { ...doc, legal: { ...doc.legal, legalClass: "user-original" } }, baseEditId: r.assetId, expectedHeadId: again.headRevisionId }), (e: { status: number }) => e.status === 400, "the server's legal class wins");
  });
  it("game-derived content can be opened and edited in the session but never saved (job retention)", async () => {
    const s = server("all", { legalClass: "game-derived" });
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    assert.equal(v.doc.legal.retention, "job"); assert.deepEqual(v.doc.legal.derivedFrom, [sha(RIFLE)]);
    assert.equal(v.legal.summary, "Game-derived, not redistributed.");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "barrel", mode: "set", t: [0.02, 0, 0] }));
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number; code: string }) => e.status === 422 && e.code === "retention_job_only");
  });
  it("rebuild: gated, template-schema validated, OFF = 503 with the reason, ON = the same template with the original budget and 0 tokens", async () => {
    const spec = { ...getTemplate("rifle")!.example, barrel: { length: 0.6 } };
    await assert.rejects(rebuildMesh(server("saka", { meshgenOn: true }).deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec }), (e: { status: number }) => e.status === 403);
    await assert.rejects(rebuildMesh(server("all").deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec }), (e: { status: number; code: string }) => e.status === 503 && e.code === "rebuild_off");
    await assert.rejects(rebuildMesh(server("all", { meshgenOn: true }).deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: { barrel: { length: 7 } } }), (e: { status: number }) => e.status === 422);
    const on = server("all", { meshgenOn: true });
    const r = await rebuildMesh(on.deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec });
    assert.equal(r.jobId, "job_9");
    const q = on.queued[0] as { template: string; spec: { barrel: { length: number } }; budget: { maxTriangles: number }; estimate: { totalTokens: number }; rung: string };
    assert.deepEqual([q.rung, q.template, q.spec.barrel.length, q.budget.maxTriangles, q.estimate.totalTokens], ["template", "rifle", 0.6, 20000, 0]);
  });
  it("drafts: gated like any edit, read back never gated, dropped by a save", async () => {
    const s = server();
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "stock", mode: "set", t: [-0.03, 0, 0] }));
    await assert.rejects(putMeshDraft(server("saka").deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, baseHeadId: null }), (e: { status: number }) => e.status === 403);
    await putMeshDraft(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, baseHeadId: null });
    assert.deepEqual((await getMeshDraft(s.deps, "u1", PID, "rifle_ak"))?.doc.parts.stock.t, [-0.03, 0, 0]);
    await saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null });
    assert.equal(await getMeshDraft(s.deps, "u1", PID, "rifle_ak"), null);
  });
  it("http: no viewer = 404; a tampered stored mesh is never served", async () => {
    const s = server();
    const api = (viewer: boolean): MeshApiDeps => ({ viewer: async () => (viewer ? { userId: "u1", preview: true } as never : null), service: s.deps, rateLimit: () => ({ ok: true }) });
    assert.equal((await handleMesh(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(false))).status, 404);
    assert.equal((await handleMesh(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(true))).status, 200);
    assert.equal((await handleMesh(new Request("http://x"), { projectId: "bad", key: "rifle_ak" }, api(true))).status, 400);
    s.objects.set(s.mem.assets[0].path!, CRATE);
    assert.equal((await handleMeshGlb(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(true))).status, 409);
  });
  it("resolveMeshes: newest mesh row + newest edit; an edit on an older mesh is flagged stale, not dropped", () => {
    const s = server();
    const base = s.mem.assets[0];
    const d = docFor({ base: { ...docFor().base, sha256: sha(CRATE) } });
    s.mem.assets.push({ ...base, id: "as9", mime: "application/vnd.cyrus.mesh-edit+json", sha256: "e".repeat(64), origin: "edited", provenance: { doc: d }, createdAt: new Date(Date.parse("2026-10-12T00:00:00Z")) });
    const m = resolveMeshes(s.mem.assets)[0];
    assert.equal(m.edit?.assetId, "as9"); assert.match(m.edit?.stale ?? "", /rebuilt since/);
  });
});

toolu_01WJHYEz2hqnfEavsDLopS6E.content:
// Cyrus Model Studio LAYER 3 (feature/cyrus-r30-modelstudio): mesh retexture + light edit for glTF meshes. The doc,
// the op log (the same one the layer-2 editor uses), snapping and light-edit limits, per-channel lossless layers and
// island fills, template parameter sliders (validated by the meshgen schema) + block-out, the export-target picker
// from the adapter asset profiles (Minecraft = no for 3D), the legal-class rules, and the server: plan gate (All
// models, fail closed), stale checks, retention, rebuild without a model call, drafts. Real meshgen glbs as fixtures.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { checkMeshEditDoc, IDENTITY_XFORM, layersOf, newMeshEditDoc, type MeshEditDoc } from "../lib/cyrus/modelstudio/retex/doc";
import { applyMeshOp, meshLog } from "../lib/cyrus/modelstudio/retex/ops";
import { blockout, blockoutBoxes, paramsFor, paramValue, setParam } from "../lib/cyrus/modelstudio/retex/params";
import { canTakeMesh, exportTargets, packPlan } from "../lib/cyrus/modelstudio/retex/export";
import { legalBadge, retentionAllowsSave } from "../lib/cyrus/modelstudio/retex/legal";
import { partCentres, partMatrix, partOverrides, orphanParts } from "../lib/cyrus/modelstudio/retex/xform";
import { hexToLin, linToHex, meshScene, uvOverlap } from "../lib/cyrus/modelstudio/retex/scene";
import { getMeshDraft, listMeshes, meshBytes, openMesh, putMeshDraft, rebuildMesh, resolveMeshes, saveMeshEdit, GLB_MIME, type MeshServiceDeps } from "../lib/cyrus/modelstudio/retex/service";
import { handleMesh, handleMeshGlb, type MeshApiDeps } from "../lib/cyrus/modelstudio/retex/http";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { apply4 } from "../lib/cyrus/modelstudio/math";
import { getTemplate } from "../lib/cyrus/meshgen/templates";
import type { AssetRow, ProjectRow, RevRow } from "../lib/cyrus/studios/service";

const ROOT = path.resolve(__dirname, "..");
const glbOf = (n: string) => new Uint8Array(fs.readFileSync(path.join(ROOT, `test/fixtures/cyrus-meshes/${n}.glb`)));
const sha = (b: Uint8Array) => createHash("sha256").update(b).digest("hex");
const RIFLE = glbOf("rifle_ak"), CRATE = glbOf("crate_scifi");
const near = (a: number[], b: number[], e = 1e-9) => a.every((v, i) => Math.abs(v - b[i]) < e);
const ok = <T,>(r: { ok: true; doc: T } | { ok: false; error: string }) => { if (!r.ok) throw new Error(r.error); return r.doc; };

function docFor(o: Partial<MeshEditDoc> = {}): MeshEditDoc {
  const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
  if (!ms.ok) throw new Error(ms.error);
  const materials = Object.fromEntries(ms.mesh.gltf.materials.map((m) => [m.name, { baseColor: m.baseColor, metallic: m.metallic, roughness: m.roughness, emissive: m.emissive }]));
  const tpl = getTemplate("rifle")!;
  return { ...newMeshEditDoc({ name: "rifle_ak", tex: { w: 512, h: 512 }, materials, base: { sha256: sha(RIFLE), source: "meshgen", assetId: "as1", template: { id: "rifle", version: tpl.version, spec: tpl.example } }, legal: { legalClass: "ai-generated-for-user", retention: "project", game: null, derivedFrom: [] } }), ...o };
}

describe("layer 3: the real meshgen glb as the shared scene", () => {
  it("named parts, material slots per part, UV islands, an honest overlap check", () => {
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    assert.ok(ms.ok);
    if (!ms.ok) return;
    assert.deepEqual(ms.mesh.scene.parts.map((p) => p.name), ["barrel", "grip", "handguard", "magazine", "receiver", "sights", "stock"]);
    assert.equal(ms.mesh.gltf.materials.length, 5);
    assert.ok(ms.mesh.slots.every((s) => s && s.startsWith("mat_")), "every part has its material slot");
    assert.ok(ms.mesh.islands.length >= ms.mesh.scene.parts.length);
    assert.ok(ms.mesh.islands.every((i) => i.texels > 0 || i.tris > 0));
    const ov = uvOverlap(ms.mesh.islands, 512);
    assert.ok(ov.texels >= 0 && Array.isArray(ov.parts), "overlap is measured, not assumed");
    assert.equal(linToHex(hexToLin("#e8742a")), "#e8742a", "sRGB <-> linear round trip for the colour fields");
  });
});

describe("layer 3: doc + ops + the one op log", () => {
  it("validates: game-derived must be job-only and name its base; params only on template meshes", () => {
    assert.ok(checkMeshEditDoc(docFor()).ok);
    assert.equal(checkMeshEditDoc({ ...docFor(), legal: { legalClass: "game-derived", retention: "project", game: "fivem", derivedFrom: [sha(RIFLE)] } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), legal: { legalClass: "game-derived", retention: "job", game: "fivem", derivedFrom: [] } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), base: { ...docFor().base, template: null }, params: { barrel: { length: 0.5 } } }).ok, false);
    assert.equal(checkMeshEditDoc({ ...docFor(), extra: 1 }).ok, false, "strict");
  });
  it("part transforms snap, stay inside the light-edit limits, and an identity transform removes the entry", () => {
    const d0 = docFor();
    const d1 = ok(applyMeshOp(d0, { op: "xform", part: "barrel", mode: "set", t: [0.1234, 0, 0], snap: { move: 0.05 } }));
    assert.deepEqual(d1.parts.barrel.t, [0.1, 0, 0]);
    const d2 = ok(applyMeshOp(d1, { op: "xform", part: "barrel", mode: "add", r: [0, 0, 20], snap: { rotate: 15 } }));
    assert.deepEqual(d2.parts.barrel.r, [0, 0, 15]);
    assert.equal(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", t: [50, 0, 0] }).ok, false, "10 m light-edit limit");
    assert.equal(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", s: [0, 1, 1] }).ok, false);
    assert.equal(applyMeshOp(d2, { op: "xform", part: "nope", mode: "set", t: [0, 0, 0] }, { parts: ["barrel"], slots: [] }).ok, false);
    const back = ok(applyMeshOp(d2, { op: "xform", part: "barrel", mode: "set", t: [0, 0, 0], r: [0, 0, 0] }));
    assert.equal(back.parts.barrel, undefined);
    assert.equal(applyMeshOp(back, { op: "reset", part: "barrel" }).ok, false);
  });
  it("materials are validated; channel layers are lossless and per channel; island fill writes only that island", () => {
    const d0 = docFor();
    const slot = Object.keys(d0.materials)[0];
    assert.equal(applyMeshOp(d0, { op: "material", slot, props: { roughness: 2 } }).ok, false);
    const d1 = ok(applyMeshOp(d0, { op: "material", slot, props: { roughness: 0.2, metallic: 0.9 } }));
    assert.equal(d1.materials[slot].roughness, 0.2);
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    const is = ms.mesh.islands.find((i) => i.texels > 20)!;
    const d2 = ok(applyMeshOp(d1, { op: "paint", p: { t: "layer.add", id: "roughness_fill", name: "Roughness edits", channel: "roughness" } }));
    const d3 = ok(applyMeshOp(d2, { op: "paint", p: { t: "fill", layer: "roughness_fill", color: [64, 64, 64], spans: is.spans } }));
    const L = layersOf(d3).layers[0];
    let n = 0; for (let i = 3; i < L.px.length; i += 4) if (L.px[i]) n++;
    assert.equal(n, is.texels, "exactly the island's texels");
    assert.equal(d3.layers.filter((l) => l.channel === "roughness").length, 1);
    assert.ok(checkMeshEditDoc(d3).ok, "a painted doc is still a valid doc (lossless rle)");
  });
  it("the op log: undo/redo O(1), replay from the base gives the same doc byte for byte", () => {
    let l = meshLog.init(docFor());
    for (const op of [
      { op: "xform", part: "stock", mode: "set", t: [-0.05, 0, 0] },
      { op: "material", slot: Object.keys(docFor().materials)[1], props: { metallic: 0.5 } },
      { op: "param", key: "barrel.length", value: 0.55 },
      { op: "xform", part: "magazine", mode: "add", r: [0, 0, 10] },
    ] as const) { const r = meshLog.push(l, op as never); assert.ok(r.ok, !r.ok ? r.error : ""); l = r.log; }
    assert.equal(meshLog.unsaved(l), 4);
    const cur = meshLog.current(l);
    assert.deepEqual(meshLog.replay(l.base, l.entries), cur);
    const u = meshLog.undo(meshLog.undo(l));
    assert.equal(meshLog.current(u).parts.magazine, undefined);
    assert.deepEqual(meshLog.current(meshLog.redo(meshLog.redo(u))), cur);
    const bad = meshLog.push(l, { op: "param", key: "barrel.length", value: 9 });
    assert.equal(bad.ok, false); assert.equal(bad.log, l, "a refused op leaves the log unchanged");
  });
  it("replace (draft restore) must stay on the same mesh and legal class", () => {
    const d0 = docFor(), d1 = ok(applyMeshOp(d0, { op: "xform", part: "grip", mode: "set", t: [0, 0.01, 0] }));
    assert.equal(ok(applyMeshOp(d0, { op: "replace", doc: d1, label: "Restore draft" })).parts.grip.t[1], 0.01);
    assert.equal(applyMeshOp(d0, { op: "replace", doc: { ...d1, base: { ...d1.base, sha256: sha(CRATE) } }, label: "x" }).ok, false);
    assert.equal(applyMeshOp(d0, { op: "replace", doc: { ...d1, legal: { ...d1.legal, legalClass: "user-original" } }, label: "x" }).ok, false);
  });
});

describe("layer 3: template parameter sliders + deterministic block-out", () => {
  it("every slider is validated by the meshgen template's own schema", () => {
    const spec = getTemplate("rifle")!.example;
    const r = setParam("rifle", spec, "barrel.length", 0.613);
    assert.ok(r.ok); if (!r.ok) return;
    assert.equal((r.spec.barrel as { length: number }).length, 0.61, "snapped to the slider step");
    assert.equal(setParam("rifle", spec, "barrel.length", 0.01).ok, false);
    assert.equal(setParam("rifle", spec, "stock.style", "laser").ok, false);
    assert.equal(setParam("rifle", spec, "barrel.colour", 1).ok, false, "only the declared sliders");
    assert.equal(paramValue({}, paramsFor("rifle").find((p) => p.key === "magazine.capacity")!), 30, "untouched = the template default");
    const st = setParam("rifle", spec, "stock.style", "none"); assert.ok(st.ok);
    for (const id of ["rifle", "crate", "sword"]) for (const p of paramsFor(id)) assert.ok(getTemplate(id), `${id} ${p.key}`);
  });
  it("block-out: deterministic, uses the Blender template's part names, follows the sliders", () => {
    const spec = getTemplate("rifle")!.example;
    const a = blockout("rifle", spec), b = blockout("rifle", spec);
    assert.deepEqual(a.scene.pos, b.scene.pos);
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    for (const p of a.scene.parts) assert.ok(ms.mesh.scene.parts.some((q) => q.name === p.name), `${p.name} is a real rifle part`);
    const long = setParam("rifle", spec, "barrel.length", 0.8);
    if (!long.ok) throw new Error(long.error);
    const bx = (s: Record<string, unknown>) => blockoutBoxes("rifle", s).find((x) => x.part === "barrel")!.s[0];
    assert.ok(bx(long.spec) > bx(spec));
    const noStock = setParam("rifle", spec, "stock.style", "none");
    if (!noStock.ok) throw new Error(noStock.error);
    assert.ok(!blockoutBoxes("rifle", noStock.spec).some((x) => x.part === "stock"));
    const crate = blockout("crate", {}); assert.ok(crate.scene.parts.some((p) => p.name === "body") && crate.scene.parts.some((p) => p.name === "lid"));
  });
});

describe("layer 3: export targets from the adapter asset profiles (honest)", () => {
  it("Minecraft is 'no' for 3D meshes (no converter); planned games are listed as planned, never exportable", () => {
    assert.equal(canTakeMesh(minecraftAssetProfile).ok, false);
    const t = exportTargets(["albedo", "roughness"]);
    const mc = t.find((x) => x.game === "minecraft")!;
    assert.equal(mc.status, "no"); assert.match(mc.reason, /no glTF-to-Minecraft converter/);
    assert.equal(t.filter((x) => x.status === "yes").length, 0, "nothing can take a glTF mesh today");
    assert.ok(["fivem", "redm"].every((g) => t.find((x) => x.game === g)?.status === "planned"));
  });
  it("packing happens only at export, from the profile channel map; unknown channels are reported, never packed", () => {
    const p = packPlan(minecraftAssetProfile, ["albedo", "roughness", "mask"]);
    assert.equal(p.slots.length, 1); assert.deepEqual(p.slots[0].roles, ["albedo"]);
    assert.deepEqual(p.notShipped, ["roughness"], "mask is an authoring aid; roughness has no Minecraft slot");
  });
});

describe("layer 3: legal class badge + rules (lib/cyrus/assets3d/manifest.ts)", () => {
  it("game-derived: job-only, not redistributed, delta only, never in the library, cannot be saved", () => {
    const d = docFor({ legal: { legalClass: "game-derived", retention: "job", game: "fivem", derivedFrom: [sha(RIFLE)] }, base: { ...docFor().base, source: "upload", template: null } });
    const b = legalBadge(d);
    assert.equal(b.tone, "warn"); assert.equal(b.summary, "Game-derived, not redistributed.");
    assert.equal(b.library, "not shared"); assert.equal(b.rules.deliverable, "delta-only");
    assert.equal(retentionAllowsSave(d).ok, false);
    const ai = legalBadge(docFor());
    assert.equal(ai.tone, "ok"); assert.equal(ai.library, "eligible");
  });
});

describe("layer 3: part transforms about each part's own centre", () => {
  it("translation moves the centre; rotation and scale keep it fixed; overrides match parts by name", () => {
    const ms = meshScene("rifle_ak", RIFLE, { w: 512, h: 512 });
    if (!ms.ok) throw new Error(ms.error);
    const s = ms.mesh.scene, c = partCentres(s), i = s.parts.findIndex((p) => p.name === "magazine");
    assert.ok(near(apply4(partMatrix({ ...IDENTITY_XFORM, r: [10, 20, 30], s: [2, 2, 2] }, c[i]), c[i]), c[i], 1e-9));
    assert.ok(near(apply4(partMatrix({ ...IDENTITY_XFORM, t: [0.1, 0, 0] }, c[i]), c[i]), [c[i][0] + 0.1, c[i][1], c[i][2]], 1e-9));
    const o = partOverrides({ magazine: { ...IDENTITY_XFORM, t: [0, -0.02, 0] } }, s);
    assert.deepEqual([...o.keys()], [i]);
    assert.deepEqual(orphanParts({ magazine: IDENTITY_XFORM, drum: IDENTITY_XFORM }, s), ["drum"]);
  });
});

// ------------------------------------------------------------------------------------------------ server
type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[] };
const PID = "cp0123456789abcdef0123";
function server(plan: unknown = "all", o: { meshgenOn?: boolean; legalClass?: string } = {}) {
  const mem: Mem = { projects: new Map([[PID, { id: PID, userId: "u1", namespace: "nx_r30mesh01", rootBuildId: "mb1", headRevisionId: null, title: null }]]), revs: [], assets: [] };
  let t = Date.parse("2026-10-11T00:00:00Z");
  const objects = new Map<string, Uint8Array>();
  const put = (b: Uint8Array) => { const k = `sha256/${sha(b)}`; objects.set(k, b); return k; };
  const glbKey = put(RIFLE);
  const tpl = getTemplate("rifle")!;
  const reqKey = put(new TextEncoder().encode(JSON.stringify({ v: 1, rung: "template", template: "rifle", spec: tpl.example, game: "fivem", category: "weapon-ranged", budget: { maxTriangles: 20000, maxMaterials: 8, lods: [], decimate: true }, render: { samples: 32 } })));
  const store: MeshServiceDeps["store"] = {
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq: mem.revs.length + 1, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: null };
      mem.revs.push(r); p.headRevisionId = r.id; return r;
    },
    async recordAsset(pid, a) {
      const hit = mem.assets.find((x) => x.projectId === pid && x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256);
      if (hit) return hit;
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) };
      mem.assets.push(row); return row;
    },
  };
  mem.assets.push({ id: "as0", projectId: PID, revisionId: "rev0", assetKey: "rifle_ak", kind: "model", sha256: sha(RIFLE), size: RIFLE.length, origin: "generated", mime: GLB_MIME, path: glbKey, provenance: { generator: "ai-mesh", legalClass: o.legalClass ?? "ai-generated-for-user", rung: "template", module: "rifle", moduleVersion: 1, requestKey: reqKey, game: "fivem" }, createdAt: new Date(t) });
  const drafts = new Map<string, { doc: unknown; baseAssetId: string | null; baseHeadId: string | null; updatedAt: Date }>();
  const queued: Record<string, unknown>[] = [];
  const deps: MeshServiceDeps = {
    store, planOf: async () => plan, objects: { get: async (k) => objects.get(k) ?? null },
    drafts: { get: async (p, u, k) => drafts.get(`${p}|${u}|${k}`) ?? null, put: async (r) => { const updatedAt = new Date(); drafts.set(`${r.projectId}|${r.ownerRef}|${r.assetKey}`, { ...r, updatedAt }); return { updatedAt }; }, drop: async (p, u, k) => { drafts.delete(`${p}|${u}|${k}`); } },
    rebuild: o.meshgenOn ? async (req) => { queued.push(req); return { ok: true, jobId: "job_9" }; } : null,
  };
  return { mem, deps, objects, queued, drafts };
}

describe("layer 3 server: plan gate (All models, server side, fail closed), stale checks, retention, rebuild, drafts", () => {
  it("viewing is never gated: list, open (materials from the glb, the template spec from the request), bytes", async () => {
    for (const plan of ["free", "saka", null, "nope"]) {
      const s = server(plan);
      const l = await listMeshes(s.deps, "u1", PID);
      assert.equal(l.meshes.length, 1); assert.equal(l.access.edit.ok, false);
      const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
      assert.equal(Object.keys(v.doc.materials).length, 5);
      assert.equal(v.doc.base.template?.id, "rifle"); assert.ok(v.doc.base.template?.spec.receiver);
      assert.equal(v.params.length, paramsFor("rifle").length);
      assert.equal(sha(await meshBytes(s.deps, "u1", PID, "rifle_ak")), sha(RIFLE));
    }
    await assert.rejects(listMeshes(server().deps, "u2", PID), (e: { status: number }) => e.status === 404, "another owner's project does not exist");
  });
  it("save: All models only; Saka = asset_locked, unknown plan = plan_unknown; stale head / base / edit -> 409", async () => {
    const s = server();
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "barrel", mode: "set", t: [0.02, 0, 0] }));
    for (const [plan, code] of [["saka", "asset_locked"], ["katara", "asset_locked"], [null, "plan_unknown"], ["weird", "plan_unknown"]] as const) {
      const x = server(plan);
      await assert.rejects(saveMeshEdit(x.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number; code: string }) => e.status === 403 && e.code === code, String(plan));
    }
    const r = await saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null });
    assert.equal(r.seq, 1);
    const row = s.mem.assets.at(-1)!;
    assert.equal(row.mime, "application/vnd.cyrus.mesh-edit+json"); assert.equal(row.origin, "edited");
    assert.equal((row.provenance as { meshSha256: string }).meshSha256, sha(RIFLE));
    assert.ok(!JSON.stringify(row.provenance).includes("glTF"), "the mesh bytes are never copied into the edit row");
    assert.equal(s.mem.revs.at(-1)!.manifest.at(-1)!.path, "assets/models/rifle_ak.meshedit.json");
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number }) => e.status === 409, "stale head");
    const again = await openMesh(s.deps, "u1", PID, "rifle_ak");
    assert.equal(again.mesh.edit?.assetId, r.assetId); assert.deepEqual(again.doc.parts.barrel.t, [0.02, 0, 0]);
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc: { ...doc, base: { ...doc.base, sha256: sha(CRATE) } }, baseEditId: r.assetId, expectedHeadId: again.headRevisionId }), (e: { status: number }) => e.status === 409);
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc: { ...doc, legal: { ...doc.legal, legalClass: "user-original" } }, baseEditId: r.assetId, expectedHeadId: again.headRevisionId }), (e: { status: number }) => e.status === 400, "the server's legal class wins");
  });
  it("game-derived content can be opened and edited in the session but never saved (job retention)", async () => {
    const s = server("all", { legalClass: "game-derived" });
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    assert.equal(v.doc.legal.retention, "job"); assert.deepEqual(v.doc.legal.derivedFrom, [sha(RIFLE)]);
    assert.equal(v.legal.summary, "Game-derived, not redistributed.");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "barrel", mode: "set", t: [0.02, 0, 0] }));
    await assert.rejects(saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null }), (e: { status: number; code: string }) => e.status === 422 && e.code === "retention_job_only");
  });
  it("rebuild: gated, template-schema validated, OFF = 503 with the reason, ON = the same template with the original budget and 0 tokens", async () => {
    const spec = { ...getTemplate("rifle")!.example, barrel: { length: 0.6 } };
    await assert.rejects(rebuildMesh(server("saka", { meshgenOn: true }).deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec }), (e: { status: number }) => e.status === 403);
    await assert.rejects(rebuildMesh(server("all").deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec }), (e: { status: number; code: string }) => e.status === 503 && e.code === "rebuild_off");
    await assert.rejects(rebuildMesh(server("all", { meshgenOn: true }).deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: { barrel: { length: 7 } } }), (e: { status: number }) => e.status === 422);
    const on = server("all", { meshgenOn: true });
    const r = await rebuildMesh(on.deps, { userId: "u1", projectId: PID, key: "rifle_ak", params: spec });
    assert.equal(r.jobId, "job_9");
    const q = on.queued[0] as { template: string; spec: { barrel: { length: number } }; budget: { maxTriangles: number }; estimate: { totalTokens: number }; rung: string };
    assert.deepEqual([q.rung, q.template, q.spec.barrel.length, q.budget.maxTriangles, q.estimate.totalTokens], ["template", "rifle", 0.6, 20000, 0]);
  });
  it("drafts: gated like any edit, read back never gated, dropped by a save", async () => {
    const s = server();
    const v = await openMesh(s.deps, "u1", PID, "rifle_ak");
    const doc = ok(applyMeshOp(v.doc, { op: "xform", part: "stock", mode: "set", t: [-0.03, 0, 0] }));
    await assert.rejects(putMeshDraft(server("saka").deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, baseHeadId: null }), (e: { status: number }) => e.status === 403);
    await putMeshDraft(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, baseHeadId: null });
    assert.deepEqual((await getMeshDraft(s.deps, "u1", PID, "rifle_ak"))?.doc.parts.stock.t, [-0.03, 0, 0]);
    await saveMeshEdit(s.deps, { userId: "u1", projectId: PID, key: "rifle_ak", doc, baseEditId: null, expectedHeadId: null });
    assert.equal(await getMeshDraft(s.deps, "u1", PID, "rifle_ak"), null);
  });
  it("http: no viewer = 404; a tampered stored mesh is never served", async () => {
    const s = server();
    const api = (viewer: boolean): MeshApiDeps => ({ viewer: async () => (viewer ? { userId: "u1", preview: true } as never : null), service: s.deps, rateLimit: () => ({ ok: true }) });
    assert.equal((await handleMesh(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(false))).status, 404);
    assert.equal((await handleMesh(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(true))).status, 200);
    assert.equal((await handleMesh(new Request("http://x"), { projectId: "bad", key: "rifle_ak" }, api(true))).status, 400);
    s.objects.set(s.mem.assets[0].path!, CRATE);
    assert.equal((await handleMeshGlb(new Request("http://x"), { projectId: PID, key: "rifle_ak" }, api(true))).status, 409);
  });
  it("resolveMeshes: newest mesh row + newest edit; an edit on an older mesh is flagged stale, not dropped", () => {
    const s = server();
    const base = s.mem.assets[0];
    const d = docFor({ base: { ...docFor().base, sha256: sha(CRATE) } });
    s.mem.assets.push({ ...base, id: "as9", mime: "application/vnd.cyrus.mesh-edit+json", sha256: "e".repeat(64), origin: "edited", provenance: { doc: d }, createdAt: new Date(Date.parse("2026-10-12T00:00:00Z")) });
    const m = resolveMeshes(s.mem.assets)[0];
    assert.equal(m.edit?.assetId, "as9"); assert.match(m.edit?.stale ?? "", /rebuilt since/);
  });
});

