// Model Studio L2: undo / redo for the cuboid + bone editor. Pure + client-safe. It is THE Model Studio op log
// (../oplog.ts, shared with the layer-3 mesh studio) instantiated for ModelDoc + editor ops; this file keeps the
// editor's names. The log is { base, entries, at }: the document at step i is replay(base, entries[0..i)); a per-step
// document cache makes undo/redo O(1); replay() rebuilds any step from the base alone (the test suite proves both
// agree byte for byte). One gizmo drag, one field commit, one key, one accepted AI candidate = ONE entry. At most
// MAX_STEPS entries: older ones fold into the base.
import { canonicalJson } from "./canonical";
import { applyOp, type Op } from "./ops";
import type { ModelDoc } from "./doc";
import { MAX_STEPS, opLog, type Log, type LogEntry as GenericEntry } from "../oplog";

export { MAX_STEPS };
export type LogEntry = GenericEntry<Op>;
export type OpLog = Log<ModelDoc, Op>;

const L = opLog<ModelDoc, Op>((doc, op) => applyOp(doc, op));

export const logInit = (base: ModelDoc): OpLog => L.init(base);
export const currentDoc = (l: OpLog): ModelDoc => L.current(l);
export const canUndo = (l: OpLog) => L.canUndo(l);
export const canRedo = (l: OpLog) => L.canRedo(l);
/** Apply + record one op (drops any redo branch). A refused op leaves the log unchanged and says why. */
export const logApply = (l: OpLog, op: Op, max = MAX_STEPS) => L.push(l, op, max);
export const logUndo = (l: OpLog): OpLog => L.undo(l);
export const logRedo = (l: OpLog): OpLog => L.redo(l);
export const logJump = (l: OpLog, at: number): OpLog => L.jump(l, at);
/** Unsaved = the current document differs from the base it was opened (or last saved) as. */
export const unsavedCount = (l: OpLog) => L.unsaved(l);
/** Rebuild the document at step `upTo` from the base and the recorded ops only (deterministic). */
export const replay = (base: ModelDoc, entries: readonly LogEntry[], upTo = entries.length): ModelDoc => L.replay(base, entries, upTo);
/** A saved revision becomes the new base (history before it is dropped: the revision list is the long-term history). */
export const logRebase = (doc: ModelDoc): OpLog => logInit(doc);
/** Byte-stable serialisation of a document (sorted keys) for hashing, saving and comparisons. */
export const serializeDoc = (d: ModelDoc) => canonicalJson(d);
EOF
