// Cyrus Model Studio layer 3 (mesh retexture + light edit): screenshots + real edits, run ON node-2 against the
// devhost dev server (WebGL via SwiftShader). Files are prefixed layer3-.
//   devhost db reset && devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > TOKENS ; devhost run -- npx tsx scripts/cyrus/mesh-studio-fixtures.ts TOKENS
//   devhost env set CYRUS_MODEL_DRAFTS=memory ; devhost dev
//   devhost run -- node test/e2e/cyrus-mesh-studio.shots.mjs TOKENS OUT [only]
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".mesh-shots", only = ""] = process.argv;
const want = (n) => !only || only.split(",").includes(n);
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"] });
let failures = 0;

async function session(who, { theme = "dark", narrow = false, q = "" } = {}) {
  const c = await browser.newContext({ viewport: narrow ? { width: 390, height: 844 } : { width: 1440, height: 900 }, deviceScaleFactor: narrow ? 2 : 1, colorScheme: theme, reducedMotion: "reduce" });
  await c.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await c.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-sound", "off"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource.*(404|503)/.test(m.text())) errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(`${BASE}/dashboard/cyrus/${T[who].buildId}/studio/mesh${q}`, { waitUntil: "networkidle", timeout: 240000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForSelector(narrow ? ".ms-narrow canvas" : ".mx-ws .ms-cv", { timeout: 90000 }).catch((e) => errs.push("wait " + String(e).slice(0, 120)));
  await page.waitForTimeout(1500);
  return { c, page, errs };
}
async function done(name, s, info = "") {
  await s.page.screenshot({ path: `${out}/${name}.png`, timeout: 120000 });
  if (s.errs.length) failures++;
  console.log(`${out}/${name}.png`, info, s.errs.length ? "ERR " + s.errs.join(" | ").slice(0, 600) : "");
  await s.c.close();
}
const part = (p, name) => p.locator(".mx-part").filter({ hasText: new RegExp(`^${name}`) }).first();
async function edit(p) {
  // select the magazine, move it 2 cm down and turn it 15 degrees; change the body roughness; fill an island
  await part(p, "magazine").click();
  const y = p.getByLabel("Move Y"); await y.fill("-0.02"); await y.press("Enter");
  const rz = p.getByLabel("Rotate Z"); await rz.fill("15"); await rz.press("Enter");
  await p.locator(".mx-slot").filter({ hasText: "mat_furniture" }).click();
  await p.getByLabel("Roughness").fill("0.25");
  await p.locator(".mx-uvbox canvas").click({ position: { x: 60, y: 60 } }).catch(() => {});
}

if (want("dark")) {
  const s = await session("all", { q: "?mesh=rifle_ak" });
  try { await edit(s.page); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("layer3-dark", s);
}
if (want("light")) {
  const s = await session("all", { theme: "light", q: "?mesh=rifle_ak" });
  try { await edit(s.page); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("layer3-light", s);
}
if (want("params")) {
  // a template slider: longer barrel + no stock -> the block-out preview; then Rebuild (worker off here = honest 503 toast)
  const s = await session("all", { q: "?mesh=rifle_ak" });
  try {
    const bl = s.page.getByLabel("Barrel length"); await bl.focus(); for (let i = 0; i < 18; i++) await bl.press("ArrowRight");
    await s.page.getByLabel("Stock type").selectOption("folding_wire");
    await s.page.waitForTimeout(600);
    await s.page.getByRole("button", { name: "Rebuild mesh" }).click();
    await s.page.waitForTimeout(800);
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("layer3-dark-params-blockout", s);
}
if (want("save")) {
  // a real save through the API (All models), then reopen: the edit is the saved revision
  const s = await session("all", { q: "?mesh=crate_scifi" });
  try {
    await part(s.page, "lid").click();
    const y = s.page.getByLabel("Move Y"); await y.fill("0.15"); await y.press("Enter");
    const rx = s.page.getByLabel("Rotate X"); await rx.fill("-30"); await rx.press("Enter");
    await s.page.getByRole("button", { name: "Save revision" }).click();
    await s.page.waitForTimeout(2500);
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  const toast = await s.page.locator(".cys-toast, [role=status]").allInnerTexts().catch(() => []);
  await done("layer3-dark-saved", s, JSON.stringify(toast).slice(0, 200));
}
if (want("gamederived")) {
  const s = await session("all", { q: "?mesh=sedan_template" });
  await done("layer3-dark-game-derived", s);
}
if (want("saka")) {
  const s = await session("saka", { q: "?mesh=rifle_ak" });
  await done("layer3-dark-locked-saka", s);
}
if (want("phone")) {
  // make a draft on a "computer", then review it on a phone (dark + light)
  const d = await session("all", { q: "?mesh=rifle_ak" });
  try { await edit(d.page); await d.page.waitForTimeout(6500); } catch (e) { d.errs.push("act " + String(e).slice(0, 200)); }
  await d.c.close();
  for (const theme of ["dark", "light"]) {
    const s = await session("all", { theme, narrow: true, q: "?mesh=rifle_ak" });
    await done(`layer3-phone-${theme}`, s);
  }
}
await browser.close();
console.log(failures ? `${failures} shots with errors` : "all shots clean");

