1	// Cyrus Model Studio LAYER 3: the LEGAL-CLASS badge and the rules it implies, straight from the canonical ledger
2	// (lib/cyrus/assets3d/manifest.ts ledgerRules + libraryEligible). Pure + client-safe. The UI only shows this; the
3	// server enforces the same rules (./service.ts): game-derived content is kept for the job only, never enters the
4	// library, is never redistributed, and only the person's own changes (a delta) can ship.
5	import { ledgerRules, libraryEligible, type LedgerRules, type LegalClass } from "../../assets3d/ledger";
6	import type { MeshEditDoc } from "./doc";
7	
8	export type LegalBadge = { label: string; tone: "ok" | "warn"; summary: string; lines: string[]; rules: LedgerRules; library: "eligible" | "not shared" };
9	
10	const LABEL: Record<LegalClass, string> = {
11	  "user-original": "Your own", "ai-generated-for-user": "AI-made for you", "platform-library": "Library (CC0)", "third-party-licensed": "Third-party licence", "game-derived": "Game-derived",
12	};
13	
14	export function legalBadge(doc: Pick<MeshEditDoc, "legal" | "base">): LegalBadge {
15	  const c = doc.legal.legalClass;
16	  const rules = ledgerRules(c);
17	  const source = doc.base.source === "meshgen" ? "ai" : doc.base.source === "library" ? "library" : doc.base.source;
18	  const eligible = libraryEligible({ legalClass: c, provenance: { source, derivedFrom: doc.legal.derivedFrom } });
19	  const lines: string[] = [];
20	  if (!rules.storeBeyondJob) lines.push("Kept for this session only (job retention), deleted when it ends.");
21	  if (!rules.redistribute) lines.push("Never redistributed: the base file is not stored, shared or shipped.");
22	  if (rules.deliverable === "delta-only") lines.push("Only your changes ship (a delta); players use their own game files.");
23	  lines.push(eligible ? "Eligible for the community library after the content checks." : "Not shared to the community library.");
24	  const summary = c === "game-derived" ? "Game-derived, not redistributed." : c === "third-party-licensed" ? "Licensed to you; not redistributed." : c === "ai-generated-for-user" ? "Made for you by Cyrus." : c === "platform-library" ? "From the Cyrus library (CC0)." : "Made by you.";
25	  return { label: LABEL[c], tone: c === "game-derived" || c === "third-party-licensed" ? "warn" : "ok", summary, lines, rules, library: eligible ? "eligible" : "not shared" };
26	}

